def _get_instrument_tagger():
    """Lazily load a pretrained PANNs (Pretrained Audio Neural Networks)
    AudioSet tagger. Optional: if panns_inference isn't installed, tagging is
    skipped everywhere it's used and the rest of the pipeline is unaffected.
    Returns None if unavailable."""
    global _INSTRUMENT_TAGGER, _INSTRUMENT_TAGGER_LABELS, INSTRUMENT_TAGGER_IMPORT_ERROR

    if _INSTRUMENT_TAGGER is False:
        return None
    if _INSTRUMENT_TAGGER is not None:
        return _INSTRUMENT_TAGGER

    try:
        with quiet_stdout():
            from panns_inference import AudioTagging
            from panns_inference.config import labels as panns_labels
            tagger = AudioTagging(checkpoint_path=None, device="cpu")
        _INSTRUMENT_TAGGER = tagger
        _INSTRUMENT_TAGGER_LABELS = [str(l).strip().lower() for l in panns_labels]
        return _INSTRUMENT_TAGGER
    except Exception as e:
        INSTRUMENT_TAGGER_IMPORT_ERROR = str(e)
        _INSTRUMENT_TAGGER = False
        return None


def _peak_normalize(y, target_peak=0.95):
    """Peak-normalize a mono waveform in place-ish (returns a new array).
    No-ops on near-silent audio to avoid amplifying noise floor into
    false-positive tags."""
    if y is None or len(y) == 0:
        return y
    peak = float(np.max(np.abs(y)))
    if not np.isfinite(peak) or peak < 1e-6:
        return y
    return y * (target_peak / peak)


def _panns_cache_key(audio_path, window_seconds, hop_seconds, max_windows, normalize):
    """Identity for a set of raw per-window PANNs probabilities: the file
    (path + size + mtime, so a re-encoded/replaced temp file at the same path
    never returns stale rows) plus the windowing parameters."""
    try:
        st = os.stat(audio_path)
        sig = (int(st.st_size), int(st.st_mtime))
    except Exception:
        sig = (None, None)
    return (
        os.path.abspath(str(audio_path)),
        sig[0],
        sig[1],
        round(float(window_seconds or 0.0), 3),
        round(float(hop_seconds or 0.0), 3),
        int(max_windows or 0),
        bool(normalize),
    )


def _panns_window_starts(n_samples, sr, window_seconds, hop_seconds, max_windows):
    """Window start/end sample indices covering the WHOLE clip.

    Previously windows marched left-to-right at a fixed hop and stopped dead
    once max_windows was reached, so everything after roughly
    (max_windows * hop) seconds was never analysed -- 43% of a 6-minute track
    went unseen, making late-entering instruments undetectable. When the
    hop-spaced layout would overrun the budget, starts are spread evenly
    across the entire file instead, trading a slightly larger effective hop
    for complete end-to-end coverage.

    Returns [(start_sample, end_sample, start_seconds), ...].
    """
    if n_samples <= 0 or sr <= 0:
        return []

    duration = n_samples / float(sr)
    if not window_seconds or duration <= window_seconds:
        return [(0, n_samples, 0.0)]

    win_n = int(window_seconds * sr)
    hop_n = max(1, int((hop_seconds or window_seconds) * sr))
    max_windows = int(max_windows or 0) or 1
    last_start = max(0, n_samples - win_n)

    needed = int(last_start // hop_n) + 1
    if INSTRUMENT_TAG_EVEN_COVERAGE and needed > max_windows:
        # Budget-constrained: spread evenly over the whole file.
        starts = [
            int(round(last_start * i / float(max_windows - 1)))
            for i in range(max_windows)
        ] if max_windows > 1 else [0]
    else:
        starts = list(range(0, last_start + 1, hop_n))
        if starts and starts[-1] < last_start:
            starts.append(last_start)
        starts = starts[:max_windows]

    windows = []
    seen = set()
    for s in starts:
        s = max(0, min(int(s), last_start))
        if s in seen:
            continue
        seen.add(s)
        e = min(s + win_n, n_samples)
        if e - s >= sr * 0.5:  # skip slivers under 0.5s
            windows.append((s, e, s / float(sr)))
    return windows


def _panns_window_probs(
    audio_path,
    window_seconds,
    hop_seconds,
    max_windows,
    normalize,
):
    """Raw per-window AudioSet probabilities for one file, cached.

    Returns (probs, times) where probs is an (n_windows, n_labels) float32
    array and times is a list of window start seconds -- or (None, None).

    The whole-mix instrument, genre and mood passes all tag the SAME audio
    over the SAME windows and differ only in which labels they keep, so they
    used to decode the file and run the network three separate times. Caching
    the raw probability matrix collapses that to one sweep; later passes are
    a dictionary lookup.
    """
    key = _panns_cache_key(audio_path, window_seconds, hop_seconds, max_windows, normalize)
    cached = _PANNS_WINDOW_CACHE.get(key)
    if cached is not None:
        return cached

    tagger = _get_instrument_tagger()
    if tagger is None:
        return None, None

    try:
        y, sr = librosa.load(audio_path, sr=32000, mono=True)  # PANNs models expect 32kHz
    except Exception:
        return None, None
    if y is None or len(y) < sr * 0.5:
        return None, None

    windows = _panns_window_starts(len(y), sr, window_seconds, hop_seconds, max_windows)
    if not windows:
        return None, None

    rows = []
    times = []
    for start, end, t0 in windows:
        chunk = y[start:end]
        if normalize:
            chunk = _peak_normalize(chunk, INSTRUMENT_TAG_NORMALIZE_PEAK)
        try:
            with quiet_stdout():
                clipwise_output, _ = tagger.inference(chunk[None, :])
        except Exception:
            continue
        rows.append(np.asarray(clipwise_output[0], dtype=np.float32))
        times.append(round(float(t0), 1))

    if not rows:
        return None, None

    probs = np.vstack(rows)
    try:
        _PANNS_WINDOW_CACHE[key] = (probs, times)
        _PANNS_WINDOW_CACHE_ORDER.append(key)
        # Bound memory: a few (n_windows x 527) float32 matrices only, but the
        # batch path is deliberately frugal about RSS. Persistence stats are
        # NOT dropped here -- they are tiny, they are still needed after the
        # matrix is gone (the whole-mix report is built after all four stem
        # passes have pushed the mix out of this cache), and discarding them
        # was losing the window counts from every whole-mix tag line.
        while len(_PANNS_WINDOW_CACHE_ORDER) > max(1, int(PANNS_WINDOW_CACHE_SIZE)):
            old = _PANNS_WINDOW_CACHE_ORDER.pop(0)
            _PANNS_WINDOW_CACHE.pop(old, None)
    except Exception:
        pass
    return probs, times


def _panns_label_groups(label_map):
    """Map each displayed label to the raw AudioSet column indices that feed
    it (several raw labels can share one displayed label, e.g. Organ /
    Electronic organ / Hammond organ). Computed once per label map."""
    groups = {}
    if not _INSTRUMENT_TAGGER_LABELS:
        return groups
    for idx, raw in enumerate(_INSTRUMENT_TAGGER_LABELS):
        mapped = label_map.get(raw)
        if mapped is None:
            continue
        groups.setdefault(mapped, []).append(idx)
    return groups


def _panns_tag_stats(audio_path, label, window_seconds=None, hop_seconds=None,
                     max_windows=None, normalize=None):
    """Persistence statistics for one displayed label on one file, recorded by
    the most recent _panns_tag_windowed() pass. Returns a dict with keys
    hits / n_windows / coverage / peak_prob / peak_time / median_prob, or None.

    Kept in this side table rather than widened into the returned tuples so
    every existing `for label, prob, t in tags` unpack keeps working exactly
    as before.
    """
    if window_seconds is None:
        window_seconds = INSTRUMENT_TAG_WINDOW_SECONDS
    if hop_seconds is None:
        hop_seconds = INSTRUMENT_TAG_HOP_SECONDS
    if max_windows is None:
        max_windows = INSTRUMENT_TAG_MAX_WINDOWS
    if normalize is None:
        normalize = INSTRUMENT_TAG_NORMALIZE
    try:
        key = _panns_cache_key(audio_path, window_seconds, hop_seconds, max_windows, normalize)
    except Exception:
        return None
    return (_PANNS_TAG_STATS.get(key) or {}).get(label)


def _tag_coverage_note(stats):
    """Short human-readable persistence note for a tag line, e.g.
    'sustained: 24/56 windows' or 'isolated: 1/56 windows'. Tells the writer
    the difference between an instrument that plays throughout and a single
    momentary spike, which the peak-only score alone cannot express."""
    if not stats:
        return ""
    hits = int(stats.get("hits") or 0)
    n = int(stats.get("n_windows") or 0)
    if hits <= 0 or n <= 0:
        return ""
    cov = hits / float(n)
    if hits == 1:
        word = "isolated"
    elif cov >= INSTRUMENT_TAG_SUSTAINED_COVERAGE:
        word = "sustained"
    else:
        word = "intermittent"
    return f"{word}: {hits}/{n} windows"


def _panns_tag_windowed(
    audio_path,
    label_map,
    top_k,
    min_prob,
    window_seconds=None,
    hop_seconds=None,
    max_windows=None,
    normalize=None,
):
    """Shared windowed-tagging engine behind tag_stem_instruments(),
    tag_full_mix_instruments(), tag_track_genre() and tag_track_mood().

    Instead of one prediction averaged over the whole clip (PANNs' Cnn14 does
    global pooling, so a brief guitar solo or a bridge-only synth pad gets
    diluted against several minutes of everything else and can silently fall
    below min_prob), this runs the tagger over short overlapping windows and
    keeps, per label, the single strongest window rather than a track-wide
    average -- so something that's clearly present for even one window is
    reported, along with roughly where in the track it was strongest.

    Returns [(label, probability, peak_time_seconds), ...] sorted by
    probability descending. Returns [] if the tagger/audio is unavailable or
    nothing clears min_prob.
    """
    if window_seconds is None:
        window_seconds = INSTRUMENT_TAG_WINDOW_SECONDS
    if hop_seconds is None:
        hop_seconds = INSTRUMENT_TAG_HOP_SECONDS
    if max_windows is None:
        max_windows = INSTRUMENT_TAG_MAX_WINDOWS
    if normalize is None:
        normalize = INSTRUMENT_TAG_NORMALIZE

    probs, times = _panns_window_probs(
        audio_path, window_seconds, hop_seconds, max_windows, normalize
    )
    if probs is None or not times:
        return []

    groups = _panns_label_groups(label_map)
    if not groups:
        return []

    n_windows = int(probs.shape[0])
    stats_key = _panns_cache_key(audio_path, window_seconds, hop_seconds, max_windows, normalize)
    if stats_key not in _PANNS_TAG_STATS:
        _PANNS_TAG_STATS_ORDER.append(stats_key)
        while len(_PANNS_TAG_STATS_ORDER) > max(1, int(PANNS_TAG_STATS_CACHE_SIZE)):
            _PANNS_TAG_STATS.pop(_PANNS_TAG_STATS_ORDER.pop(0), None)
    stats_for_file = _PANNS_TAG_STATS.setdefault(stats_key, {})

    # best[label] = (peak_probability, peak_time_seconds)
    best = {}
    for mapped, idxs in groups.items():
        # Per window, a displayed label scores the strongest of the raw
        # AudioSet columns that feed it.
        per_window = probs[:, idxs].max(axis=1).astype(float)
        peak_i = int(np.argmax(per_window))
        peak_prob = float(per_window[peak_i])
        if peak_prob < min_prob:
            continue

        fired = per_window >= float(min_prob)
        hits = int(np.count_nonzero(fired))
        median_prob = float(np.median(per_window[fired])) if hits else 0.0

        best[mapped] = (peak_prob, times[peak_i] if peak_i < len(times) else 0.0)
        stats_for_file[mapped] = {
            "hits": hits,
            "n_windows": n_windows,
            "coverage": (hits / float(n_windows)) if n_windows else 0.0,
            "peak_prob": peak_prob,
            "peak_time": times[peak_i] if peak_i < len(times) else 0.0,
            "median_prob": median_prob,
            "mean_prob": float(np.mean(per_window)),
        }

    if not best:
        return []

    ranked = sorted(best.items(), key=lambda kv: kv[1][0], reverse=True)[:top_k]
    return [(label, prob, t) for label, (prob, t) in ranked]


def _is_guitar_family_label(label):
    lab = (label or "").strip().lower()
    if lab in INSTRUMENT_TAG_GUITAR_LABELS:
        return True
    return "guitar" in lab and "bass" not in lab


def _guitar_family_probe(audio_path, window_seconds=None, hop_seconds=None,
                         max_windows=None, normalize=None):
    """Measure guitar-family energy straight from the raw per-window PANNs
    probabilities, with no top-k truncation and no reporting thresholds.

    Why this exists separately from the tag pipeline: _panns_tag_windowed()
    ranks every displayed label by peak probability and keeps only the top
    `top_k`. The whole-mix pass keeps 6, and the instrument label map contains
    a large drum family (drum kit, drums, snare, kick, hi-hat, cymbal) plus
    bass and synth, all of which score high on a loud commercial pop-rock
    master. A prominent electric guitar can therefore be ranked seventh and
    silently discarded before the guitar-family threshold is ever applied --
    after which the pipeline concluded "no guitar" and said so in the notes.

    This probe answers a narrower question the tag list cannot: how much
    guitar-family evidence is actually in the audio, including values far
    below any reporting bar, so an ABSENCE claim can be made on positive
    evidence rather than on a failure to clear a strict threshold.

    Reads the same cached probability matrix the tagging passes populate, so
    when tagging has already run this costs one dictionary lookup and a numpy
    reduction -- no extra decode, no extra inference.

    Returns a dict:
        {"peak": float, "coverage": float, "hits": int, "n_windows": int,
         "peak_time": float, "best_label": str, "per_label": {label: peak},
         "present": bool, "absent": bool}
    or None when the tagger/audio is unavailable.
    """
    if not GUITAR_PROBE_ENABLED:
        return None
    if not audio_path or str(audio_path).startswith(("http://", "https://")):
        return None
    if window_seconds is None:
        window_seconds = INSTRUMENT_TAG_WINDOW_SECONDS
    if hop_seconds is None:
        hop_seconds = INSTRUMENT_TAG_HOP_SECONDS
    if max_windows is None:
        max_windows = INSTRUMENT_TAG_MAX_WINDOWS
    if normalize is None:
        normalize = INSTRUMENT_TAG_NORMALIZE

    try:
        probs, times = _panns_window_probs(
            audio_path, window_seconds, hop_seconds, max_windows, normalize
        )
    except Exception:
        return None
    if probs is None or not times:
        return None

    try:
        groups = _panns_label_groups(_INSTRUMENT_LABEL_MAP)
    except Exception:
        return None
    if not groups:
        return None

    # Every displayed label in the guitar family, including the performance
    # techniques ("strum", "tapping") -- AudioSet scores those separately and
    # they are strong evidence that a real played guitar is present rather
    # than a synth patch that merely sounds guitar-ish.
    idxs = []
    per_label = {}
    for mapped, cols in groups.items():
        if not _is_guitar_family_label(mapped):
            continue
        idxs.extend(cols)
        try:
            per_label[mapped] = float(probs[:, cols].max())
        except Exception:
            continue
    if not idxs:
        return None

    try:
        per_window = probs[:, sorted(set(idxs))].max(axis=1).astype(float)
    except Exception:
        return None
    if per_window.size == 0:
        return None

    n_windows = int(per_window.shape[0])
    peak_i = int(np.argmax(per_window))
    peak = float(per_window[peak_i])
    hits = int(np.count_nonzero(per_window >= float(GUITAR_PROBE_FIRE_PROB)))
    coverage = (hits / float(n_windows)) if n_windows else 0.0
    best_label = ""
    if per_label:
        best_label = max(per_label.items(), key=lambda kv: kv[1])[0]

    present = (
        peak >= float(GUITAR_PROBE_PRESENT_PEAK)
        or (
            coverage >= float(GUITAR_PROBE_PRESENT_COVERAGE)
            and peak >= float(GUITAR_PROBE_PRESENT_COVERAGE_PEAK)
        )
    )
    absent = (
        peak < float(GUITAR_PROBE_ABSENT_PEAK)
        and coverage <= float(GUITAR_PROBE_ABSENT_COVERAGE)
    )

    return {
        "peak": peak,
        "coverage": coverage,
        "hits": hits,
        "n_windows": n_windows,
        "peak_time": float(times[peak_i]) if peak_i < len(times) else 0.0,
        "best_label": best_label,
        "per_label": per_label,
        "present": bool(present),
        "absent": bool(absent),
    }


def _drum_extras_probe(drums_stem_path):
    """Find kit pieces the drum transcription structurally cannot detect.

    Reads raw per-window probabilities for cymbals, tambourine, shakers, toms'
    tuned cousins and other percussion straight from the cached PANNs matrix
    for the DRUMS stem, with no top-k truncation. Returns a list of
    (label, peak, coverage, hits, n_windows) sorted strongest first, or [].

    This is deliberately additive: it never touches drum_type, the groove
    statistics or the hit counts, all of which stay exactly as measured. It
    only supplies vocabulary for instruments that were previously invisible.
    """
    if not DRUM_EXTRAS_PROBE_ENABLED or not drums_stem_path:
        return []
    try:
        probs, times = _panns_window_probs(
            drums_stem_path, INSTRUMENT_TAG_WINDOW_SECONDS,
            INSTRUMENT_TAG_HOP_SECONDS, INSTRUMENT_TAG_MAX_WINDOWS,
            INSTRUMENT_TAG_NORMALIZE,
        )
    except Exception:
        return []
    if probs is None or not times:
        return []
    try:
        groups = _panns_label_groups(_INSTRUMENT_LABEL_MAP)
    except Exception:
        return []
    if not groups:
        return []

    n_windows = int(probs.shape[0])
    if not n_windows:
        return []

    out = []
    for mapped, cols in groups.items():
        if mapped not in _DRUM_EXTRA_PROBE_LABELS:
            continue
        try:
            per_window = probs[:, cols].max(axis=1).astype(float)
        except Exception:
            continue
        peak = float(per_window.max())
        hits = int(np.count_nonzero(per_window >= float(DRUM_EXTRAS_FIRE_PROB)))
        coverage = hits / float(n_windows)
        if peak >= float(DRUM_EXTRAS_REPORT_PEAK) or (
            coverage >= float(DRUM_EXTRAS_REPORT_COVERAGE)
            and peak >= float(DRUM_EXTRAS_FIRE_PROB)
        ):
            out.append((mapped, peak, coverage, hits, n_windows))
    out.sort(key=lambda r: r[1], reverse=True)
    return out


def _format_drum_extras(extras):
    """Turn _drum_extras_probe output into a report block."""
    if not extras:
        return ""
    parts = []
    for label, peak, coverage, hits, n_windows in extras:
        note = _tag_coverage_note({"hits": hits, "n_windows": n_windows})
        parts.append(
            f"{label} ({peak * 100:.0f}%, {note or f'{hits}/{n_windows} windows'})"
        )
    return (
        "ADDITIONAL PERCUSSION DETECTED (independent audio classifier run on the "
        "separated drums stem, NOT the note transcription). The transcription above "
        "resolves only kick, snare and hi-hat; these are kit pieces it is structurally "
        "incapable of detecting, so this is the ONLY evidence in the notes about them. "
        "Treat a sustained entry here as a real part of the kit and feel free to name it "
        "(crash/ride when cymbals are listed, tambourine, shaker and so on), while "
        "keeping in mind these are classifier tags rather than counted hits -- describe "
        "presence and rough extent, not exact hit counts or placement, and prefer the "
        "coverage note over inventing a pattern: "
        + "; ".join(parts)
    )


def build_instrument_presence_by_section(stems, sections):
    """Which instrument is audible in WHICH section, not just in the track.

    Instrument tags were whole-track: a label either made the list for the
    whole song or it did not. So "when does the organ come in", "is there
    guitar in the bridge", "what's actually playing in the intro" had no
    evidence behind them at all, and got answered from arrangement habit --
    the same failure mode as the drums, one instrument family over.

    The windowed tagger already produces timestamped probabilities; this
    regroups them by section instead of collapsing them to a track-wide peak.
    No extra inference: the probability matrices are cached from the per-stem
    tagging pass that has already run.

    Reported per instrument rather than per section, because "the organ is in
    the bridge only" is the answer to the question people actually ask, and it
    stays short on a track with ten sections and five tagged stems.
    """
    if not INSTRUMENT_SECTION_PRESENCE_ENABLED or not stems or not sections:
        return ""
    try:
        groups = _panns_label_groups(_INSTRUMENT_LABEL_MAP)
    except Exception:
        return ""
    if not groups:
        return ""

    win = float(INSTRUMENT_TAG_WINDOW_SECONDS or 10.0)
    found = {}   # (label, stem) -> [section names]
    for stem in INSTRUMENT_TAG_STEMS:
        path = (stems or {}).get(stem)
        if not path or not os.path.exists(str(path)):
            continue
        try:
            probs, times = _panns_window_probs(
                path, INSTRUMENT_TAG_WINDOW_SECONDS, INSTRUMENT_TAG_HOP_SECONDS,
                INSTRUMENT_TAG_MAX_WINDOWS, INSTRUMENT_TAG_NORMALIZE,
            )
        except Exception:
            continue
        if probs is None or not times:
            continue
        centers = [float(t) + win / 2.0 for t in times]
        for sec in sections:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            idx = [i for i, c in enumerate(centers) if a <= c < b]
            if not idx:
                # Short section: fall back to whichever window covers it.
                idx = [i for i, t in enumerate(times) if float(t) <= a < float(t) + win]
            if not idx:
                continue
            for mapped, cols in groups.items():
                try:
                    peak = float(probs[np.ix_(idx, cols)].max())
                except Exception:
                    continue
                if peak >= float(INSTRUMENT_SECTION_MIN_PROB):
                    found.setdefault((mapped, stem), []).append(sec.get("name") or "?")
    if not found:
        return ""

    all_names = [sec.get("name") or "?" for sec in sections]
    total = len(all_names)
    rows = []
    for (label, stem), names in found.items():
        uniq = [n for i, n in enumerate(all_names) if n in set(names)]
        if len(uniq) >= total:
            where = "throughout"
        elif len(uniq) == 1:
            where = f"{uniq[0]} only"
        else:
            where = ", ".join(uniq)
        rows.append((len(uniq), label, stem, where))
    rows.sort(key=lambda r: (r[0], r[1]))
    rows = rows[: max(1, int(INSTRUMENT_SECTION_MAX_LABELS)) * 3]

    lines = [
        "INSTRUMENT PRESENCE BY SECTION (independent classifier, per separated "
        "stem, grouped by this track's own sections -- use this when asked which "
        "instruments play in a particular section, when something enters or drops "
        "out, or what is playing at a given point. It reports WHERE an instrument "
        "is detected, not how loud it is there: for loudness use INTENSITY BY "
        "SECTION, and for what it plays use MELODY PER SECTION. These are "
        "classifier detections on separated stems, so treat a single-section "
        "entry as a real but localised appearance and stay cautious about exact "
        "entry/exit moments):"
    ]
    for _n, label, stem, where in rows:
        lines.append(f"  {label} ({stem} stem): {where}")
    return "\n".join(lines)


def _mix_pass_is_low_power(whole_mix_tags):
    """Does the whole-mix tagging pass have enough discriminating power for its
    DISAGREEMENT to mean anything?

    Returns (is_low_power, detail_string). A pass that identified one or two
    labels barely over threshold has not really analysed the track, so "guitar
    is not in that list" says nothing about guitar. Distinguishing this from a
    confident pass that genuinely found no guitar is the whole point: only the
    latter is evidence.
    """
    if whole_mix_tags is None:
        return False, ""
    try:
        n = len(whole_mix_tags)
    except Exception:
        return False, ""
    if n == 0:
        return True, "whole-mix pass returned no tags at all"
    try:
        top = max(float(t[1]) for t in whole_mix_tags if t and len(t) > 1)
    except (TypeError, ValueError):
        return False, ""
    if n <= int(MIX_PASS_LOW_POWER_MAX_TAGS) and top < float(MIX_PASS_LOW_POWER_MAX_TOP_PROB):
        return True, (
            f"whole-mix pass identified only {n} label"
            f"{'' if n == 1 else 's'}, top confidence {top * 100:.0f}%"
        )
    return False, ""


def _label_is_native_to_stem(label, stem):
    """Is this instrument the stem's own source rather than bleed into it?

    Demucs gives guitar, bass, piano, vocals and drums their own stems, so a
    guitar tag on the guitar stem is that stem doing its job. A guitar tag on
    the "other" stem is bleed or a lookalike. Agreements that contain a native
    hit are anchored to a real separated source; agreements made entirely of
    non-native stems may be one mis-identified source counted several times.
    """
    fams = _STEM_NATIVE_FAMILIES.get((stem or "").strip().lower())
    if not fams:
        return False
    lab = (label or "").strip().lower()
    if lab in fams:
        return True
    # Guitar family is matched by shape as well as by name, so a guitar-family
    # label not spelled exactly as listed still anchors to the guitar stem.
    if (stem or "").strip().lower() == "guitar":
        return _is_guitar_family_label(lab)
    return False


def _build_cross_stem_convergence(per_stem_tags, whole_mix_tags=None,
                                  mix_audio_path=None):
    """Find instruments that several independently-tagged stems agree on, and
    say honestly how much that agreement is worth.

    `per_stem_tags` maps displayed label -> [(stem, prob, coverage), ...].
    Returns (block_text, converged) where converged maps label -> list of stem
    names for agreements that survived both guards, so callers can use the
    agreement as evidence as well as report it.

    Two things this deliberately does NOT do. It does not treat agreement as
    proof of an ongoing part: presence and extent are separate claims, and the
    extent question is answered by whole-mix persistence and the per-section
    intensity blocks. And it does not treat stems as independent observers:
    they share one separation, so bleed-prone agreement with no native anchor
    is flagged rather than counted twice.
    """
    mix_cov = {}
    if CONVERGENCE_EXTENT_CONFLICT_ENABLED and mix_audio_path:
        try:
            for lab, _p, _t in (whole_mix_tags or []):
                st = _panns_tag_stats(mix_audio_path, lab)
                if st:
                    mix_cov[lab] = (
                        float(st.get("coverage") or 0.0),
                        int(st.get("hits") or 0),
                        int(st.get("n_windows") or 0),
                        float(st.get("peak_time") or 0.0),
                    )
        except Exception:
            mix_cov = {}

    converged = {}
    lines = []
    for label, entries in sorted(per_stem_tags.items()):
        strong = [e for e in entries if float(e[1]) >= float(CROSS_STEM_CONVERGENCE_MIN_PROB)]
        if len(strong) < int(CROSS_STEM_CONVERGENCE_MIN_STEMS):
            continue
        sustained = [
            e for e in strong
            if float(e[2] or 0.0) >= float(INSTRUMENT_TAG_SUSTAINED_COVERAGE)
        ]
        if len(sustained) < int(CROSS_STEM_CONVERGENCE_MIN_SUSTAINED_STEMS):
            continue

        stems_hit = [e[0] for e in sustained]
        anchored = any(_label_is_native_to_stem(label, st) for st in stems_hit)

        # Unanchored agreement across a pair Demucs is known to smear between
        # is weak: it is consistent with one source appearing in two stems.
        bleed_only = False
        if not anchored and len(stems_hit) >= 2:
            pairs = [
                frozenset((a, b))
                for i, a in enumerate(stems_hit) for b in stems_hit[i + 1:]
                if a != b
            ]
            bleed_only = bool(pairs) and all(p in BLEED_PRONE_STEM_PAIRS for p in pairs)

        # Extent conflict: whole mix found it, but only briefly.
        #
        # Only meaningful when the agreement is UNANCHORED. The whole-mix pass
        # is weak at persistence as well as at identification -- in a dense
        # master an instrument playing throughout still only clears threshold
        # in a handful of windows -- so low whole-mix coverage is not by itself
        # evidence of brief extent. When a native stem carries the instrument
        # sustained, that stem is the better extent witness (isolated and
        # peak-normalised, which is the reason it exists), and firing this rule
        # there would downgrade a genuinely constant part into "a brief detail".
        # With no native anchor there is no such witness, and the whole-mix
        # reading becomes the more trustworthy of the two.
        cov = mix_cov.get(label)
        extent_conflict = bool(
            cov
            and not anchored
            and cov[0] < float(INSTRUMENT_TAG_SUSTAINED_COVERAGE)
        )

        detail = ", ".join(
            f"{stem} stem {prob * 100:.0f}%" for stem, prob, _c in sorted(
                sustained, key=lambda e: e[1], reverse=True
            )
        )
        line = f"- {label}: agreed by {len(sustained)} stems ({detail})"

        cautions = []
        if bleed_only:
            cautions.append(
                "UNANCHORED -- none of these stems is the dedicated stem for this "
                "instrument, and Demucs commonly smears sources between them, so this "
                "may be one mis-identified source appearing twice rather than two "
                "independent detections. Do not upgrade it to a confident identification"
            )
        if extent_conflict:
            _c, _h, _n, _pt = cov
            cautions.append(
                f"EXTENT CONFLICT -- the whole-mix pass, which has no separation "
                f"artifacts, detected this in only {_h}/{_n} windows (strongest near "
                f"{_pt:.0f}s), not across the track. Treat it as a brief or localised "
                f"detail around that point, NOT as an ongoing layer; the sustained stem "
                f"reading is likely a similar timbre bleeding through"
            )
        if cautions:
            line += "\n    [" + "; ".join(cautions) + "]"
        else:
            converged[label] = stems_hit
        lines.append(line)

    if not lines:
        return "", converged

    return (
        "CROSS-STEM INSTRUMENT AGREEMENT (the same instrument identified independently "
        "on more than one separated stem, each sustained across that stem). Demucs "
        "routinely splits one loud instrument across several stems, so repeated "
        "agreement between isolated, peak-normalised stems is real evidence that a "
        "timbre of this family is PRESENT somewhere in the track -- often more "
        "reliable than the whole-mix pass, where everything competes for a few label "
        "slots. But it is evidence of presence only, NOT of extent: these stems all "
        "come from one separation of one file, so they are not fully independent "
        "observers. How much of the track an instrument actually plays is answered by "
        "the whole-mix window counts and the INTENSITY BY SECTION blocks, and how loud "
        "it sits by the STEM ACTIVITY / PROMINENCE ranking -- never by this list. Read "
        "any bracketed caution below as overriding the agreement above it:\n"
        + "\n".join(lines)
    ), converged


def _guitar_stem_is_active(stem_notes=None, activity_metas=None):
    """Corroborating evidence from the dedicated Demucs guitar stem.

    htdemucs_6s separates guitar into its own stem, so a guitar-driven track
    should leave real energy and real transcribed notes there even when the
    AudioSet tagger misses the instrument in the full mix. Returns
    (is_active, detail_string). Both inputs are optional; missing data simply
    yields (False, "") and the caller falls back to tag evidence alone.
    """
    note_count = None
    rms = None
    try:
        if stem_notes and isinstance(stem_notes, dict):
            gn = stem_notes.get("guitar")
            if gn is not None:
                note_count = len(gn)
    except Exception:
        note_count = None
    try:
        for m in (activity_metas or []):
            if (m or {}).get("stem") == "guitar":
                if m.get("silent"):
                    rms = 0.0
                else:
                    rms = float(m.get("rms") or 0.0)
                if note_count is None:
                    note_count = int(m.get("note_count") or 0)
                break
    except Exception:
        pass

    if note_count is None and rms is None:
        return False, ""

    active = False
    if rms is not None and rms >= float(GUITAR_STEM_ACTIVE_MIN_RMS):
        active = True
    if note_count is not None and note_count >= int(GUITAR_STEM_ACTIVE_MIN_NOTES):
        active = True

    bits = []
    if rms is not None:
        bits.append(f"RMS≈{rms:.5f}")
    if note_count is not None:
        bits.append(f"{note_count} transcribed notes")
    return active, ", ".join(bits)


def _filter_instrument_tags(tags, note_count=None, whole_mix_tags=None,
                            audio_path=None, mix_audio_path=None):
    """Apply family-specific thresholds, stem-activity gating, persistence
    gating, and optional whole-mix agreement notes. Returns list of
    (label, prob, peak_t, confidence_note) where confidence_note is "" or a
    short caution string for the report line.

    `audio_path` / `mix_audio_path` are optional: when supplied, per-label
    persistence statistics (how many windows the label actually fired in) are
    consulted so a single fluke window can be held to a higher bar than an
    instrument that is audible throughout. Both default to None, in which case
    behaviour is exactly the previous peak-probability-only logic.
    """
    if not tags:
        return []

    mix_by_label = {}
    if whole_mix_tags:
        for lab, prob, _t in whole_mix_tags:
            mix_by_label[lab] = max(mix_by_label.get(lab, 0.0), float(prob))
            # Also index coarse family keys for soft agreement.
            if _is_guitar_family_label(lab):
                mix_by_label["__guitar__"] = max(
                    mix_by_label.get("__guitar__", 0.0), float(prob)
                )

    # A whole-mix pass that barely identified anything cannot meaningfully
    # disagree with a stem tag; treating its silence as a veto suppresses real
    # instruments (three stems agreeing on guitar, all three marked "whole-mix
    # did not agree", because the mix pass returned one label at 21%).
    mix_low_power, mix_low_power_detail = _mix_pass_is_low_power(whole_mix_tags)

    # The whole-mix tag list is top-k truncated and threshold-filtered, so
    # "guitar is not in this list" is weaker evidence than it looks. When the
    # original mix audio is available, read guitar-family support straight
    # from the raw per-window probabilities instead, so a stem guitar tag is
    # not discarded merely because the mix list had no room for it.
    if mix_audio_path:
        try:
            probe = _guitar_family_probe(mix_audio_path)
            if probe:
                mix_by_label["__guitar__"] = max(
                    mix_by_label.get("__guitar__", 0.0), float(probe.get("peak") or 0.0)
                )
        except Exception:
            pass

    out = []
    for label, prob, t in tags:
        conf_note = ""
        min_needed = INSTRUMENT_TAG_MIN_PROB
        if _is_guitar_family_label(label):
            min_needed = max(min_needed, float(INSTRUMENT_TAG_GUITAR_MIN_PROB))

        stats = _panns_tag_stats(audio_path, label) if audio_path else None
        coverage = float(stats.get("coverage") or 0.0) if stats else 0.0
        hits = int(stats.get("hits") or 0) if stats else 0
        sustained = bool(stats) and coverage >= float(INSTRUMENT_TAG_SUSTAINED_COVERAGE)

        # Persistence gate. The score is the single strongest window, which is
        # what makes brief solos detectable — but it also means one spurious
        # window reads exactly like a part that plays all the way through.
        # Across ~56 windows some label spiking once by chance is likely, so a
        # one-window claim has to clear a higher bar.
        if stats and hits > 0:
            if hits < int(INSTRUMENT_TAG_MIN_WINDOW_HITS) and prob < float(
                INSTRUMENT_TAG_SINGLE_WINDOW_STRONG_PROB
            ):
                continue
            # Conversely, an instrument audible across much of the track is
            # genuinely present even at a moderate peak score; the peak-only
            # rule used to discard these.
            if sustained:
                min_needed *= float(INSTRUMENT_TAG_SUSTAINED_PROB_RELIEF)

        if prob < min_needed:
            continue

        # Empty / near-empty stems: Demucs residuals often get guitar-ish tags.
        if (
            INSTRUMENT_TAG_REQUIRE_STEM_ACTIVITY
            and note_count is not None
            and note_count < INSTRUMENT_TAG_MIN_NOTES_FOR_WEAK
            and prob < INSTRUMENT_TAG_STRONG_PROB
        ):
            continue

        if whole_mix_tags is not None and not mix_low_power:
            mix_p = mix_by_label.get(label, 0.0)
            if _is_guitar_family_label(label):
                mix_p = max(mix_p, mix_by_label.get("__guitar__", 0.0))
            if mix_p < float(INSTRUMENT_TAG_MIX_AGREE_MIN_PROB):
                # Guitar-family without mix support is almost always Demucs
                # residual / synth lookalike — drop unless extremely strong.
                if _is_guitar_family_label(label) and prob < 0.55:
                    continue
                if prob < INSTRUMENT_TAG_STRONG_PROB:
                    # Weak stem-only claim with no mix support → drop.
                    continue
                conf_note = "weak: stem-only, whole-mix did not agree"
            elif mix_p >= min_needed:
                conf_note = "supported by whole-mix tag"
            else:
                conf_note = "partial whole-mix support"
        elif mix_low_power:
            # The mix pass failed on this master, so it cannot corroborate OR
            # contradict. Say exactly that rather than reporting the stem tag
            # as contradicted, and let it through on its own merits.
            conf_note = f"whole-mix cross-check inconclusive ({mix_low_power_detail})"

        # Persistence is reported alongside the confidence note: "sustained"
        # vs "isolated" is exactly the distinction between a rhythm part and a
        # one-off fill, and the peak score alone cannot express it.
        cov_note = _tag_coverage_note(stats)
        if cov_note:
            conf_note = f"{conf_note}; {cov_note}" if conf_note else cov_note

        out.append((label, prob, t, conf_note))

    return out


def tag_stem_instruments(stem_wav_path, top_k=None, min_prob=None):
    """Run the pretrained audio tagger on one stem and return the top
    plausible instrument tags as [(label, probability, peak_time_seconds), ...],
    restricted to the musically-relevant AudioSet classes in
    _INSTRUMENT_LABEL_MAP.

    This is supporting evidence only -- like Essentia's measurements, it is
    not proof of identity on its own (AudioSet taggers can be fooled by
    timbral similarity, e.g. synth brass vs real brass), but it is a genuine
    independent signal the writer previously didn't have, on top of pitch/
    density stats that say nothing about timbre.

    Returns [] if the tagger isn't available, the stem can't be loaded, or
    nothing clears min_prob. Guitar-family labels use a higher threshold
    (see INSTRUMENT_TAG_GUITAR_MIN_PROB); final filtering for stem activity /
    mix agreement happens in build_omnizart_summaries via
    _filter_instrument_tags().
    """
    if top_k is None:
        top_k = INSTRUMENT_TAG_TOP_K
    # Fetch a slightly wider pool so family-specific thresholds can still
    # keep strong guitar tags while dropping weaker non-guitar noise.
    if min_prob is None:
        min_prob = min(INSTRUMENT_TAG_MIN_PROB, 0.10)
    return _panns_tag_windowed(stem_wav_path, _INSTRUMENT_LABEL_MAP, top_k, min_prob)


def tag_full_mix_instruments(mix_audio_path, top_k=None, min_prob=None):
    """Same as tag_stem_instruments(), but run on the original, un-separated
    mix rather than a Demucs stem. A stem-level tag inherits whatever
    mistakes Demucs made when separating (a source can be misassigned,
    smeared across stems, or attenuated); tagging the full mix is a second,
    independent read that isn't subject to those separation artifacts, and
    is useful for flagging cases where a stem's tags look inconsistent with
    what's actually audible in the full mix."""
    if top_k is None:
        top_k = WHOLE_MIX_INSTRUMENT_TAG_TOP_K
    if min_prob is None:
        min_prob = min(WHOLE_MIX_INSTRUMENT_TAG_MIN_PROB, 0.10)
    raw = _panns_tag_windowed(mix_audio_path, _INSTRUMENT_LABEL_MAP, top_k, min_prob)
    # Apply guitar-family floor on the mix as well.
    filtered = []
    for label, prob, t in raw:
        need = WHOLE_MIX_INSTRUMENT_TAG_MIN_PROB
        if _is_guitar_family_label(label):
            need = max(need, float(INSTRUMENT_TAG_GUITAR_MIN_PROB) * 0.85)

        # Same persistence reasoning as the per-stem path: a label that fired
        # in exactly one window out of dozens is far more likely to be a
        # momentary misfire than an instrument in the arrangement, so it has
        # to be strong; one that persists is trusted a little lower.
        stats = _panns_tag_stats(mix_audio_path, label)
        if stats and int(stats.get("hits") or 0) > 0:
            hits = int(stats.get("hits") or 0)
            coverage = float(stats.get("coverage") or 0.0)
            if hits < int(INSTRUMENT_TAG_MIN_WINDOW_HITS) and prob < float(
                INSTRUMENT_TAG_SINGLE_WINDOW_STRONG_PROB
            ):
                continue
            if coverage >= float(INSTRUMENT_TAG_SUSTAINED_COVERAGE):
                need *= float(INSTRUMENT_TAG_SUSTAINED_PROB_RELIEF)

        if prob >= need:
            filtered.append((label, prob, t))

    # TOP-K RESCUE. _panns_tag_windowed() truncates to the top
    # WHOLE_MIX_INSTRUMENT_TAG_TOP_K labels by peak probability BEFORE any
    # family threshold is applied. The instrument map holds a large drum
    # family plus bass and synth, all of which score high on a loud
    # commercial master, so on a dense pop-rock mix a real, prominent
    # electric guitar can be ranked outside the top 6 and vanish before it is
    # ever tested against its own bar -- after which the pipeline reported
    # "no clear guitar-family signal" on a track built around guitar riffs.
    # Consult the raw probabilities directly and put the guitar back if it is
    # genuinely there, flagged honestly as a low-confidence detection.
    try:
        if not any(_is_guitar_family_label(lab) for lab, _p, _t in filtered):
            probe = _guitar_family_probe(mix_audio_path)
            if probe and probe.get("present") and probe.get("best_label"):
                filtered.append(
                    (probe["best_label"], float(probe["peak"]), float(probe["peak_time"]))
                )
                filtered.sort(key=lambda kv: kv[1], reverse=True)
    except Exception:
        pass
    return filtered


def tag_track_genre(mix_audio_path, top_k=None, min_prob=None):
    """Broad AudioSet genre tags for the full mix -- see _GENRE_LABEL_MAP
    and ENABLE_GENRE_MOOD_TAGGING docstring above. Supporting evidence only;
    never treated as a replacement for GENRE_RANKED."""
    if top_k is None:
        top_k = GENRE_TAG_TOP_K
    if min_prob is None:
        min_prob = GENRE_TAG_MIN_PROB
    return _panns_tag_windowed(mix_audio_path, _GENRE_LABEL_MAP, top_k, min_prob)


def tag_track_mood(mix_audio_path, top_k=None, min_prob=None):
    """Broad AudioSet mood tags for the full mix -- see _MOOD_LABEL_MAP.
    Supporting evidence only; never treated as a replacement for MOOD_VIBE."""
    if top_k is None:
        top_k = MOOD_TAG_TOP_K
    if min_prob is None:
        min_prob = MOOD_TAG_MIN_PROB
    return _panns_tag_windowed(mix_audio_path, _MOOD_LABEL_MAP, top_k, min_prob)


def build_genre_mood_signal_report(mix_audio_path):
    """Independent, low-cost genre/mood cross-check built from the same
    already-loaded PANNs tagger used for instrument tagging (see
    ENABLE_GENRE_MOOD_TAGGING docstring).

    Returns (report_text, genre_tags) where genre_tags is the list from
    tag_track_genre() (possibly empty). report_text is "" when nothing useful
    was produced. genre_tags are still returned when present so reconcile_genre()
    can build RECOMMENDED GENRE FOR DISCUSSION even if the prose block is used
    separately.
    """
    if not ENABLE_GENRE_MOOD_TAGGING:
        return "", []
    if mix_audio_path is None or mix_audio_path.startswith(("http://", "https://")):
        return "", []

    genre_tags = tag_track_genre(mix_audio_path)
    mood_tags = tag_track_mood(mix_audio_path)
    if not genre_tags and not mood_tags:
        return "", genre_tags or []

    lines = ["OBJECTIVE GENRE/MOOD SIGNAL (independent AudioSet classifier, PANNs)"]
    if genre_tags:
        lines.append(
            "genre-adjacent tags: "
            + ", ".join(f"{label} ({prob * 100:.0f}%)" for label, prob, _t in genre_tags)
        )
    if mood_tags:
        lines.append(
            "mood-adjacent tags: "
            + ", ".join(f"{label} ({prob * 100:.0f}%)" for label, prob, _t in mood_tags)
        )
    lines.append(
        "These categories are broad, overlapping, and derived from noisy YouTube "
        "metadata -- they are supporting evidence, not automatic overrides. "
        "When this signal clearly favours electronic/dance/synth-pop and GENRE_RANKED "
        "leads with rock/pop-punk mainly from guitar texture, prefer revising "
        "GENRE_RANKED toward the electronic/dance identity (see self-check genre rules). "
        "When both agree, keep GENRE_RANKED. When mixed, put the production-led label "
        "first and the secondary flavour second with lower confidence."
    )
    return "\n".join(lines), genre_tags


def build_whole_mix_instrument_report(mix_audio_path, tags=None):
    """Independent whole-mix instrument tagging (see tag_full_mix_instruments
    docstring) formatted as a report block. Returns "" if disabled, the
    tagger is unavailable, or nothing clears the probability threshold.

    If `tags` is provided (same shape as tag_full_mix_instruments output),
    skips re-running the tagger — used when the stem pass already computed
    whole-mix tags for agreement filtering.
    """
    if not ENABLE_WHOLE_MIX_INSTRUMENT_TAGGING:
        return ""
    if tags is None:
        if mix_audio_path is None or mix_audio_path.startswith(("http://", "https://")):
            return ""
        tags = tag_full_mix_instruments(mix_audio_path)
    if not tags:
        return (
            "WHOLE-MIX INSTRUMENT TAGS: none cleared the confidence thresholds "
            "(prefer describing texture without naming weak instrument identities). "
            "This means the classifier was not confident about any instrument on this "
            "track -- it does NOT mean the track is instrumentally empty or that any "
            "particular instrument is missing. Do not turn this into a negative claim."
        )

    tag_parts = []
    for label, prob, t in tags:
        part = f"{label} ({prob * 100:.0f}%, strongest near {t:.0f}s"
        cov_note = _tag_coverage_note(_panns_tag_stats(mix_audio_path, label))
        if cov_note:
            part += f", {cov_note}"
        tag_parts.append(part + ")")
    tag_text = ", ".join(tag_parts)
    return (
        "WHOLE-MIX INSTRUMENT TAGS (independent audio classifier run on the original, "
        "un-separated mix -- not subject to Demucs separation artifacts. "
        "Guitar-family labels use a higher confidence bar. Treat disagreement with a "
        "per-stem tag as a reason to omit or hedge that instrument rather than "
        "trusting the stem alone; still supporting evidence only, not proof. "
        "If a named instrument is absent here and only weakly present on one stem, "
        "prefer 'no clear X' over asserting X -- but note that this list is capped at a "
        "fixed number of labels and uses strict per-family thresholds, so a label's "
        "absence from it is NOT positive evidence that the instrument is absent from "
        "the recording, and must never be reported as 'the track has no X'. Only an "
        "explicit absence note elsewhere in these notes carries that meaning. The "
        "window counts say how much of the "
        "track each label was actually detected in: 'sustained' means an ongoing part "
        "in the arrangement, while 'isolated' means a single brief moment -- describe "
        f"an isolated tag as a passing detail, never as a main instrument): {tag_text}"
    )


def guitar_absence_note_from_tags(whole_mix_tags=None, report_text=None,
                                  mix_audio_path=None, stem_notes=None,
                                  activity_metas=None, cross_stem_agreement=None):
    """Report what is actually known about guitar on this track: present,
    absent, or undetermined -- and never silently turn the third case into the
    second.

    The original version emitted a hard GUITAR ABSENCE NOTE whenever the
    whole-mix tag list contained no guitar-family label above
    INSTRUMENT_TAG_MIX_AGREE_MIN_PROB. That list is top-k truncated and sits
    behind a deliberately strict 0.35 family threshold, so it goes empty for
    two very different reasons: because there is no guitar, or because a real
    guitar scored 0.2 on a dense limited master, or read as synth, or lost its
    place in the top 6 to the drum family. The note did not distinguish them,
    and the writer prompt treats it as authoritative -- so a detector miss
    became a confident claim of absence, and then an argument against a
    rock/pop-rock genre reading. That is the failure this rewrite fixes.

    Absence is now asserted only on positive evidence: guitar-family energy
    measurably low across the whole mix (raw per-window probabilities, no
    top-k, no reporting threshold) AND a dedicated Demucs guitar stem with no
    real activity. When the two disagree, or when the evidence is merely
    inconclusive, an explicit uncertainty note is emitted instead, which tells
    the writer to describe the texture neutrally and forbids using "no guitar"
    as a genre argument.

    `mix_audio_path`, `stem_notes`, `activity_metas` and `cross_stem_agreement`
    are optional; without them the function degrades to the tag-list evidence it
    always had, but still hedges rather than asserting absence outright.
    """
    found_guitar = False
    if whole_mix_tags is not None:
        for item in whole_mix_tags:
            if not item:
                continue
            lab = item[0] if isinstance(item, (tuple, list)) else str(item)
            try:
                prob = float(item[1]) if isinstance(item, (tuple, list)) and len(item) > 1 else 0.0
            except (TypeError, ValueError):
                prob = 0.0
            if _is_guitar_family_label(lab) and prob >= float(INSTRUMENT_TAG_MIX_AGREE_MIN_PROB):
                found_guitar = True
                break
    elif report_text:
        # Parse lines from WHOLE-MIX INSTRUMENT TAGS report.
        lower = report_text.lower()
        if "whole-mix instrument tags" in lower:
            # Only the tag list itself is evidence. The block's own preamble
            # contains the advisory phrase "prefer 'no clear X'", so scanning
            # the whole string for "no clear" used to zero out a positive
            # detection on every single track that reached this branch.
            tail = report_text.split("):", 1)[-1].lower() if "):" in report_text else lower
            if "none cleared" in lower:
                found_guitar = False
            else:
                for lab in ("electric guitar", "acoustic guitar", "guitar", "slide/steel"):
                    if lab in tail:
                        found_guitar = True
                        break
        else:
            return ""  # tagging didn't run / no report
    else:
        return ""

    if found_guitar:
        return ""

    # --- No guitar in the reported tags. Establish WHY before claiming it. ---
    probe = None
    try:
        probe = _guitar_family_probe(mix_audio_path) if mix_audio_path else None
    except Exception:
        probe = None

    stem_active, stem_detail = _guitar_stem_is_active(
        stem_notes=stem_notes, activity_metas=activity_metas
    )

    # Several isolated stems independently identifying guitar is corroboration
    # in its own right, and settles the question against a mix pass that found
    # nothing. Without this, three stems agreeing at 64-82% counted for zero.
    conv_stems = []
    try:
        for lab, stems_list in (cross_stem_agreement or {}).items():
            if _is_guitar_family_label(lab):
                for st in (stems_list or []):
                    if st not in conv_stems:
                        conv_stems.append(st)
    except Exception:
        conv_stems = []

    mix_low_power, mix_low_power_detail = _mix_pass_is_low_power(whole_mix_tags)

    probe_bits = ""
    if probe:
        probe_bits = (
            f"peak guitar-family confidence {probe['peak'] * 100:.0f}% "
            f"across the whole mix, fired in {probe['hits']}/{probe['n_windows']} windows"
        )

    # Case 1: the raw probabilities agree there is essentially nothing there,
    # and the dedicated guitar stem is empty too. This is a real absence.
    if probe and probe.get("absent") and not stem_active and not conv_stems and not mix_low_power:
        detail = f" ({probe_bits}"
        detail += f"; separated guitar stem inactive: {stem_detail})" if stem_detail else ")"
        return (
            "GUITAR ABSENCE NOTE: whole-mix instrument tagging found no clear "
            "guitar-family signal on THIS track" + detail + ", and the dedicated "
            "Demucs guitar stem carries no real activity. Two independent checks "
            "agree, so treat this as genuine absence: do not claim electric/acoustic "
            "guitar from genre expectation, a residual Demucs 'guitar' stem, or "
            "instruments heard on a previously discussed track. Prefer 'no clear "
            "guitar' or a texture description unless the user confirms otherwise."
        )

    # Case 2: the tag list is empty but something is still there -- the raw
    # probabilities show guitar-family energy, or the guitar stem is carrying
    # a real part, or both. This is the case that used to be misreported as
    # absence, and it is where guitar-driven tracks were losing their guitars.
    reasons = []
    if probe and (probe.get("present") or not probe.get("absent")):
        reasons.append(
            "the raw classifier still shows measurable guitar-family energy in the mix"
            + (f" ({probe_bits})" if probe_bits else "")
        )
    if stem_active:
        reasons.append(
            "the dedicated Demucs guitar stem is carrying a real part"
            + (f" ({stem_detail})" if stem_detail else "")
        )
    if conv_stems:
        reasons.append(
            "guitar was identified independently on "
            + f"{len(conv_stems)} separate stems ({', '.join(conv_stems)}), each "
            "sustained across the track"
        )
    if mix_low_power and not reasons:
        reasons.append(
            "the whole-mix pass had no discriminating power on this master "
            f"({mix_low_power_detail}), so its silence about guitar is not evidence"
        )
    if reasons:
        return (
            "GUITAR EVIDENCE INCONCLUSIVE (do NOT report this as 'no guitar'): the "
            "whole-mix tagger did not produce a confident guitar-family tag on this "
            "track, but " + ", and ".join(reasons) + ". This "
            "classifier is known to under-report guitar on dense, heavily limited "
            "commercial masters and to score overdriven or heavily processed electric "
            "guitar as synth/keyboard, so a missing tag here is weak evidence of "
            "absence and no evidence at all about the arrangement. Do NOT state that "
            "the track has no guitar, and do NOT use absence of guitar as an argument "
            "for or against any genre label (a pop-rock or rock reading must stand or "
            "fall on the rest of the evidence). Describe the midrange layer neutrally "
            "instead -- e.g. 'a bright, overdriven midrange rhythm layer, guitar or "
            "guitar-like synth' -- and say the instrument tagging was inconclusive if "
            "the user asks directly."
            + (
                " NOTE: with this many independent stems agreeing, guitar is best "
                "treated as PRESENT in the arrangement; what remains genuinely "
                "uncertain is only its prominence and whether it is guitar or a "
                "guitar-like synth patch. Use the STEM ACTIVITY / PROMINENCE "
                "ranking for how loud it sits."
                if len(conv_stems) >= int(CROSS_STEM_CONVERGENCE_MIN_STEMS) else ""
            )
        )

    # Case 3: no probe available (tagger/audio missing) and no stem evidence.
    # Nothing was measured, so nothing is claimed either way.
    return (
        "GUITAR EVIDENCE UNAVAILABLE: whole-mix instrument tagging reported no "
        "guitar-family tag on this track, but no independent cross-check could be "
        "run, so this is not evidence of absence. Do not assert either that the "
        "track has guitar or that it has none; describe the texture from what was "
        "measured and treat instrument identity here as undetermined."
    )



def build_section_keyed_stem_blocks(stems, sections, stem_notes, bpm=None, key=None):
    """Per-section stem evidence (intensity + melody), built AFTER the section
    map is final.

    These blocks name and timestamp every section they describe, so they are
    only correct if they are generated from the same map the writer is given as
    authoritative. Generating them earlier and leaving them in place after the
    map changes produces two contradictory section lists in one evidence
    bundle -- the structure block saying "Pre-Chorus 1 1:02-1:13" while the
    melody and intensity blocks still describe a differently-named section over
    the same seconds. Splitting them out of the main stem report and building
    them here keeps the whole bundle keyed to one map.
    """
    if not sections:
        return ""
    blocks = []
    for stem in STEM_MIDI_STEMS:
        path = (stems or {}).get(stem)
        if not path or not os.path.exists(path):
            continue
        try:
            _whole, section_rms = _stem_rms_by_section(path, sections)
        except Exception:
            continue
        if section_rms:
            block = _format_intensity_by_section(stem, section_rms)
            if block:
                blocks.append(block)
    # Per-section drum groove ("what's the groove like in the chorus vs the
    # verse"). This is also section-keyed, so it belongs here with the rest --
    # it was previously produced inside summarize_stem_midi and would simply
    # vanish once that call stopped receiving a section list.
    drum_notes = (stem_notes or {}).get("drums")
    if drum_notes:
        try:
            # Returns a LIST of per-section lines, not a string.
            section_blocks = _summarize_drum_rhythm_by_section(
                drum_notes, sections, bpm,
                max_pattern_hits=max(8, STEM_MIDI_DRUM_PATTERN_HITS // 2),
            )
            if section_blocks:
                blocks.append("\n".join(
                    ["Per-section groove (from this track's own STRUCTURE boundaries; "
                     "use these, not the whole-track pattern, when asked about the "
                     "groove in a specific section like the verse or chorus):"]
                    + list(section_blocks)
                ))
        except Exception:
            pass

    try:
        presence = build_instrument_presence_by_section(stems, sections)
        if presence:
            blocks.append(presence)
    except Exception:
        pass

    try:
        _changes = _arrangement_change_points(
            stem_notes, bpm=bpm,
            total_duration=(sections[-1]["end"] if sections else None),
        )
        _chg_block = build_arrangement_change_report(_changes)
        if _chg_block:
            blocks.append(_chg_block)
    except Exception:
        pass

    if stem_notes:
        try:
            melody = build_melody_understanding_block(
                sections, stem_notes, bpm=bpm, key=key
            )
            if melody:
                blocks.append(melody)
        except Exception:
            pass
    return "\n\n".join(blocks)


def build_omnizart_summaries(stems, whole_mix_tags=None, bpm=None, sections=None,
                             key=None, notes_out=None, mix_audio_path=None,
                             activity_out=None, convergence_out=None):
    """`mix_audio_path` (optional): path to the original un-separated mix.
    Threaded through to _filter_instrument_tags so guitar-family stem tags can
    be checked against the raw whole-mix probabilities rather than only
    against the top-k truncated whole-mix tag list.

    `convergence_out` (optional dict): populated in place with the cross-stem
    instrument agreement map (label -> [stem, ...]) so callers can use "several
    stems independently found this instrument" as evidence, not just print it.

    `activity_out` (optional list): populated in place with the per-stem
    activity metadata (stem, rms, note_count, density, silent). The Demucs
    guitar stem's energy is independent evidence about whether a guitar is
    present, and the caller needs it to decide whether a missing guitar tag
    means absence or just a detector miss.

    `key` (optional): the track's RECOMMENDED KEY FOR DISCUSSION string,
    e.g. "C major" -- threaded through to melodic-line summaries so they can
    report real scale-degree emphasis instead of just bare note names.

    `notes_out` (optional dict): populated in place with the filtered note
    events per stem. The raw transcription used to be discarded the moment
    this function returned its prose report, so nothing downstream -- the
    saved .json, the melodic analysis block, a reloaded track -- could ever
    see an actual note again. Passing a dict here keeps the measurements
    available for the rest of the pipeline without changing the return type
    for existing callers."""
    if not stems:
        return "STEM MIDI REPORT unavailable: no Demucs stems found."

    lines = []
    activity_metas = []
    stem_notes = {}   # will store filtered notes per stem
    # label -> [(stem, prob, coverage), ...], for cross-stem agreement below.
    per_stem_tags = {}

    for stem in STEM_MIDI_STEMS:
        path = stems.get(stem)
        if not path or not os.path.exists(path):
            continue

        preset = STEM_MIDI_PRESETS[stem]
        # Always measure stem energy for prominence ranking (cheap vs transcription).
        # This now reads the WHOLE stem and, when structure sections are
        # available, also returns a per-section RMS breakdown -- see
        # _stem_rms_by_section. One file load covers both.
        rms, section_rms_list = _stem_rms_by_section(path, sections)
        empty_rms = float(preset.get("empty_rms_threshold", 0) or 0)
        if empty_rms > 0 and rms < empty_rms:
            lines.append(
                f"[{stem.upper()} stem]\n"
                f"Stem energy is very low (RMS≈{rms:.5f}); treating as effectively silent. "
                f"Demucs often leaves a quiet residual even when this instrument is absent."
            )
            activity_metas.append({
                "stem": stem,
                "rms": rms,
                "note_count": 0,
                "density": 0.0,
                "is_drums": stem == "drums",
                "silent": True,
            })
            continue

        try:
            # --- ROUTING LOGIC ---
            try:
                if stem == "drums":
                    # Try Omnizart's dedicated drum model first — real kick/snare/hihat/tom/cymbal
                    # classification, not just a register guess. Fall back to the onset detector
                    # only if Omnizart fails or returns nothing for this stem.
                    status(f"Transcribing drums with Omnizart's drum model: {os.path.basename(path)}")

                    raw_notes = omnizart_transcribe(path, stem, preset)

                    if not raw_notes:
                        if SHOW_OMNIZART_LOGS:
                            print(
                                "  (Omnizart returned no hits for the drums stem; "
                                "falling back to the multiband onset detector)"
                            )
                        raw_notes = transcribe_drums_with_onsets(
                            path,
                            preset
                        )
                    elif SHOW_OMNIZART_LOGS:
                        print(
                            f"  (Omnizart drum model returned "
                            f"{len(raw_notes)} classified hit(s))"
                        )

                elif stem == "other":
                    # Try Omnizart's music model first; fall back to onset detection.
                    raw_notes = omnizart_transcribe(path, stem, preset)

                    if not raw_notes:
                        if SHOW_OMNIZART_LOGS:
                            print(
                                "  (Omnizart returned no notes for 'other' stem; "
                                "falling back to onset detection)"
                            )
                        raw_notes = transcribe_drums_with_onsets(
                            path,
                            preset
                        )

                else:
                    # vocals -> Omnizart vocal model
                    # bass/guitar/piano -> Omnizart music model
                    raw_notes = omnizart_transcribe(
                        path,
                        stem,
                        preset
                    )
            except Exception as e:
                print(f"  ⚠ {stem} stem MIDI transcription failed: {e}")
                raw_notes = []

            # Ensure raw_notes is a list (some stems may return None on failure)
            if raw_notes is None:
                raw_notes = []

            # --- FILTERING LOGIC ---
            if stem == "drums":
                filtered = [n for n in raw_notes if n.get("onset", 0) >= 0]
                removed = len(raw_notes) - len(filtered)
                stem_notes[stem] = filtered
            elif stem == "other" and not any(
                preset["min_frequency"] <= n["frequency"] <= preset["max_frequency"]
                for n in raw_notes
            ):
                # Onset-fallback path: skip pitch-range filter, keep only valid onsets.
                filtered = [n for n in raw_notes if n.get("onset", 0) > 0 and n.get("duration", 0) > 0]
                removed = len(raw_notes) - len(filtered)
                stem_notes[stem] = filtered
            else:
                filtered, removed = _filter_transcribed_notes(raw_notes, preset)
                stem_notes[stem] = filtered

            summary, meta = summarize_stem_midi(
                stem, raw_notes, filtered, removed, preset, stem_rms=rms,
                bpm=bpm, sections=sections, section_rms=section_rms_list, key=key,
                stem_path=path,
            )

            if ENABLE_INSTRUMENT_TAGGING and stem in INSTRUMENT_TAG_STEMS:
                status(f"Tagging instruments in {stem} stem...")
                raw_tags = tag_stem_instruments(path)
                note_count = int(meta.get("note_count") or 0)
                tags = _filter_instrument_tags(
                    raw_tags,
                    note_count=note_count,
                    whole_mix_tags=whole_mix_tags,
                    audio_path=path,
                    mix_audio_path=mix_audio_path,
                )
                if tags:
                    tag_parts = []
                    for label, prob, t, conf_note in tags:
                        base = f"{label} ({prob * 100:.0f}%, strongest near {t:.0f}s)"
                        if conf_note:
                            base += f" [{conf_note}]"
                        tag_parts.append(base)
                        # Record for the cross-stem agreement pass.
                        try:
                            _st = _panns_tag_stats(path, label) or {}
                            per_stem_tags.setdefault(label, []).append(
                                (stem, float(prob), float(_st.get("coverage") or 0.0))
                            )
                        except Exception:
                            pass
                    summary += (
                        f"\ninstrument tag (independent audio classifier, windowed; "
                        f"guitar-family + empty-stem filters applied; supporting evidence "
                        f"only — do NOT assert an instrument from a weak/stem-only tag): "
                        + ", ".join(tag_parts)
                    )
                elif raw_tags:
                    summary += (
                        "\ninstrument tag: raw classifier fired weak labels that were "
                        "dropped (below family threshold, empty-stem gate, or no whole-mix "
                        "agreement). Prefer texture description over naming those instruments."
                    )

            activity_metas.append(meta)
        except Exception as e:
            summary = f"[{stem.upper()} stem] MIDI transcription failed: {e}"
            print(f"  \u26a0 {stem} stem MIDI transcription failed: {e}")
            activity_metas.append({
                "stem": stem,
                "rms": rms,
                "note_count": 0,
                "density": 0.0,
                "is_drums": stem == "drums",
                "silent": True,
            })
            
            stem_notes[stem] = []

        lines.append(summary)

    if not lines:
        return "STEM MIDI REPORT unavailable: no stems could be transcribed."

    # Cross-stem prominence ranking (energy + event density) — small but useful
    # for "which instruments dominate" questions without raw event dumps.
    if activity_metas:
        ranked = sorted(
            activity_metas,
            key=lambda m: (
                0 if m.get("silent") else 1,
                float(m.get("rms") or 0.0),
                float(m.get("density") or 0.0),
            ),
            reverse=True,
        )
        rank_parts = []
        for i, m in enumerate(ranked, 1):
            rms_v = m.get("rms")
            dens = float(m.get("density") or 0.0)
            rms_s = f"{rms_v:.5f}" if rms_v is not None else "n/a"
            if m.get("silent"):
                band = "silent/negligible"
            else:
                band, _ = _stem_activity_label(
                    float(rms_v or 0.0), dens, is_drums=bool(m.get("is_drums"))
                )
            dens_unit = "hits/min" if m.get("is_drums") else "notes/min"
            rank_parts.append(
                f"{i}) {m['stem']}: {band} (RMS={rms_s}, density={dens:.1f} {dens_unit}, "
                f"events={m.get('note_count', 0)})"
            )
        lines.append(
            "STEM ACTIVITY / PROMINENCE (ranked by stem energy then event density; "
            "use for relative instrument balance, not absolute loudness):\n"
            + "\n".join(rank_parts)
        )

    # Cross-stem agreement: the same instrument found independently on more
    # than one isolated stem. Built after every stem has been tagged.
    _convergence = {}
    try:
        _conv_block, _convergence = _build_cross_stem_convergence(
            per_stem_tags, whole_mix_tags=whole_mix_tags,
            mix_audio_path=mix_audio_path,
        )
        if _conv_block:
            lines.append(_conv_block)
    except Exception:
        _convergence = {}
    if convergence_out is not None and isinstance(convergence_out, dict):
        try:
            convergence_out.update(_convergence)
        except Exception:
            pass

    coverage_note = (
        "full track" if not STEM_MIDI_MAX_SECONDS
        else f"first ~{int(STEM_MIDI_MAX_SECONDS)} seconds"
    )
    if STEM_MIDI_INCLUDE_EVENT_LOGS:
        event_note = (
            "Optional compact note/hit event samples are included per stem (evenly sampled "
            "end-to-end). "
            if STEM_MIDI_COMPACT_EVENT_FORMAT else
            "Optional JSON note/hit event samples are included per stem (evenly sampled "
            "end-to-end). "
        )
    else:
        event_note = (
            "Raw note/hit event lists are omitted to keep context small; rely on aggregate "
            "stats, melodic-line samples, drum pattern samples, and the STEM ACTIVITY / "
            "PROMINENCE ranking for melody, groove, and instrument-balance discussion. "
        )
    header = (
        f"STEM MIDI REPORT (Demucs 6s + Omnizart, {coverage_note}, all 6 stems: "
        "vocals/bass/guitar/piano/other/drums)\n"
        "This is a probabilistic audio-to-MIDI transcription of separated stems — "
        "not a Logic Pro project or a standard MIDI file. Aggregate stats (pitch range, "
        "density, chords, drum-type breakdown, rhythm pattern samples, melodic-line "
        "samples, stem energy/prominence, etc.) are computed from ALL detected notes/hits "
        "for the whole track. Per-stem energy (RMS) is measured over the WHOLE track, and "
        "when structure sections are available, each stem also gets an INTENSITY BY "
        "SECTION block showing how that instrument's presence rises and falls across the "
        "song's own verse/chorus/etc. sections — use that (not just the single whole-track "
        "prominence figure) whenever the user asks how an instrument changes across the "
        "song, builds into the chorus, drops out, etc. "
        "Melodic-line summaries also report real step/leap interval movement and, when the "
        "track's key is known, which scale degrees (relative to that key) the line "
        "emphasizes — both computed directly from the transcribed notes, not invented; use "
        "them for genuine music-theory framing (e.g. 'mostly stepwise, centers on the tonic "
        "and dominant') instead of guessing at harmony from note names alone. "
        + event_note
        + "Use it for casual melody/harmony/composition/rhythm discussion; be cautious "
        "with erratic short notes and low-confidence stems.\n"
    )

    # Build the melody‑per‑section block from the filtered notes and the
    # structural sections, then append it to the report.
    if sections and stem_notes:
        melody_block = _build_melody_per_section(sections, stem_notes, bpm=bpm, key=key)
        if melody_block:
            lines.append("\n" + melody_block)

    # Independent section-change candidates from MIDI note-density jumps.
    # These catch arrangement shifts that keep the same full-mix timbre
    # (e.g. denser chorus line) and feed the structure snap pipeline via
    # _collect_structure_boundaries().
    try:
        _dur_for_midi = None
        if sections:
            try:
                _dur_for_midi = max(float(s.get("end") or 0) for s in sections)
            except Exception:
                _dur_for_midi = None
        _midi_bounds = _midi_activity_boundary_candidates(
            stem_notes, duration=_dur_for_midi
        )
        if _midi_bounds:
            lines.append(
                "MIDI ACTIVITY BOUNDARY CANDIDATES (objective, per-stem note-density "
                "change points — independent of full-mix timbre novelty):\n"
                "candidate change points: "
                + ", ".join(_seconds_to_mmss(t) for t in _midi_bounds)
            )
    except Exception:
        pass

    if notes_out is not None and isinstance(notes_out, dict):
        notes_out.update(stem_notes)

    # Per-stem energy/density, exported for callers that need to cross-check a
    # tagger result against what the separated stems actually contain.
    if activity_out is not None and isinstance(activity_out, list):
        try:
            activity_out.extend(activity_metas)
        except Exception:
            pass

    # Return the full report, now including melody per section.
    return header + "\n\n".join(lines)


# --- Save/load helpers ------------------------------------------------------
# Characters that must never appear in a saved basename (path separators,
# Windows-reserved, control chars). Spaces, apostrophes, parentheses, dashes,
# unicode letters, etc. are intentionally kept so "/save" and "/load" work with
# natural names like "Artist Name - Song's Title (Live).json".
_SAVED_NAME_FORBIDDEN = re.compile(r'[/\\:\*\?"<>\|\x00-\x1f]')


def _sanitize_saved_name(name):
    """Keep spaces and most printable characters; only strip path-hostile chars.

    Previously this collapsed everything outside [A-Za-z0-9._-] to underscores,
    which made it impossible to save or load names containing spaces or common
    punctuation. We now preserve the user's intended filename as closely as
    the filesystem allows.
    """
    name = (name or "").strip().strip('"').strip("'")
    if not name:
        return ""

    base = os.path.basename(name)
    # Normalise runs of whitespace to a single space; drop path-hostile chars.
    safe = _SAVED_NAME_FORBIDDEN.sub("_", base)
    safe = re.sub(r"\s+", " ", safe).strip()
    if not safe:
        return ""
    # Keep a clean ".json" suffix when present (avoid "Name .json").
    if safe.lower().endswith(".json"):
        stem = safe[:-5].rstrip(" .")
        safe = (stem if stem else "song") + ".json"
    else:
        safe = safe.rstrip(" .")
    if not safe:
        return ""
    if len(safe) > 200:
        # Prefer keeping the extension when truncating.
        if safe.lower().endswith(".json"):
            stem = safe[:-5][:195].rstrip(" .")
            safe = (stem if stem else "song") + ".json"
        else:
            safe = safe[:200].rstrip(" .")
    return safe


def _metadata_artist_title(metadata, audio_path=None):
    """Return (artist, title) for batch/save naming from tags or filename."""
    artist = ""
    title = ""
    if metadata:
        artist = str(metadata.get("artist") or "").strip()
        title = str(metadata.get("title") or "").strip()

    if not title and audio_path:
        base = os.path.basename(audio_path or "")
        stem, _ext = os.path.splitext(base)
        title = stem.strip() if stem.strip() else ""

    if not artist:
        artist = "Unknown"
    if not title:
        title = f"song_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}"
    return artist, title


def _batch_save_basename(audio_path, metadata=None):
    """Derive a .json basename as 'Artist Name - Song Name.json'.

    Uses file-tag artist/title when available. Missing artist → 'Unknown';
    missing title → original audio filename stem. Spaces and normal
    punctuation are kept (only path-hostile characters are replaced).

    e.g. tags Artist='Radiohead', Title='Creep' → 'Radiohead - Creep.json'
         no tags, file '01 Song Title.m4a' → 'Unknown - 01 Song Title.json'
    """
    artist, title = _metadata_artist_title(metadata, audio_path)

    def _part(s):
        s = _SAVED_NAME_FORBIDDEN.sub("_", str(s or ""))
        s = re.sub(r"\s+", " ", s).strip(" .")
        return s or "Unknown"

    stem = f"{_part(artist)} - {_part(title)}"
    if not stem.strip(" -"):
        stem = f"song_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}"
    if len(stem) > 180:
        stem = stem[:180].rstrip(" .")
    return stem + ".json"


def save_song_data(
    filename,
    track_key,
    analysis,
    corrections,
    metadata=None,
    cover_observations=None,
    singer_identity=None,
    cover_bytes=None,
    cover_mime="image/jpeg",
    preserve_audio_basename=False,
    stem_midi=None,
    structure_sections=None,
    bpm=None,
    key=None,
    clap_embedding=None,
):
    os.makedirs(SAVE_DIR, exist_ok=True)

    if preserve_audio_basename and track_key and not str(track_key).startswith(("http://", "https://")):
        safe = _batch_save_basename(track_key, metadata=metadata)
    else:
        safe = _sanitize_saved_name(filename) or f"song_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}"
        if not safe.lower().endswith(".json"):
            safe += ".json"

    path = os.path.join(SAVE_DIR, safe)

    lyrics_text = ""
    if metadata:
        lyrics_text = str(metadata.get("lyrics") or "").strip()

    # Prefer the embedding already computed at the end of the analysis
    # (resolve_identity_and_finalize). Fall back to computing it here so any
    # caller that doesn't pass one — an older/other call path, or a re-save of
    # a track whose analysis predates this — still produces a complete JSON,
    # exactly as before. compute_clap_embedding() is cached, so even the
    # fallback is free when the vector was already made for this file.
    clap_vector = _extract_clap_embedding(clap_embedding)
    if clap_vector is not None:
        # _extract_clap_embedding returns full float32 precision; round to the
        # same CLAP_EMBEDDING_PRECISION the compute path uses so a JSON written
        # from a passed-in vector is byte-identical to one written from a
        # freshly computed vector.
        clap_vector = [round(float(x), CLAP_EMBEDDING_PRECISION) for x in clap_vector]
    if clap_vector is None and ENABLE_CLAP_EMBEDDING and track_key and not str(track_key).startswith(("http://", "https://")):
        clap_vector = compute_clap_embedding(track_key)

    # Write the prepared cover art next to the JSON so saves are self-contained.
    # Cover art uses the same stem as the JSON (including spaces / special chars).
    cover_path = None
    if cover_bytes:
        stem_name = safe[:-5] if safe.lower().endswith(".json") else safe
        img_suffix = _cover_temp_suffix(cover_mime or _guess_image_mime(cover_bytes))
        cover_path = os.path.join(SAVE_DIR, stem_name + img_suffix)
        try:
            with open(cover_path, "wb") as f:
                f.write(cover_bytes)
        except Exception as e:
            print(f"  (could not write cover art to save: {e})")
            cover_path = None

    data = {
        "version": 2,
        "track_path": track_key,
        "label": track_label(track_key),
        "saved_at": datetime.datetime.now().isoformat(),
        "audio_file_signature": _audio_file_signature(track_key),
        "analysis": analysis,
        "corrections": corrections or {},
        "metadata": metadata or {},
        "lyrics": lyrics_text,
        "cover_observations": cover_observations or {},
        "singer_identity": singer_identity or "",
        "cover_art": os.path.basename(cover_path) if cover_path else "",
        "clap_embedding_model": CLAP_MODEL_ID if clap_vector is not None else "",
        "clap_embedding_dimension": CLAP_EMBEDDING_DIMENSION if clap_vector is not None else 0,
        "clap_embedding_aggregation": (
            "mean_of_l2_normalized_10s_windows_then_l2_normalized"
            if clap_vector is not None else ""
        ),
        "clap_embedding": clap_vector or [],
        # Raw per-stem transcribed MIDI for this recording. Stored so melody,
        # contour, motif and range questions asked after a /load are answered
        # from the actual notes rather than from whatever prose happened to be
        # written during the original scan.
        "stem_midi": _stem_notes_to_json(stem_midi) if stem_midi else {},
        "stem_midi_format": (
            "compact_v1: t=onset_s, d=duration_s, m=midi_note, n=note_name, "
            "v=amplitude, k=drum_type"
        ) if stem_midi else "",
        "stem_midi_complete": bool(stem_midi) and bool(FULL_MIDI_TRANSCRIPTION),
        "structure_sections": [
            {
                "name": s.get("name"),
                "start": round(float(s.get("start", 0.0)), 2),
                "end": round(float(s.get("end", 0.0)), 2),
                "cluster": s.get("cluster", ""),
            }
            for s in (structure_sections or [])
        ],
        "bpm": bpm,
        "key": key,
    }

    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

    return path, cover_path


def load_song_data(filename):
    """Load a saved song by filename, preserving spaces and special characters.

    Matching order:
      1. Exact basename as given (after light sanitisation only)
      2. Same with .json appended
      3. Case-insensitive match against files in SAVE_DIR
      4. Match ignoring only differences in runs of whitespace
    """
    os.makedirs(SAVE_DIR, exist_ok=True)

    raw = (filename or "").strip().strip('"').strip("'")
    if not raw:
        return None

    safe = _sanitize_saved_name(raw)
    if not safe:
        return None

    candidates = [os.path.join(SAVE_DIR, safe)]
    if not safe.lower().endswith(".json"):
        candidates.append(os.path.join(SAVE_DIR, safe + ".json"))
    # Also try the raw basename if the user typed a path-like string.
    raw_base = os.path.basename(raw)
    if raw_base and raw_base != safe:
        candidates.append(os.path.join(SAVE_DIR, raw_base))
        if not raw_base.lower().endswith(".json"):
            candidates.append(os.path.join(SAVE_DIR, raw_base + ".json"))

    path = None
    for cand in candidates:
        if os.path.exists(cand):
            path = cand
            break

    if path is None:
        target = safe[:-5] if safe.lower().endswith(".json") else safe
        target_l = target.lower()
        target_ws = re.sub(r"\s+", " ", target_l).strip()
        # Quote-folded comparison too (see _fold_quotes_for_match): a track
        # title saved from tag metadata routinely uses a typographic curly
        # apostrophe, while a typed name almost always uses a plain one, and
        # the two are visually near-identical. Every OTHER matching pass here
        # (exact, +.json, case-insensitive, whitespace) already runs on
        # `target`/`safe`, so this needs to be a genuinely separate criterion,
        # not a modification of the existing ones -- a file that already uses
        # the "right" apostrophe must still match exactly as before.
        target_folded = _fold_quotes_for_match(target_l)
        match = None
        try:
            for f in os.listdir(SAVE_DIR):
                if not f.lower().endswith(".json"):
                    continue
                stem_name = f[:-5]
                fl = f.lower()
                stem_l = stem_name.lower()
                stem_ws = re.sub(r"\s+", " ", stem_l).strip()
                if (
                    stem_l == target_l
                    or fl == safe.lower()
                    or fl == (safe.lower() if safe.lower().endswith(".json") else safe.lower() + ".json")
                    or stem_ws == target_ws
                    or _fold_quotes_for_match(stem_l) == target_folded
                ):
                    match = os.path.join(SAVE_DIR, f)
                    break
        except Exception:
            pass

        if match is None:
            return None
        path = match

    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as e:
        raise RuntimeError(f"Could not read saved song file {path}: {e}")

    if not isinstance(data, dict):
        return None

    return data


def _command_remainder(text, flag):
    t = text.strip()
    if not t.lower().startswith(flag):
        return None
    rest = t[len(flag):]
    if rest and rest[0] not in ("=", " ", "\t"):
        return None
    return rest.lstrip("=").strip()


_QUOTE_FOLD_MAP = str.maketrans({
    "\u2018": "'", "\u2019": "'", "\u201a": "'", "\u201b": "'", "\u2032": "'",
    "\u201c": '"', "\u201d": '"', "\u201e": '"', "\u201f": '"', "\u2033": '"',
    "`": "'",
})


def _fold_quotes_for_match(s):
    """Fold every apostrophe/quote-mark variant to a plain ASCII one, for
    MATCHING ONLY -- never for the string that actually gets used to open a
    file.

    Track titles saved from tag metadata routinely use a typographic curly
    apostrophe (U+2019, e.g. "Mary\u2019s Garden"), because that's what most
    taggers, iTunes/Apple Music exports and streaming metadata write. A
    person typing the title at a terminal almost always types a plain
    keyboard apostrophe (U+0027) instead, and the two are close to
    indistinguishable in most terminal fonts. Without folding, a typed name
    that is visually identical to the real file fails to match it.
    """
    return (s or "").translate(_QUOTE_FOLD_MAP)


def _find_saved_file_by_folded_match(candidate):
    """Look up `candidate` against every saved .json file, ignoring which
    apostrophe/quote variant either side used. Returns the REAL on-disk
    filename on a match (never the candidate text itself), or None.
    """
    if not candidate:
        return None
    try:
        saved = [
            f for f in os.listdir(SAVE_DIR) if f.lower().endswith(".json")
        ] if os.path.isdir(SAVE_DIR) else []
    except Exception:
        return None
    cand_json = candidate if candidate.lower().endswith(".json") else candidate + ".json"
    for key in (cand_json, candidate):
        folded = _fold_quotes_for_match(key).lower()
        for f in saved:
            if _fold_quotes_for_match(f).lower() == folded:
                return f
    return None


def _resolve_next_saved_track_argument(text, allow_best_effort_fallback=False):
    """Consume ONE saved-track name from the front of `text`, the same way
    /load has always resolved its argument, and return (filename, remainder).

    This is the single resolution algorithm both /load and /loadcompare use,
    so a name that works for one works identically for the other. It used to
    live only inline in the /load handler; /loadcompare had its own, much
    thinner version (just _match_saved_filename_prefix) that skipped the
    richest fallback below -- so /loadcompare could only resolve a name that
    was typed with a literal ".json" suffix (quoted or not), while /load could
    also resolve a bare, unquoted title with no extension at all by matching
    it against the actual saved filenames. That gap is what made /loadcompare
    look like it "insisted on .json" and "couldn't handle apostrophes": a
    title typed without .json never reached a step that tries appending it,
    so a name like Guns N' Roses - Don't Stop, typed the same casual way /load
    accepts it, simply never matched -- the apostrophe was never actually the
    problem, the missing extension was, but the two tend to be dropped
    together by anyone typing casually, so they read as one failure.

    Tries, in order:
      1. Exact prefix match against real on-disk filenames (handles quoted OR
         unquoted, any punctuation including apostrophes, with or without a
         wrapping quote character) -- see _match_saved_filename_prefix.
      2. A quoted argument with no exact on-disk match yet (e.g. the name is
         typed slightly differently from disk) -- closing quote preferred
         right after ".json" if present, else the last quote in the text.
      3. Unquoted text containing ".json" -- everything up to and including
         it is the name.
      4. No ".json" anywhere -- shlex-tokenise the remainder and try the
         LONGEST prefix of tokens that matches a saved file, with and without
         an implicit ".json" appended. This is what lets a bare, unquoted
         title with no extension resolve at all.

    `allow_best_effort_fallback`: when nothing above matches, /load's own
    long-standing behaviour is to still attempt SOMETHING (the first token, or
    the whole remaining text) so a clear "not found" message can be shown
    rather than a generic parse error. /loadcompare does NOT want this: it
    needs to know definitively when no more names are found, so it can treat
    everything left over as the comparison question instead of accidentally
    swallowing the question as a bogus track name. False by default; /load's
    handler passes True to keep its exact previous behaviour.

    Returns (filename_or_None, remainder). filename is None only when nothing
    could be resolved and allow_best_effort_fallback is False.
    """
    rest = (text or "").strip()
    if not rest:
        return None, rest

    saved_match = _match_saved_filename_prefix(rest)
    if saved_match is not None:
        return saved_match

    # 1) Quoted filename.
    if rest[:1] in ("'", '"'):
        q = rest[0]
        body = rest[1:]
        close_m = re.search(r"\.json" + re.escape(q), body, re.IGNORECASE)
        if close_m:
            close_idx = close_m.end() - 1
            candidate = body[:close_idx].strip()
            # This boundary is unambiguous about WHERE the name ends, but says
            # nothing about whether the typed text matches the real filename
            # byte-for-byte -- a quote-variant mismatch (see
            # _fold_quotes_for_match) would otherwise sail through here
            # untouched and only fail two steps later, at the actual file
            # open, with a confusing "not found" for a file that visibly
            # exists. Correct to the real on-disk name when a folded match is
            # found; otherwise return the typed text as before so a genuine
            # typo still gets a clear "not found" from the load step.
            real = _find_saved_file_by_folded_match(candidate)
            if real is not None or allow_best_effort_fallback:
                return (real or candidate), body[close_idx + 1:].strip()
            return None, rest

        # No ".json" inside the quotes to anchor on. There can be more than
        # one quoted argument in the remaining text (/loadcompare's second
        # and third track names), so the closing quote for THIS argument is
        # not necessarily the last quote character in the whole string --
        # grabbing the last one (as a single /load argument safely can, since
        # it only ever has one) would swallow every later quoted name too.
        # Instead, try each closing-quote candidate NEAREST first, and accept
        # the first one whose enclosed text is an actual saved file (with or
        # without an implied ".json") -- exactly the same on-disk check step
        # 3 below performs, just applied per-candidate instead of once.
        close_positions = [m.start() for m in re.finditer(re.escape(q), body)]
        if close_positions:
            try:
                saved = [
                    f for f in os.listdir(SAVE_DIR)
                    if f.lower().endswith(".json")
                ] if os.path.isdir(SAVE_DIR) else []
            except Exception:
                saved = []
            # Keyed on the QUOTE-FOLDED lowercase name, so a typed straight
            # apostrophe matches a saved file's curly one (see
            # _fold_quotes_for_match) -- values are still the real filenames.
            saved_l = {_fold_quotes_for_match(f).lower(): f for f in saved}

            for idx in close_positions:
                cand = body[:idx].strip()
                cand_json = cand if cand.lower().endswith(".json") else cand + ".json"
                cand_json_f = _fold_quotes_for_match(cand_json).lower()
                cand_f = _fold_quotes_for_match(cand).lower()
                if cand_json_f in saved_l or cand_f in saved_l:
                    matched = saved_l.get(cand_json_f, saved_l.get(cand_f, cand_json))
                    return matched, body[idx + 1:].strip()

            # Nothing between any candidate quote pair matched a real file.
            # /load's long-standing behaviour is to still guess (the LAST
            # quote in the text) so a clear "not found" message can follow;
            # /loadcompare must NOT guess a nonexistent name here, since that
            # would be reported as a track and break the load, so it stops
            # and leaves the text for the caller to treat as the question.
            if allow_best_effort_fallback:
                close_idx = close_positions[-1]
                return body[:close_idx].strip(), body[close_idx + 1:].strip()

    # 2) Unquoted, contains ".json".
    json_m = re.search(r"\.json\b", rest, re.IGNORECASE)
    if json_m:
        candidate = rest[: json_m.end()].strip().strip('"').strip("'")
        real = _find_saved_file_by_folded_match(candidate)
        remainder = rest[json_m.end():].strip()
        if real is not None or allow_best_effort_fallback:
            return (real or candidate), remainder
        return None, rest

    # 3) No ".json" anywhere -- try the longest token prefix, with and
    #    without an implicit ".json", against what is actually on disk.
    #
    # Plain whitespace splitting, NOT shlex. By this point any leading quote
    # character has already been consumed by step 1 above, so there is no
    # shell-style quoting left to interpret -- and shlex actively mishandles
    # a track title with an apostrophe in it. An ODD number of apostrophes
    # in the remaining text raises ValueError (harmlessly caught below), but
    # an EVEN number -- e.g. "Guns N' Roses - Don't Stop", which has two --
    # is silently parsed as one shell-quoted span running from the first
    # apostrophe to the second, swallowing the space and both apostrophes
    # and producing a mangled token ("N Roses - Dont") that can never match
    # the real filename. This is exactly the class of failure reported:
    # an unquoted, extension-less title containing an apostrophe. A plain
    # split() has no quoting semantics at all, so every apostrophe stays
    # exactly where it was typed.
    tokens = rest.split() if rest else []

    if tokens:
        try:
            saved = [
                f for f in os.listdir(SAVE_DIR)
                if f.lower().endswith(".json")
            ] if os.path.isdir(SAVE_DIR) else []
        except Exception:
            saved = []
        saved_l = {_fold_quotes_for_match(f).lower(): f for f in saved}

        for n in range(len(tokens), 0, -1):
            cand = " ".join(tokens[:n]).strip('"').strip("'")
            cand_json = cand if cand.lower().endswith(".json") else cand + ".json"
            cand_json_f = _fold_quotes_for_match(cand_json).lower()
            cand_f = _fold_quotes_for_match(cand).lower()
            if cand_json_f in saved_l or cand_f in saved_l:
                matched_name = saved_l.get(cand_json_f, saved_l.get(cand_f, cand_json))
                remainder = " ".join(tokens[n:]).strip()
                return matched_name, remainder

        if allow_best_effort_fallback:
            return tokens[0].strip('"').strip("'"), " ".join(tokens[1:]).strip()

    if allow_best_effort_fallback:
        return rest.strip('"').strip("'"), ""

    return None, rest


def _match_saved_filename_prefix(text):
    """Match an actual saved JSON filename at the start of command text.

    This deliberately uses the filenames that exist on disk rather than shell
    tokenisation or punctuation-based parsing, so apostrophes and other
    printable filename characters remain part of the filename. Returns
    (filename, trailing_text) or None.

    Comparison is done on QUOTE-FOLDED copies (see _fold_quotes_for_match) so
    a plain keyboard apostrophe in the typed text matches a saved file that
    uses a typographic one (curly quotes are what most tag/metadata sources
    write, e.g. "Mary\u2019s Garden" saved from a music tagger, while a person
    typing the title normally types a straight one) -- without this, such a
    file would silently fail to match here and fall through to a later step
    that (previously) trusted the typed text without checking it against disk
    at all, surfacing as a confusing "not found" for a file that visibly
    exists. Folding never changes string length, so offsets computed on the
    folded copies are safe to use for slicing the ORIGINAL text.
    """
    rest = (text or "").lstrip()
    if not rest or not os.path.isdir(SAVE_DIR):
        return None

    try:
        saved = [
            f for f in os.listdir(SAVE_DIR)
            if f.lower().endswith(".json") and os.path.isfile(os.path.join(SAVE_DIR, f))
        ]
    except Exception:
        return None

    # Longest-first prevents a shorter saved name from stealing the prefix of
    # a longer one. Matching is case-insensitive, while returning the actual
    # on-disk spelling/path-safe filename.
    saved.sort(key=len, reverse=True)

    if rest[:1] in ("'", '"'):
        quote = rest[0]
        body = rest[1:]
        body_lf = _fold_quotes_for_match(body).lower()
        for name in saved:
            nlf = _fold_quotes_for_match(name).lower()
            if body_lf.startswith(nlf):
                end = len(name)
                if len(body) > end and body[end] == quote:
                    return name, body[end + 1:].strip()
        return None

    rest_lf = _fold_quotes_for_match(rest).lower()
    for name in saved:
        nlf = _fold_quotes_for_match(name).lower()
        if not rest_lf.startswith(nlf):
            continue
        end = len(name)
        if len(rest) == end or rest[end].isspace():
            return name, rest[end:].strip()

    return None


def list_audio_files_in_folder(folder):
    """Non-recursive listing of audio files in folder (stable sorted order)."""
    folder = os.path.abspath(os.path.expanduser(folder))
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Not a directory: {folder}")
    out = []
    for name in sorted(os.listdir(folder)):
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            continue
        ext = os.path.splitext(name)[1].lower()
        if ext in AUDIO_EXTENSIONS:
            out.append(path)
    return out


def run_fresh_track_analysis_heavy(
    track_path,
    *,
    audio_temp_files,
    dsp_temp_files,
    stem_temp_files,
    demucs_out_dirs,
):
    """
    Full /listen-quality analysis for one local file, MINUS singer identity
    resolution. Does not touch writer_history or session token counters.

    Singer identity resolution is deliberately NOT done here — see
    resolve_identity_and_finalize(). It's a plain-text Ollama call with no
    dependency on Music Flamingo/Demucs/Omnizart/Essentia, so splitting it
    out lets it run in a separate, model-free process for isolated batch
    tracks (see run_batch_one_finish() / BATCH_SPLIT_IDENTITY_PROCESS): the
    torch/TF/MPS allocations from this heavy stage are not always reliably
    reclaimed within the SAME process even after unload + gc + cache-empty
    (a known MPS/TF limitation), so previously Ollama could try to load the
    writer model for identity resolution on top of that stranded memory and
    get OOM-killed (SIGKILL / "child exited -9") right at that stage.

    Returns a dict with everything resolve_identity_and_finalize() and
    save_song_data() need.
    """
    track_path = os.path.abspath(os.path.expanduser(track_path))
    if not os.path.exists(track_path):
        raise FileNotFoundError(f"File not found: {track_path}")

    # Free Ollama writer weights before the heavy analysis peak so MF/Demucs/
    # Omnizart are not competing with a resident 30B model. Chat history in the
    # parent Musiclyse process is unaffected (separate address space / stays
    # in Python RAM). Results of this analysis stay in local variables below.
    if globals().get("BATCH_UNLOAD_OLLAMA", True) and _is_batch_context():
        try:
            status("Unloading Ollama writer before analysis (batch)...")
            ollama_unload_model()
            status_done("Ollama writer unloaded for analysis phase")
        except Exception:
            pass

    metadata = {}
    cover_b64 = None
    cover_bytes_for_save = None
    cover_mime = "image/jpeg"
    cover_observations = {}
    singer_identity = ""

    if ENABLE_FILE_METADATA:
        status("Reading file metadata/tags...")
        try:
            meta, cover_bytes, cover_mime = extract_audio_metadata(track_path)
            metadata = meta or {}
            if cover_bytes:
                prepared = prepare_cover_image_for_ollama(cover_bytes, cover_mime)
                if prepared:
                    cover_bytes_for_save = prepared
                    cover_b64 = base64.b64encode(prepared).decode("utf-8")
                    cover_mime = _guess_image_mime(prepared)
        except Exception as e:
            print(f"  (metadata/cover extraction skipped: {e})")

    if (
        ENABLE_COVER_ART_DESCRIPTION
        and cover_b64
        and cover_b64 != NO_COVER_SENTINEL
    ):
        status("Describing embedded cover art...")
        try:
            obs = describe_cover_art(cover_b64)
            if obs:
                cover_observations = obs
        except Exception as e:
            print(f"  (cover description skipped: {e})")

    ext = os.path.splitext(track_path)[1].lower()
    if ext in (".wav", ".flac"):
        resolved_path = track_path
    elif track_path in audio_temp_files:
        resolved_path = audio_temp_files[track_path]
    else:
        status(f"Converting {ext} to WAV for compatibility...")
        resolved_path = convert_to_wav(track_path)
        audio_temp_files[track_path] = resolved_path

    ollama_unload_model()
    mf_model, mf_processor, _mf_device = get_music_flamingo()

    status("Listening — estimating era...")
    era_conversation = [
        {
            "role": "user",
            "content": [
                {"type": "text", "text": ERA_ANALYSIS_PROMPT},
                {"type": "audio", "path": resolved_path},
            ],
        }
    ]
    era_result = mf_generate(mf_model, mf_processor, era_conversation, max_new_tokens=1024)

    status("Listening — running full analysis (this can take a while)...")
    first_pass, mf_conversation, main_max_tokens = _mf_run_main_analysis(
        mf_model, mf_processor, resolved_path, deep=DEEP_MODE
    )

    objective_report = ""
    vocal_objective_report = ""
    essentia_report = ""
    dsp_path = None
    if track_path in dsp_temp_files:
        dsp_path = dsp_temp_files[track_path]
    else:
        status("Preparing higher-rate WAV for signal processing...")
        try:
            dsp_path = convert_to_wav(track_path, sample_rate=22050)
            dsp_temp_files[track_path] = dsp_path
        except Exception:
            dsp_path = track_path if ext in (".wav", ".flac") else resolved_path

    # Isolate vocals via Demucs *before* pitch tracking, when stem separation
    # is enabled, so pyin locks onto the singer instead of a sustained
    # bass/pad/guitar drone in the full mix. Reused below for the stem MIDI
    # report so Demucs only runs once per track.
    precomputed_stems, precomputed_demucs_out_dir = {}, None
    vocal_pitch_source = "full mix (no isolated vocal stem available)"
    if ENABLE_VOCAL_OBJECTIVE_REPORT and ENABLE_STEM_MIDI:
        precomputed_stems, precomputed_demucs_out_dir = _prepare_demucs_stems_for_track(
            track_path, stem_temp_files, demucs_out_dirs,
            status_fn=status, deep_mode=DEEP_MODE,
        )
        if precomputed_stems.get("vocals"):
            vocal_pitch_source = "isolated vocal stem (Demucs)"

    if dsp_path is not None:
        if ENABLE_OBJECTIVE_AUDIO_REPORT:
            status("Measuring beat/timbre with signal processing...")
            # track_path is the untouched source file; dsp_path is the mono
            # working WAV. Only the stereo measurement uses the former.
            objective_report = build_objective_audio_report(
                dsp_path, original_path=track_path
            )
        if ENABLE_VOCAL_OBJECTIVE_REPORT:
            status("Measuring vocal pitch/formant proxies...")
            _pitch_source_path = precomputed_stems.get("vocals") or dsp_path
            vocal_objective_report = build_vocal_objective_report(_pitch_source_path)
            if vocal_objective_report:
                vocal_objective_report += f"\nmeasurement source: {vocal_pitch_source}"
        if ENABLE_ESSENTIA_REPORT and ESSENTIA_AVAILABLE:
            status("Measuring tempo/key/spectral features with Essentia...")
            essentia_report = build_essentia_report(dsp_path)

    genre_mood_report = ""
    panns_genre_tags = []
    if ENABLE_GENRE_MOOD_TAGGING and dsp_path is not None:
        status("Cross-checking genre/mood with an independent classifier...")
        try:
            genre_mood_report, panns_genre_tags = build_genre_mood_signal_report(dsp_path)
        except Exception as e:
            print(f"  (genre/mood signal skipped: {e})")
            genre_mood_report = ""
            panns_genre_tags = []

    vocal_result = ""
    confirmation_result = ""
    initial_lead = ""
    initial_backing = ""
    confirm_lead = ""
    confirm_confidence = ""
    final_lead = ""
    vocal_pitch = {"median": None, "low": None, "high": None, "note": None}
    median_f0 = None
    no_clear_vocals = False
    multi_voice_fields = {}

    if ENABLE_VOCAL_PASS:
        status("Listening — estimating singer profile...")
        vocal_prompt_text = VOCAL_ANALYSIS_PROMPT
        if vocal_objective_report:
            vocal_prompt_text += (
                "\n\nObjective vocal measurements (evidence only, not proof):\n"
                f"{vocal_objective_report}"
            )
        vocal_conversation = [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": vocal_prompt_text},
                    {"type": "audio", "path": resolved_path},
                ],
            }
        ]
        vocal_result = mf_generate(mf_model, mf_processor, vocal_conversation, max_new_tokens=768)
        if vocal_result:
            initial_lead, initial_backing = parse_vocal_tags(vocal_result)
        vocal_pitch = extract_vocal_pitch_summary(vocal_objective_report) if vocal_objective_report else vocal_pitch
        median_f0 = vocal_pitch.get("median")
        _vp_flag = _parse_vocals_present_flag(vocal_result or "")
        no_clear_vocals = _vp_flag in ("no",)
        no_clear_vocals, _early_vocal_salvage, _ = _salvage_false_no_vocals(
            vocal_result,
            no_clear_vocals,
            median_f0=median_f0,
            vocal_objective_report=vocal_objective_report or "",
            stem_midi_report="",
            initial_lead=initial_lead,
        )
        if ENABLE_VOCAL_CONFIRMATION_PASS and vocal_result and not no_clear_vocals:
            should_confirm = False
            if initial_lead in UNCERTAIN_YOUNG_CATEGORIES:
                should_confirm = True
            elif initial_lead in FEMALE_LEAD_CATEGORIES and (
                (median_f0 is not None and median_f0 >= VOCAL_CONFIRMATION_F0_THRESHOLD)
                or (median_f0 is None and VOCAL_CONFIRMATION_WITHOUT_F0)
            ):
                should_confirm = True
            elif initial_lead in (MALE_LEAD_CATEGORIES | ADOLESCENT_MALE_CATEGORIES) and (
                median_f0 is not None
                and F0_MALE_HIGH_CONFIRM_HZ is not None
                and median_f0 >= float(F0_MALE_HIGH_CONFIRM_HZ)
            ):
                # High track-wide median on a male-tagged lead is a common
                # female→male mislabel path; run confirmation before locking in.
                should_confirm = True
            elif initial_lead == "mixed_leads":
                should_confirm = True
            else:
                # Confirm when the vocal pass itself flags multiple distinct voices.
                _mv_early = parse_multi_voice_fields(vocal_result or "")
                if _mv_early.get("voice_arrangement") in ("duet_co_leads", "call_response"):
                    should_confirm = True
                elif _mv_early.get("num_distinct_voices") in ("2", "3", "3+", "two", "three"):
                    should_confirm = True
            if should_confirm:
                status("Listening — confirming lead voice category...")
                confirmation_conversation = [
                    {
                        "role": "user",
                        "content": [
                            {"type": "text", "text": VOCAL_CONFIRMATION_PROMPT},
                            {"type": "audio", "path": resolved_path},
                        ],
                    }
                ]
                confirmation_result = mf_generate(
                    mf_model, mf_processor, confirmation_conversation, max_new_tokens=256
                )
                if confirmation_result:
                    confirm_lead, confirm_confidence = parse_vocal_confirmation(confirmation_result)
        # Populate multi_voice_fields BEFORE the final-lead decision so duets are honoured.
        multi_voice_fields = parse_multi_voice_fields(vocal_result or "")
        if confirmation_result:
            for _k, _v in parse_multi_voice_fields(confirmation_result).items():
                if _v and not multi_voice_fields.get(_k):
                    multi_voice_fields[_k] = _v

        final_lead = choose_final_vocal_lead(
            initial_lead, confirm_lead, confirm_confidence, confirmation_result,
            median_f0=median_f0,
            multi_voice_fields=multi_voice_fields,
        )
        final_lead = _apply_vocal_age_guard(
            final_lead,
            (vocal_result or "") + "\n" + (confirmation_result or ""),
        )
        final_lead = _apply_f0_pitch_guard(
            final_lead,
            median_f0,
            low_f0=vocal_pitch.get("low") if isinstance(vocal_pitch, dict) else None,
            high_f0=vocal_pitch.get("high") if isinstance(vocal_pitch, dict) else None,
        )



    # If the main MF pass still claims "no music" but DSP heard a track, replace
    # the failure text with a conservative scaffold before self-check / save.
    first_pass = _mf_salvage_empty_analysis(
        first_pass, objective_report, essentia_report, vocal_result
    )

    if FAST_MODE:
        revised = first_pass
    else:
        status("Double-checking its own analysis for overconfident claims...")
        self_check_text = SELF_CHECK_PROMPT + "\n\n" + STYLE_EVIDENCE_FIREWALL
        if vocal_result or confirmation_result:
            self_check_text += "\n\nVocal profile evidence:\n"
            if vocal_result:
                self_check_text += f"{vocal_result}\n"
            if confirmation_result:
                self_check_text += f"{confirmation_result}\n"
        objective_crosscheck_parts = []
        if essentia_report:
            objective_crosscheck_parts.append(essentia_report)
        if objective_report:
            objective_crosscheck_parts.append(objective_report)
        if objective_crosscheck_parts:
            self_check_text += (
                "\n\nIndependent signal-processing cross-checks "
                "(use only for tempo/beat, key/key strength when explicitly reported, timbre, "
                "element activity, dynamic range, and -- when a STRUCTURAL BOUNDARY CANDIDATES "
                "line is present -- section-timing in STRUCTURE; do NOT use librosa/Essentia "
                "spectral stats to invent GENRE or change vocal identity):\n"
                + "\n\n".join(objective_crosscheck_parts)
            )
            if genre_mood_report:
                self_check_text += (
                    "\n\nIndependent genre/mood classifier (PANNs/AudioSet) — this MAY be used "
                    "to revise GENRE_RANKED when it clearly conflicts with a rock/pop-punk top rank "
                    "driven mainly by guitar texture while this signal is electronic/dance/synth-pop. "
                    "See GENRE self-check rules.\n"
                    + genre_mood_report
                )
        mf_conversation.append(
            {"role": "assistant", "content": [{"type": "text", "text": first_pass}]}
        )
        mf_conversation.append(
            {"role": "user", "content": [{"type": "text", "text": self_check_text}]}
        )
        revised = mf_generate(mf_model, mf_processor, mf_conversation, max_new_tokens=main_max_tokens)

    # ------------------------------------------------------------------
    # SONG STRUCTURE (objective-first) — resolved here, once, for the run.
    # ------------------------------------------------------------------
    # Placed immediately before the unload because this is the last moment the
    # audio model is resident. It is only asked to NAME parts whose boundaries
    # have already been fixed by signal analysis, so the timestamps never
    # depend on it. Running it here (rather than in the finalize stage, as it
    # used to) avoids reloading the model after it has been freed, and makes
    # the resulting section map available to the stem MIDI pass below — so the
    # melody and intensity blocks are keyed to the SAME sections the writer is
    # later told are authoritative, instead of an earlier, different estimate.
    _structure_sections = []
    _bnd_pre = []
    _struct_grid = {}
    try:
        _total_duration_pre = _resolve_total_duration(
            track_path=track_path, dsp_path=dsp_path, objective_report=objective_report
        )
        _struct_audio_path = dsp_path or resolved_path or track_path
        if (
            _struct_audio_path
            and _total_duration_pre
            and not str(_struct_audio_path).startswith(("http://", "https://"))
            and os.path.exists(_struct_audio_path)
        ):
            # Tempo reconciliation (final_bpm) does not happen until later in
            # this function, so it cannot be referenced here -- doing so raised
            # NameError, which the except below swallowed, silently degrading
            # every scan to the evenly-spaced filler windows. The beat tracker
            # works without a hint; pass a measured tempo only when one already
            # exists at this point, purely to help it lock on faster.
            _struct_bpm_hint = None
            try:
                _struct_bpm_hint = (
                    extract_objective_bpm(objective_report)
                    or extract_essentia_bpm(essentia_report)
                )
            except Exception:
                _struct_bpm_hint = None

            status("Resolving song structure from the audio (cut -> cluster -> name)...")
            _y_struct, _sr_struct = librosa.load(_struct_audio_path, sr=None, mono=True)
            _structure_sections = _build_objective_first_structure(
                _struct_audio_path, _y_struct, _sr_struct, _total_duration_pre,
                mf_model, mf_processor, bpm_hint=_struct_bpm_hint,
            )
            # Keep the metrical grid: the late refinement pass snaps any
            # lyric/MIDI-derived boundary onto the same bar lines, so added
            # boundaries are as precise as the acoustic ones.
            try:
                _sb, _sd, _sbl, _ = _beat_and_downbeat_grid(
                    _y_struct, _sr_struct, bpm_hint=_struct_bpm_hint
                )
                _struct_grid = {"beats": _sb, "downbeats": _sd, "beat_len": _sbl}
            except Exception:
                _struct_grid = {}
            del _y_struct
            if _structure_sections:
                _bnd_pre = [float(s["start"]) for s in _structure_sections[1:]]
                status_done(
                    f"Structure resolved from audio ({len(_structure_sections)} sections)"
                )
    except Exception as e:
        # Loud, with a traceback. This used to print a single easy-to-miss line,
        # so a hard failure looked exactly like a successful scan right up until
        # the section map turned out to be evenly-spaced filler.
        import traceback
        print(f"  !! STRUCTURE DETECTION FAILED: {type(e).__name__}: {e}")
        traceback.print_exc()
        _structure_sections = []

    # Music Flamingo's job for this track is done as of the self-check
    # revision above — free it now, before possibly loading Whisper for the
    # lyrics pass, so the two models are never resident in RAM/VRAM at once.
    unload_music_flamingo()

    tag_lyrics = str((metadata or {}).get("lyrics") or "").strip()
    _lyric_chunks = []  # default when the Whisper lyrics pass below is skipped
    # Any non-empty file-tag lyrics are authoritative. Do not let a short tag
    # block fall through to snippet-level Whisper transcription.
    skip_mf_lyrics = (
        SKIP_MF_LYRICS_WHEN_TAGS_PRESENT
        and bool(tag_lyrics)
    )
    if skip_mf_lyrics:
        status("Skipping lyrics transcription pass (file-tag lyrics already present)...")
        revised += (
            "\n\nLYRICS: reliable lyrics are present and are the preferred source for lyric questions."
        )
    else:
        status("Transcribing full lyrics with Whisper (dedicated pass)...")
        # Whisper (WHISPER_MODEL_ID) replaces Music Flamingo for this pass —
        # Music Flamingo hallucinates readily on song lyrics (inventing
        # lines, drifting into unrelated prose, "correcting" words toward
        # remembered/expected lyrics), whereas Whisper is a dedicated,
        # comparatively literal ASR model. Whisper is lazy-loaded here (only
        # for the duration of this pass) and released again immediately
        # after, same RAM-optimization principle Music Flamingo used above.
        # As before, two independent decodes (deterministic + sampled) are
        # cross-checked against each other to catch ungrounded/hallucinated
        # spans that a single pass wouldn't reveal.
        full_lyrics, _lyric_chunks = whisper_transcribe_lyrics_full(resolved_path, cross_check=True)
        unload_whisper()

        if full_lyrics and full_lyrics.strip():
            revised += f"\n\nLYRICS HEARD IN AUDIO (secondary evidence; do not use when reliable lyrics are present):\n{full_lyrics}"

        lyric_repetition_report = build_lyric_repetition_report(_lyric_chunks)
        if lyric_repetition_report:
            revised += "\n\n" + lyric_repetition_report

    revised += f"\n\n11. ERA / RELEASE PERIOD (isolated dedicated pass):\n{era_result}"
    try:
        revised += _build_era_remaster_caveat(objective_report)
    except Exception:
        pass
    if vocal_result:
        revised += (
            "\n\nVOCAL / SINGER PROFILE (isolated dedicated pass):\n"
            + _mark_superseded_vocal_tags(vocal_result, locals().get("final_lead"))
        )
        if confirmation_result:
            revised += (
                "\n\nVOCAL CONFIRMATION PASS:\n"
                + _mark_superseded_vocal_tags(confirmation_result, locals().get("final_lead"))
            )
        f0_text = f"{median_f0} Hz" if median_f0 is not None else "unavailable"
        # Merge any additional detail not already captured above.
        if confirmation_result:
            conf_mv = parse_multi_voice_fields(confirmation_result)
            for k, v in conf_mv.items():
                if v and (not multi_voice_fields.get(k) or multi_voice_fields.get(k) in ("", "unparsed", "uncertain")):
                    multi_voice_fields[k] = v
        # INDEPENDENT TRIGGER: even when MF's own pass (and the confirmation
        # pass) reported only a single voice, check the objective f0 evidence
        # on its own merits. A male-verse/female-chorus track that MF's one
        # holistic listen just didn't notice as two voices previously had NO
        # path to correction here at all -- this closes that gap. Stricter
        # thresholds than the refinement case below, since upgrading MF's own
        # single-voice call is a bigger claim than adding detail to a call MF
        # already made.
        if (
            ENABLE_INDEPENDENT_F0_MULTI_SINGER_TRIGGER
            and (final_lead or initial_lead) not in ("mixed_leads", "")
            and vocal_objective_report
        ):
            try:
                f0_independent = _refine_multi_singer_from_f0(
                    vocal_objective_report,
                    min_sep=INDEPENDENT_MULTI_SINGER_MIN_SEP_SEMITONES,
                    min_ratio=INDEPENDENT_MULTI_SINGER_MIN_RATIO,
                )
            except Exception:
                f0_independent = {}
            if f0_independent.get("num_distinct_voices") in ("2", "3+"):
                final_lead = "mixed_leads"
                for k, v in f0_independent.items():
                    if v:
                        multi_voice_fields[k] = v
                multi_voice_fields["multi_voice_evidence"] = (
                    (multi_voice_fields.get("multi_voice_evidence") or "")
                    + " [Upgraded from a single-voice MF classification on "
                    "independent objective f0 evidence — MF's own pass did not "
                    "report a second voice, but the measured pitch histogram "
                    "shows two well-separated, substantial centres consistent "
                    "with two different singers/registers.]"
                ).strip()

        if (final_lead or initial_lead) == "mixed_leads" and not multi_voice_fields.get("voice_arrangement"):
            multi_voice_fields["voice_arrangement"] = "duet_co_leads"
            if not multi_voice_fields.get("num_distinct_voices"):
                multi_voice_fields["num_distinct_voices"] = "2"
            # Refine multi-singer detection using objective f0 multi-peak hint
            if vocal_objective_report:
                f0_suggest = _refine_multi_singer_from_f0(vocal_objective_report)
                if f0_suggest:
                    for k, v in f0_suggest.items():
                        if v and (not multi_voice_fields.get(k) or multi_voice_fields.get(k) in ("", "unparsed", "uncertain")):
                            multi_voice_fields[k] = v
                    # If f0 suggests two distinct centres, strongly consider mixed_leads
                    if f0_suggest.get("num_distinct_voices") in ("2", "3+"):
                        if final_lead not in ("mixed_leads",):
                            final_lead = "mixed_leads"
                            multi_voice_fields["voice_arrangement"] = f0_suggest.get("voice_arrangement", "duet_co_leads")
                            if not multi_voice_fields.get("co_lead_detail"):
                                multi_voice_fields["co_lead_detail"] = f0_suggest.get("co_lead_detail", "two distinct pitch centres from f0 analysis")
        revised += (
            "\n\nVOCAL DECISION AUDIT (audio-only evidence for vocal age/gender):\n"
            f"- Initial isolated lead profile: {initial_lead or 'unparsed'}\n"
            f"- Confirmation pass: {confirm_lead or 'not run/unparsed'} (confidence={confirm_confidence or 'n/a'})\n"
            f"- Objective median f0: {f0_text}\n"
            f"- FINAL LEAD PROFILE: {final_lead or 'unknown'}\n"
            f"- BACKING PROFILES: {initial_backing or 'uncertain'}\n"
            "This is audio-only evidence. If a SINGER IDENTITY RESOLUTION block appears later in this analysis, use that for user-facing singer-identity claims; otherwise use FINAL LEAD PROFILE. Do not override a well-supported combined judgment with pitch impressions alone. If FINAL LEAD PROFILE is unknown/unparsed, do not treat free-text LEAD_PROFILE / LEAD_CATEGORY lines earlier in the vocal pass as a settled gender/age claim — those lines were not accepted as structured final tags. A very high objective median f0 can demote male/adolescent tags to uncertain; when FINAL is uncertain, prefer SINGER IDENTITY RESOLUTION (metadata + cover + pitch constraint) over any earlier free-text male claim."
        )
        mv_block = format_multi_voice_audit(
            multi_voice_fields, final_lead or initial_lead, initial_backing or "uncertain"
        )
        if mv_block:
            revised += "\n\n" + mv_block
        # Presence salvage: failed lyric pass / false MF 'no vocals' must not
        # poison the saved analysis or the writer reply.
        _salv_note = locals().get('_early_vocal_salvage') or ''
        if not _salv_note:
            _, _salv_note, _ = _salvage_false_no_vocals(
                vocal_result,
                no_clear_vocals,
                median_f0=median_f0,
                vocal_objective_report=(vocal_objective_report or ''),
                stem_midi_report='',
                initial_lead=(initial_lead or final_lead or ''),
            )
        if _salv_note and 'VOCAL PRESENCE SALVAGE' not in (revised or ''):
            revised += '\n\n' + _salv_note
            if 'VOCALS_PRESENT=yes' not in revised:
                revised += '\nVOCALS_PRESENT=yes  # from objective/structured salvage'
    elif median_f0 is not None and _objective_evidence_of_vocals(median_f0=median_f0):
        # MF returned empty/unusable vocal pass but pyin heard a voice
        _ps = (
            "VOCAL PRESENCE SALVAGE: no usable Music Flamingo vocal pass, but objective "
            f"voiced pitch median ~{median_f0} Hz indicates a human voice is present. "
            "Treat VOCALS_PRESENT=yes; age/gender may be uncertain. Do not claim the track "
            "is instrumental solely because lyrics failed or the clip is short."
        )
        if 'VOCAL PRESENCE SALVAGE' not in (revised or ''):
            revised += '\n\n' + _ps + '\nVOCALS_PRESENT=yes  # from objective pitch salvage'
            no_clear_vocals = False

    if ENABLE_VOCAL_OBJECTIVE_REPORT:
        pitch_lines = ["VOCAL PITCH REPORT (independent of lead age/gender category):"]
        if median_f0 is None:
            pitch_lines.append("- No reliable voiced pitch detected in the scanned portion.")
        else:
            pitch_lines.append(f"- objective voiced pitch median: {median_f0} Hz")
            if vocal_pitch.get("note"):
                pitch_lines.append(f"- approximate median note: {vocal_pitch['note']}")
            if vocal_pitch.get("low") is not None and vocal_pitch.get("high") is not None:
                pitch_lines.append(
                    f"- 5-95 percentile range: {vocal_pitch['low']}-{vocal_pitch['high']} Hz"
                )
            pitch_lines.append(
                "- Prefer median + 5–95 percentile range for the main vocal range. Median f0 is also used as a soft constraint on lead age/gender tags (high median can demote an overconfident post-puberty-male claim; it does not invent gender alone). "
                "Do not treat absolute extremes from stem MIDI as the sung range."
            )
        revised += "\n\n" + "\n".join(pitch_lines)

    mf_bpm_val = extract_bpm_from_text(first_pass)
    revised_bpm_val = extract_bpm_from_text(revised)
    if revised_bpm_val is not None:
        mf_bpm_val = revised_bpm_val
    essentia_bpm_val = extract_essentia_bpm(essentia_report) if essentia_report else None
    objective_bpm_val = extract_objective_bpm(objective_report) if objective_report else None
    essentia_median_bpm_val = extract_essentia_median_bpm(essentia_report) if essentia_report else None
    objective_median_bpm_val = extract_objective_median_bpm(objective_report) if objective_report else None
    _bpm_genre_hint = _genre_hint_from_analysis_text(
        revised or first_pass,
        panns_genre_tags,
    )
    final_bpm, bpm_note = reconcile_bpm(
        mf_bpm_val, essentia_bpm_val, objective_bpm_val,
        essentia_median_bpm=essentia_median_bpm_val,
        objective_median_bpm=objective_median_bpm_val,
        genre_hint=_bpm_genre_hint,
    )
    if final_bpm:
        revised += (
            f"\n\nRECOMMENDED TEMPO FOR DISCUSSION: {final_bpm} BPM. "
            f"Reasoning: {bpm_note}. "
            "This is the primary tempo to report to the user. "
            "State it as a concrete figure (e.g. 'about 158 BPM'). "
            "Do not expand it into a range unless this block itself marks the value as uncertain."
        )

    mf_key_val = extract_key_from_text(first_pass)
    revised_key_val = extract_key_from_text(revised)
    if revised_key_val is not None:
        mf_key_val = revised_key_val
    essentia_key_val, essentia_key_strength = (None, None)
    if essentia_report:
        parsed = extract_essentia_key_from_text(essentia_report)
        if parsed:
            essentia_key_val, essentia_key_strength = parsed
    final_key, key_note = reconcile_key(mf_key_val, essentia_key_val, essentia_key_strength)
    if final_key:
        revised += (
            f"\n\nRECOMMENDED KEY FOR DISCUSSION: {final_key}. "
            f"Reasoning: {key_note} "
            "This is the primary key to report to the user unless the reasoning above marks it uncertain."
        )

    # Numeric dynamics / loudness — prefer the ORIGINAL local file (full duration,
    # native rate/channels) so LUFS is not biased by the mono 22.05 kHz DSP WAV.
    # ReplayGain/RGAD tags are intentionally ignored (raw PCM decode only).
    crest_db_val = None
    crest_src = "objective (librosa) crest-factor proxy"
    lufs_val = lra_val = loudness_src = None
    try:
        _dyn_path = None
        if (
            track_path
            and not str(track_path).startswith(("http://", "https://"))
            and os.path.exists(track_path)
        ):
            _dyn_path = track_path
        elif track_path in dsp_temp_files:
            _dyn_path = dsp_temp_files[track_path]
        elif dsp_path is not None:
            _dyn_path = dsp_path
        if _dyn_path:
            crest_db_val = measure_crest_factor_db(_dyn_path)
            lufs_val, lra_val, loudness_src = measure_ebur128_loudness(_dyn_path)
    except Exception:
        crest_db_val = None
    if crest_db_val is None:
        crest_db_val = extract_crest_db_from_text(objective_report) if objective_report else None
    if crest_db_val is None and essentia_report:
        crest_db_val = extract_crest_db_from_text(essentia_report)
        if crest_db_val is not None:
            crest_src = "Essentia crest-factor proxy"
    dyn_block = format_recommended_dynamics_block(
        crest_db=crest_db_val,
        source_note=crest_src,
        lufs=lufs_val,
        lra=lra_val,
        loudness_source=loudness_src,
    )
    if dyn_block:
        revised += dyn_block
    else:
        revised += (
            "\n\nRECOMMENDED DYNAMICS FOR DISCUSSION: unavailable "
            "(could not compute EBU R128 loudness or crest-factor proxy from this file). "
            "Do not invent a dB/LUFS figure; fall back only to qualitative production notes."
        )

    measurement_parts = []
    if objective_report:
        measurement_parts.append(objective_report)
    if vocal_objective_report:
        measurement_parts.append(vocal_objective_report)
    if essentia_report:
        measurement_parts.append(essentia_report)
    if measurement_parts:
        revised += (
            "\n\n[Independent signal-processing report:\n"
            + "\n\n".join(measurement_parts)
            + "\nThis is computed directly from the audio (librosa/Essentia), not from the model above — "
            "use it only for tempo/beat, key/key strength when explicitly reported, timbre, "
            "low/mid/high element activity, dynamic range / loudness (crest-factor proxy), "
            "and vocal pitch/formant proxies. "
            "Do NOT use it to infer or revise GENRE."
        )

    if genre_mood_report:
        revised += "\n\n" + genre_mood_report
    try:
        _rec_g, _rec_g_note = reconcile_genre(revised, panns_genre_tags)
        revised += format_recommended_genre_block(_rec_g, _rec_g_note)
        # Genre-conditioned Essentia key refinement (edma vs temperley/krumhansl).
        if _rec_g and dsp_path is not None:
            _prev_k = extract_essentia_key_from_text(essentia_report) if essentia_report else None
            _pk, _ps = (None, None)
            if _prev_k:
                _pk, _ps = _prev_k if isinstance(_prev_k, tuple) else (_prev_k, None)
            _nk, _ns, _nnote = refine_essentia_key_with_genre(
                dsp_path, _rec_g, previous_key=_pk, previous_strength=_ps
            )
            if _nnote:
                revised += f"\n\nKEY PROFILE REFINEMENT: {_nnote}"
            if _nk and _nnote and "shifted" in _nnote:
                # Re-reconcile recommended key with the refined Essentia estimate
                _mfk = extract_key_from_text(revised) or extract_key_from_text(first_pass)
                _fk, _fnote = reconcile_key(_mfk, _nk, _ns)
                if _fk:
                    revised += (
                        f"\n\nRECOMMENDED KEY FOR DISCUSSION: {_fk}. "
                        f"Reasoning: {_fnote} (after genre-conditioned Essentia refinement). "
                        "This is the primary key to report to the user unless the reasoning marks it uncertain."
                    )
    except Exception:
        pass

    stem_midi_report = ""
    if ENABLE_STEM_MIDI:
        try:
            _get_omnizart()
            if precomputed_stems:
                # Reuse the separation already run above for vocal pitch
                # isolation -- avoids a second, redundant Demucs pass.
                stems = precomputed_stems
            else:
                if track_path in stem_temp_files:
                    stem_wav = stem_temp_files[track_path]
                else:
                    status("Preparing stereo WAV for Demucs/MIDI...")
                    stem_wav = convert_to_wav_for_stems(
                        track_path,
                        sample_rate=44100,
                        channels=2,
                        max_seconds=STEM_MIDI_MAX_SECONDS,
                    )
                    stem_temp_files[track_path] = stem_wav
                status("Running Demucs 6s stem separation (this can be slow)...")
                out_dir = tempfile.mkdtemp(prefix="demucs_")
                demucs_out_dirs.append(out_dir)
                stems = run_demucs_stems(
                    stem_wav, out_dir, shifts=DEMUCS_SHIFTS_DEEP if DEEP_MODE else DEMUCS_SHIFTS_FAST,
                )
            if not stems:
                stem_midi_report = "STEM MIDI REPORT unavailable: Demucs did not produce expected stems."
            else:
                whole_mix_tags = None
                if ENABLE_WHOLE_MIX_INSTRUMENT_TAGGING and dsp_path is not None:
                    try:
                        status("Tagging instruments on the full (un-separated) mix...")
                        whole_mix_tags = tag_full_mix_instruments(dsp_path)
                    except Exception as e:
                        print(f"  (whole-mix instrument tagging skipped: {e})")
                        whole_mix_tags = None
                status("Running Omnizart on each separated stem...")
                _total_duration = _resolve_total_duration(
                    track_path=track_path, dsp_path=dsp_path, objective_report=objective_report
                )
                # Reuse the section map resolved before the model unload. Only
                # fall back to parsing the model's own STRUCTURE= guess if that
                # pass produced nothing at all.
                if not _structure_sections:
                    _structure_sections, _bnd_pre, _ = _finalize_structure_sections(
                        revised or first_pass,
                        objective_report=objective_report,
                        lyric_chunks=locals().get("_lyric_chunks"),
                        total_duration=_total_duration,
                    )

                # Raw per-stem note events, kept so the melodic analysis and the
                # saved .json can work from actual notes rather than prose.
                _stem_notes_raw = {}
                # Per-stem energy/density, needed below to cross-check a
                # missing guitar tag against the actual Demucs guitar stem.
                _stem_activity_raw = []
                # Cross-stem instrument agreement (label -> [stem, ...]).
                _stem_convergence = {}
                # sections=None on purpose: the section-keyed blocks
                # (INTENSITY BY SECTION, MELODY PER SECTION) are built after the
                # refinement pass below, from the FINAL map, by
                # build_section_keyed_stem_blocks(). Generating them here would
                # bake in the pre-refinement section names and timings, leaving
                # two contradictory section lists in the evidence.
                stem_midi_report = build_omnizart_summaries(
                    stems, whole_mix_tags=whole_mix_tags,
                    bpm=final_bpm, sections=None, key=final_key,
                    notes_out=_stem_notes_raw,
                    mix_audio_path=dsp_path,
                    activity_out=_stem_activity_raw,
                    convergence_out=_stem_convergence,
                )
                # Melody/intensity are appended after refinement (see below).
                if whole_mix_tags is not None:
                    whole_mix_report = build_whole_mix_instrument_report(
                        dsp_path, tags=whole_mix_tags
                    )
                    if whole_mix_report:
                        stem_midi_report = stem_midi_report + "\n\n" + whole_mix_report
                        try:
                            _gan = guitar_absence_note_from_tags(
                                locals().get("whole_mix_tags"), whole_mix_report,
                                mix_audio_path=dsp_path,
                                stem_notes=locals().get("_stem_notes_raw"),
                                activity_metas=locals().get("_stem_activity_raw"),
                                cross_stem_agreement=locals().get("_stem_convergence"),
                            )
                            if _gan:
                                stem_midi_report = stem_midi_report + "\n\n" + _gan
                        except Exception:
                            pass
                _release_omnizart_memory()
        except Exception as e:
            print(f"  (stem MIDI skipped/unavailable: {e})")
            stem_midi_report = f"STEM MIDI REPORT unavailable: {e}"
    stem_midi_report = stem_midi_report or "STEM MIDI REPORT not run (disabled)."
    revised += "\n\n" + stem_midi_report

    # Presence salvage, second pass. The two _salvage_false_no_vocals() calls
    # above ran with stem_midi_report hardcoded to "" -- Demucs/Omnizart had
    # not run yet at that point in the pipeline, so they could only ever see
    # median_f0 / vocal_objective_report. If MF's vocal pass never wrote an
    # explicit VOCALS_PRESENT field at all (not "no", just absent -- a real,
    # separate MF failure mode from the explicit-"no" case those calls
    # already handle) and neither earlier check caught it, the track can
    # reach the writer with NO explicit vocals flag whatsoever, even when the
    # vocal stem's own transcription just measured a note a fraction of a
    # second into the track. This is the strongest evidence this pipeline
    # produces (see EARLIEST VOCAL ONSET above), and now that it exists,
    # this is the first point it CAN be checked.
    if "VOCALS_PRESENT=yes" not in revised and "EARLIEST VOCAL ONSET:" in stem_midi_report:
        revised += (
            "\n\nVOCAL PRESENCE SALVAGE (from vocal-stem transcription): the isolated vocal "
            "stem has a measured note onset (see EARLIEST VOCAL ONSET above), confirming a "
            "human voice is present in this recording. Treat VOCALS_PRESENT=yes; do not "
            "describe the track, or its opening, as instrumental on the strength of Music "
            "Flamingo's own vocal-pass prose alone when this measured onset contradicts it."
            "\nVOCALS_PRESENT=yes  # from vocal-stem onset salvage"
        )

    # Add authoritative structure block
    total_duration = _resolve_total_duration(
        track_path=track_path, dsp_path=dsp_path, objective_report=objective_report
    )

    _lyric_groups_for_structure = None
    try:
        _lc = locals().get("_lyric_chunks")
        _lyric_groups_for_structure = _detect_lyric_repetitions(_lc) if _lc else None
    except Exception:
        _lyric_groups_for_structure = None

    # ------------------------------------------------------------------
    # FINAL SECTION MAP — the audio model leads, measurement sharpens.
    # ------------------------------------------------------------------
    # The model's own STRUCTURE=[...] is the primary source: it listened to the
    # whole recording and understands song form. The acoustic pass is used to
    # pull each of its boundaries onto a detected change point or bar line
    # (precision), and lyric repetition to correct names where the same words
    # were labelled two different ways. The DSP map replaces it only when the
    # model produced nothing usable.
    _mf_sections = []
    try:
        _mf_sections = extract_structure_sections(revised or "")
    except Exception:
        _mf_sections = []

    structure_sections, _structure_source = _resolve_final_structure(
        _mf_sections,
        dsp_sections=_structure_sections,
        lyric_groups=_lyric_groups_for_structure,
        lyric_chunks=locals().get("_lyric_chunks"),
        total_duration=total_duration,
        grid=_struct_grid,
        stem_notes=locals().get("_stem_notes_raw"),
        bpm=locals().get("final_bpm"),
    )
    if structure_sections:
        boundary_seconds = [float(s["start"]) for s in structure_sections[1:]]
        revised = _overwrite_structure_field(revised, structure_sections)
        status_done(
            f"Section map resolved ({_structure_source}, "
            f"{len(structure_sections)} sections)"
        )
    else:
        structure_sections, boundary_seconds, _lg = _finalize_structure_sections(
            revised,
            objective_report=objective_report,
            stem_midi_report=locals().get("stem_midi_report") or "",
            lyric_chunks=locals().get("_lyric_chunks"),
            total_duration=total_duration,
        )
        _lyric_groups_for_structure = _lg or _lyric_groups_for_structure

    # Section-keyed stem evidence is generated here, once, from the FINAL map,
    # so the structure, melody, intensity and groove blocks can never disagree
    # about section names or timings.
    if structure_sections:
        try:
            _sk = build_section_keyed_stem_blocks(
                locals().get("stems") or {}, structure_sections,
                locals().get("_stem_notes_raw") or {},
                bpm=final_bpm, key=final_key,
            )
            if _sk:
                stem_midi_report = (
                    (locals().get("stem_midi_report") or "").rstrip() + "\n\n" + _sk
                )
                # `revised` was given a COPY of stem_midi_report above, and
                # Python strings are immutable, so the rebinding on the line
                # above never reached the analysis the writer actually sees.
                # Every section-keyed block -- per-stem INTENSITY BY SECTION,
                # the per-section drum groove, and MELODY PER SECTION -- was
                # computed correctly and then silently discarded, which is why
                # questions about a specific verse or chorus could only ever be
                # answered from the whole-track averages.
                revised += "\n\n" + _sk
        except Exception as e:
            print(f"  (section-keyed stem blocks skipped: {e})")

    structure_block = format_recommended_structure_block(
        structure_sections,
        objective_boundaries=boundary_seconds,
        total_duration=total_duration,
        lyric_groups=_lyric_groups_for_structure,
        objective_report=objective_report,
    )
    if structure_block:
        revised += "\n\n" + structure_block

    # Whole-mix tags are folded into the stem report above when both paths run.
    # If stem MIDI was disabled but whole-mix tagging is still on, run it alone.
    if (
        ENABLE_WHOLE_MIX_INSTRUMENT_TAGGING
        and dsp_path is not None
        and "WHOLE-MIX INSTRUMENT TAGS" not in (stem_midi_report or "")
    ):
        status("Tagging instruments on the full (un-separated) mix...")
        try:
            whole_mix_report = build_whole_mix_instrument_report(dsp_path)
            if whole_mix_report:
                revised += "\n\n" + whole_mix_report
                _gan = ""
                try:
                    _gan = guitar_absence_note_from_tags(
                        locals().get("whole_mix_tags"), whole_mix_report,
                        mix_audio_path=dsp_path,
                        stem_notes=locals().get("_stem_notes_raw"),
                        activity_metas=locals().get("_stem_activity_raw"),
                        cross_stem_agreement=locals().get("_stem_convergence"),
                    )
                except Exception:
                    _gan = ""
                if _gan:
                    revised += "\n\n" + _gan
        except Exception as e:
            print(f"  (whole-mix instrument tagging skipped: {e})")

    # Singer identity resolution is intentionally NOT done here — see
    # resolve_identity_and_finalize(). Just precompute the plain-text
    # evidence summary it needs, then release the heavy models.
    vocal_audit_for_resolution = None
    if ENABLE_SINGER_IDENTITY_RESOLUTION and (metadata or cover_observations):
        f0_text_res = f"{median_f0} Hz" if median_f0 is not None else "unavailable"
        vocal_audit_for_resolution = (
            f"Initial isolated lead profile: {initial_lead or 'unparsed'}\n"
            f"Confirmation pass: {confirm_lead or 'not run/unparsed'} (confidence={confirm_confidence or 'n/a'})\n"
            f"FINAL LEAD PROFILE: {final_lead or 'unknown'}\n"
            f"BACKING PROFILES: {initial_backing or 'uncertain'}\n"
            f"objective median f0: {f0_text_res}"
        )
        if no_clear_vocals:
            vocal_audit_for_resolution = "No clear vocals detected.\n" + vocal_audit_for_resolution

    # Always release MF/Omnizart/Ollama here, not just when identity
    # resolution is enabled — this is the point where this process's peak
    # (MF + Demucs + Omnizart all having been resident) has passed, so
    # freeing what we can now minimises what the OS has to reclaim on exit.
    _release_heavy_analysis_memory_before_identity()

    return {
        "track_path": track_path,
        "analysis": revised,
        "corrections": {},
        "metadata": metadata,
        "cover_observations": cover_observations,
        "cover_bytes": cover_bytes_for_save,
        "cover_mime": cover_mime,
        "stem_midi_report": stem_midi_report,
        # Carried forward so the saved .json can hold the real note events and
        # the resolved section map, rather than only the prose written above.
        "stem_notes": locals().get("_stem_notes_raw") or {},
        "structure_sections": structure_sections,
        "bpm": final_bpm,
        "key": final_key,
        "vocal_audit_for_resolution": vocal_audit_for_resolution,
        "final_lead": final_lead,
        "initial_backing": initial_backing,
        "vocal_result_present": bool(vocal_result),
        "_objective_report": objective_report,
    }


def resolve_identity_and_finalize(heavy):
    """Lightweight second stage: resolve singer identity, then append the
    RECOMMENDED STRUCTURE block at the absolute end of the analysis so it
    survives context truncation and is always available for structure questions.
    """
    revised = heavy.get("analysis", "") or ""
    metadata = heavy.get("metadata")
    cover_observations = heavy.get("cover_observations")
    final_lead = heavy.get("final_lead")
    initial_backing = heavy.get("initial_backing")
    vocal_result_present = bool(heavy.get("vocal_result_present"))
    vocal_audit_for_resolution = heavy.get("vocal_audit_for_resolution")
    objective_report = heavy.get("_objective_report", "")   # now passed through

    singer_identity = ""
    if ENABLE_SINGER_IDENTITY_RESOLUTION and (metadata or cover_observations):
        status("Resolving singer identity from audio + metadata + cover art...")
        try:
            singer_identity = resolve_singer_identity(
                metadata,
                vocal_audit_for_resolution or "",
                cover_observations,
                {},
                wiki_context=_artist_background_for_identity(metadata),
            ) or ""
        except Exception as e:
            print(f"  (singer identity skipped: {e})")
            singer_identity = ""
        finally:
            if globals().get("BATCH_UNLOAD_OLLAMA", True) and _is_batch_context():
                try:
                    ollama_unload_model()
                except Exception:
                    pass
        cover_obs_block = (
            _format_cover_observation_block(cover_observations) if cover_observations else ""
        )
        if cover_obs_block and "COVER ART OBSERVATIONS" not in revised:
            revised += "\n\n" + cover_obs_block
        if singer_identity and "SINGER IDENTITY RESOLUTION" not in revised:
            revised += (
                f"\n\nSINGER IDENTITY RESOLUTION (combined audio + metadata + cover art; "
                f"use for who-is-singing questions):\n{singer_identity}"
            )
        resolved_tag = _parse_singer_identity(singer_identity) if singer_identity else ""
        priority_tag = _reconcile_identity_with_acoustic_age(resolved_tag, final_lead)
        if vocal_result_present or singer_identity:
            revised += build_vocal_priority_note(priority_tag, initial_backing or "uncertain")

    # ------------------------------------------------------------
    # FINAL STEP: force the structure block to be the very last thing
    # ------------------------------------------------------------
    # 1. Remove any existing RECOMMENDED STRUCTURE block (so we don't duplicate).
    # Matches all three header variants format_recommended_structure_block can
    # emit: "...DISCUSSION:", "...DISCUSSION (from objective change points):",
    # and "...DISCUSSION (coarse, evenly-spaced windows...):". The old pattern
    # only matched the first, so once the coarse fallback started actually
    # firing (see _resolve_total_duration) it would have been left in place
    # and duplicated below instead of replaced.
    revised = re.sub(
        r"\n\nRECOMMENDED STRUCTURE FOR DISCUSSION(?:\s*\([^)]*\))?:.*?(?=\n\n[A-Z]|\Z)",
        "",
        revised,
        flags=re.DOTALL,
    )

    # 2. Build a fresh structure block using the OBJECTIVE-FIRST pipeline
    track_path = heavy.get("track_path")
    total_duration = _resolve_total_duration(
        track_path=track_path, objective_report=objective_report
    )

    # The section map was already resolved objectively during the heavy stage,
    # while the audio model was still loaded (see run_fresh_track_analysis_heavy).
    # It is reused verbatim here.
    #
    # This block used to re-run the whole cut/cluster/label pipeline from
    # scratch at this point, which meant reloading Music Flamingo immediately
    # after _release_heavy_analysis_memory_before_identity() had deliberately
    # freed it — paying a full model load to recompute a result the run already
    # had, and producing a section map that disagreed with the one the melody
    # and intensity blocks had already been keyed to.
    structure_sections = list(heavy.get("structure_sections") or [])
    boundary_seconds = []
    _lyric_groups_for_structure = None

    if structure_sections:
        boundary_seconds = [float(s["start"]) for s in structure_sections[1:]]
        revised = _overwrite_structure_field(revised, structure_sections)

    # Fall back only if the heavy stage genuinely produced nothing.
    if not structure_sections:
        structure_sections, boundary_seconds, _lyric_groups_for_structure = _finalize_structure_sections(
            revised,
            objective_report=objective_report,
            stem_midi_report=locals().get("stem_midi_report") or "",
            lyric_chunks=locals().get("_lyric_chunks"),
            total_duration=total_duration,
        )

    structure_block = format_recommended_structure_block(
        structure_sections,
        objective_boundaries=boundary_seconds,
        total_duration=total_duration,
        lyric_groups=_lyric_groups_for_structure,
        objective_report=objective_report,
    )
    if structure_block:
        revised = revised.rstrip() + "\n\n" + structure_block

    revised = _collapse_runaway_repetition_fields(revised)

    # Sonic embedding is computed HERE, at the end of the analysis, rather than
    # only inside save_song_data(). Previously a track only ever acquired an
    # embedding if it was saved, so a freshly analysed track could not take
    # part in a sonic-similarity comparison until it had been written to disk
    # and read back. This runs at the same point in the same process the save
    # would have run it (right after identity resolution, with the heavy
    # listening models already released), so peak memory is unchanged; the
    # result is cached and handed to save_song_data(), which reuses it instead
    # of recomputing.
    clap_vector = None
    try:
        _clap_src = heavy.get("track_path")
        if ENABLE_CLAP_EMBEDDING and _clap_src and not str(_clap_src).startswith(("http://", "https://")):
            status("Computing sonic-similarity embedding...")
            clap_vector = compute_clap_embedding(_clap_src)
            status_done(
                "Sonic embedding ready" if clap_vector is not None
                else "Sonic embedding unavailable"
            )
    except Exception as e:
        print(f"  (CLAP embedding skipped: {e})")
        clap_vector = None

    status_done("Analysis complete")

    out = dict(heavy)
    out["analysis"] = revised
    out["singer_identity"] = singer_identity
    out["structure_sections"] = structure_sections
    out["clap_embedding"] = clap_vector or []
    # clean up temporary keys
    for k in ("_objective_report", "vocal_audit_for_resolution", "final_lead",
              "initial_backing", "vocal_result_present"):
        out.pop(k, None)
    return out


def run_fresh_track_analysis(
    track_path,
    *,
    audio_temp_files,
    dsp_temp_files,
    stem_temp_files,
    demucs_out_dirs,
):
    """Back-compat wrapper: heavy analysis + identity resolution in one call,
    both stages in THIS process. Used by the non-isolated in-process batch
    fallback (BATCH_ISOLATE_PER_TRACK = False) and anywhere splitting into
    two OS processes isn't applicable. The (default) isolated batch path
    instead runs run_fresh_track_analysis_heavy() and
    resolve_identity_and_finalize() as two separate subprocess stages — see
    run_batch_one_analyze() / run_batch_one_finish() — so identity
    resolution's Ollama model load never has to coexist with this stage's
    stranded MF/Demucs/Omnizart memory.
    """
    heavy = run_fresh_track_analysis_heavy(
        track_path,
        audio_temp_files=audio_temp_files,
        dsp_temp_files=dsp_temp_files,
        stem_temp_files=stem_temp_files,
        demucs_out_dirs=demucs_out_dirs,
    )
    return resolve_identity_and_finalize(heavy)


def run_batch_one_track(track_path):
    """Analyse a single local audio file (heavy + identity, ONE process) and
    write JSON+cover into SAVE_DIR.

    Used when BATCH_SPLIT_IDENTITY_PROCESS is False. When it's True
    (default), the isolated batch path instead uses run_batch_one_analyze()
    + run_batch_one_finish() as two separate subprocess stages — see
    _batch_run_isolated().
    """
    track_path = os.path.abspath(os.path.expanduser(track_path))
    if not os.path.exists(track_path):
        raise FileNotFoundError(f"File not found: {track_path}")

    audio_temp_files = {}
    dsp_temp_files = {}
    stem_temp_files = {}
    demucs_out_dirs = []

    try:
        result = run_fresh_track_analysis(
            track_path,
            audio_temp_files=audio_temp_files,
            dsp_temp_files=dsp_temp_files,
            stem_temp_files=stem_temp_files,
            demucs_out_dirs=demucs_out_dirs,
        )
        save_name = _batch_save_basename(track_path, metadata=result.get("metadata"))
        out_path, cover_path = save_song_data(
            save_name,
            result["track_path"],
            result["analysis"],
            result.get("corrections") or {},
            metadata=result.get("metadata"),
            cover_observations=result.get("cover_observations"),
            singer_identity=result.get("singer_identity"),
            cover_bytes=result.get("cover_bytes"),
            cover_mime=result.get("cover_mime") or "image/jpeg",
            preserve_audio_basename=True,
            stem_midi=result.get("stem_notes"),
            structure_sections=result.get("structure_sections"),
            bpm=result.get("bpm"),
            key=result.get("key"),
            clap_embedding=result.get("clap_embedding"),
        )
        print(
            f"  ✓ saved {os.path.basename(out_path)}"
            + (f" + {os.path.basename(cover_path)}" if cover_path else "")
        )
        return out_path
    finally:
        try:
            _cleanup_track_temp_files(
                track_path, audio_temp_files, dsp_temp_files, stem_temp_files, demucs_out_dirs
            )
        except Exception:
            pass
        try:
            _aggressive_memory_cleanup()
        except Exception:
            pass


def run_batch_one_analyze(track_path, staging_path):
    """Stage 1 of the split-process batch pipeline (BATCH_SPLIT_IDENTITY_PROCESS):
    run the heavy audio analysis (MF/Demucs/Omnizart/Essentia/PANNs) and dump
    the result to staging_path as JSON, then this process exits. Deliberately
    does NOT resolve singer identity here — see run_batch_one_finish(), which
    runs as a fresh, model-free process so it can't inherit any of this
    stage's stranded torch/TF/MPS memory.
    """
    track_path = os.path.abspath(os.path.expanduser(track_path))
    if not os.path.exists(track_path):
        raise FileNotFoundError(f"File not found: {track_path}")

    audio_temp_files = {}
    dsp_temp_files = {}
    stem_temp_files = {}
    demucs_out_dirs = []

    try:
        heavy = run_fresh_track_analysis_heavy(
            track_path,
            audio_temp_files=audio_temp_files,
            dsp_temp_files=dsp_temp_files,
            stem_temp_files=stem_temp_files,
            demucs_out_dirs=demucs_out_dirs,
        )
        payload = dict(heavy)
        cover_bytes = payload.pop("cover_bytes", None)
        payload["cover_bytes_b64"] = (
            base64.b64encode(cover_bytes).decode("ascii") if cover_bytes else None
        )
        with open(staging_path, "w", encoding="utf-8") as f:
            json.dump(payload, f)
    finally:
        try:
            _cleanup_track_temp_files(
                track_path, audio_temp_files, dsp_temp_files, stem_temp_files, demucs_out_dirs
            )
        except Exception:
            pass
        try:
            _aggressive_memory_cleanup()
        except Exception:
            pass


def run_batch_one_finish(staging_path):
    """Stage 2 of the split-process batch pipeline: load stage 1's JSON,
    resolve singer identity (a plain-text Ollama call — no Music Flamingo/
    Demucs/Omnizart/Essentia involved), and save. Runs in a fresh process
    that starts with a clean memory baseline, regardless of how much of
    stage 1's memory the OS was slow to reclaim.
    """
    with open(staging_path, "r", encoding="utf-8") as f:
        heavy = json.load(f)

    cover_b64 = heavy.pop("cover_bytes_b64", None)
    heavy["cover_bytes"] = base64.b64decode(cover_b64) if cover_b64 else None

    result = resolve_identity_and_finalize(heavy)

    save_name = _batch_save_basename(result["track_path"], metadata=result.get("metadata"))
    out_path, cover_path = save_song_data(
        save_name,
        result["track_path"],
        result["analysis"],
        result.get("corrections") or {},
        metadata=result.get("metadata"),
        cover_observations=result.get("cover_observations"),
        singer_identity=result.get("singer_identity"),
        cover_bytes=result.get("cover_bytes"),
        cover_mime=result.get("cover_mime") or "image/jpeg",
        preserve_audio_basename=True,
        stem_midi=result.get("stem_notes"),
        structure_sections=result.get("structure_sections"),
        bpm=result.get("bpm"),
        key=result.get("key"),
        clap_embedding=result.get("clap_embedding"),
    )
    print(
        f"  ✓ saved {os.path.basename(out_path)}"
        + (f" + {os.path.basename(cover_path)}" if cover_path else "")
    )
    return out_path


def _batch_run_isolated(track_path):
    """Run one track through the isolated batch pipeline; returns (ok: bool, detail).

    When BATCH_SPLIT_IDENTITY_PROCESS is True (default), this spawns TWO
    fresh Python processes in sequence — one for the heavy MF/Demucs/
    Omnizart/Essentia analysis, one for singer-identity resolution + save —
    instead of one process doing both. The heavy stage's process exits
    completely between the two, which is the only fully reliable way to
    reset MPS/TF residual memory (in-process unload/gc/cache-clear is
    best-effort and can leave allocations stranded); the identity/save
    stage then starts from a clean baseline instead of asking Ollama to
    load the writer model on top of whatever the heavy stage couldn't
    fully release, which is what was causing "child exited -9" specifically
    at the "Resolving singer identity" step. Set BATCH_SPLIT_IDENTITY_PROCESS
    = False to fall back to the single-process-per-track behaviour.
    """
    script = os.path.abspath(__file__)
    env = os.environ.copy()
    # Child uses ephemeral Ollama loads (keep_alive=0) and unloads the writer
    # around heavy analysis. Parent chat history stays in this process's RAM.
    env["MUSICLYSE_BATCH_ONE"] = "1"
    env["MUSICLYSE_IN_BATCH"] = "1"
    try:
        # Free parent-side Ollama weights so the child can claim RAM for MF.
        if globals().get("BATCH_UNLOAD_OLLAMA", True):
            try:
                ollama_unload_model()
            except Exception:
                pass

        if globals().get("BATCH_SPLIT_IDENTITY_PROCESS", True):
            staging_fd, staging_path = tempfile.mkstemp(
                prefix="musiclyse_batch_", suffix=".json"
            )
            os.close(staging_fd)
            try:
                analyze_result = subprocess.run(
                    [sys.executable, script, "--batch-one-analyze", track_path, staging_path],
                    env=env,
                    timeout=None,
                )
                if analyze_result.returncode != 0:
                    return False, f"analysis stage exited {analyze_result.returncode}"

                # The analysis process has now fully exited, so the OS has
                # reclaimed 100% of its memory (unlike in-process cleanup,
                # which is best-effort). This finish stage re-imports the
                # module (cheap — no big model weights loaded) but starts
                # from that clean baseline before Ollama loads the writer.
                finish_result = subprocess.run(
                    [sys.executable, script, "--batch-one-finish", staging_path],
                    env=env,
                    timeout=None,
                )
                if finish_result.returncode != 0:
                    return False, f"identity/save stage exited {finish_result.returncode}"
                return True, "ok"
            finally:
                try:
                    os.remove(staging_path)
                except Exception:
                    pass

        # Single-process fallback (BATCH_SPLIT_IDENTITY_PROCESS = False).
        result = subprocess.run(
            [sys.executable, script, "--batch-one", track_path],
            env=env,
            timeout=None,
        )
        if result.returncode == 0:
            return True, "ok"
        return False, f"child exited {result.returncode}"
    except Exception as e:
        return False, str(e)


def batch_scan_folder_to_saved_songs(
    folder,
    *,
    audio_temp_files,
    dsp_temp_files,
    stem_temp_files,
    demucs_out_dirs,
    skip_existing=True,
):
    """
    Scan every audio file in folder with the same pipeline as /listen and write
    JSON (+ cover art) into SAVE_DIR. Does not import anything into chat history.

    When BATCH_ISOLATE_PER_TRACK is True (default), each track is analysed in a
    fresh subprocess so MPS/TensorFlow residual memory cannot accumulate. That
    is the recommended path for overnight runs on macOS.

    The interactive session's writer_history remains in the parent process RAM
    throughout; only the Ollama model weights are unloaded around analysis.
    """
    files = list_audio_files_in_folder(folder)
    if not files:
        print(f"  No audio files found in {folder}\n")
        return

    os.makedirs(SAVE_DIR, exist_ok=True)
    isolate = bool(BATCH_ISOLATE_PER_TRACK)
    os.environ["MUSICLYSE_IN_BATCH"] = "1"
    # Drop any resident writer model before the first track so analysis can use
    # the RAM. Session chat messages stay in the parent Python process.
    if globals().get("BATCH_UNLOAD_OLLAMA", True):
        try:
            status("Unloading Ollama writer for batch scan (session history kept)...")
            ollama_unload_model()
            status_done("Ollama writer unloaded — chat history still in memory")
        except Exception:
            pass
    split_identity = isolate and bool(globals().get("BATCH_SPLIT_IDENTITY_PROCESS", True))
    print(
        f"  Batch scan: {len(files)} track(s) in {folder}\n"
        f"  Saving to {os.path.abspath(SAVE_DIR)} (not imported into chat)\n"
        f"  Isolation: {'subprocess per track (recommended on macOS)' if isolate else 'in-process'}\n"
        f"  Identity stage: "
        f"{'separate process (BATCH_SPLIT_IDENTITY_PROCESS)' if split_identity else 'same process as analysis'}\n"
        f"  Ollama during batch: "
        f"{'unload between stages (BATCH_UNLOAD_OLLAMA)' if BATCH_UNLOAD_OLLAMA else 'left loaded'}\n"
    )

    ok, skipped, failed = 0, 0, 0
    for i, path in enumerate(files, 1):
        # Peek tags so the skip-check uses the same Artist - Title naming
        # that the actual save will use after analysis.
        peek_meta = {}
        if ENABLE_FILE_METADATA:
            try:
                peek_meta, _, _ = extract_audio_metadata(path)
            except Exception:
                peek_meta = {}
        save_name = _batch_save_basename(path, metadata=peek_meta)
        dest = os.path.join(SAVE_DIR, save_name)
        label = os.path.basename(path)
        print(f"\n  [{i}/{len(files)}] {label}")

        if skip_existing and os.path.exists(dest):
            print(f"  (skip — already saved as {save_name})")
            skipped += 1
            continue

        if isolate:
            success, detail = _batch_run_isolated(path)
            if success:
                ok += 1
            else:
                failed += 1
                print(f"  ✗ failed: {detail}")
            # Short pause even with isolation — lets the OS reclaim the dead
            # child's pages and reduces pressure spikes on the next launch.
            pause = float(BATCH_PAUSE_BETWEEN_TRACKS_S or 0)
            if pause > 0 and i < len(files):
                status(f"Batch pause {pause:.0f}s (letting RAM settle)...")
                try:
                    import time as _time
                    _time.sleep(pause)
                except Exception:
                    pass
                status_done()
            continue

        # In-process fallback (BATCH_ISOLATE_PER_TRACK = False)
        try:
            result = run_fresh_track_analysis(
                path,
                audio_temp_files=audio_temp_files,
                dsp_temp_files=dsp_temp_files,
                stem_temp_files=stem_temp_files,
                demucs_out_dirs=demucs_out_dirs,
            )
            out_path, cover_path = save_song_data(
                save_name,
                result["track_path"],
                result["analysis"],
                result.get("corrections") or {},
                metadata=result.get("metadata"),
                cover_observations=result.get("cover_observations"),
                singer_identity=result.get("singer_identity"),
                cover_bytes=result.get("cover_bytes"),
                cover_mime=result.get("cover_mime") or "image/jpeg",
                preserve_audio_basename=True,
                clap_embedding=result.get("clap_embedding"),
            )
            print(f"  ✓ saved {os.path.basename(out_path)}"
                  + (f" + {os.path.basename(cover_path)}" if cover_path else ""))
            ok += 1
        except Exception as e:
            failed += 1
            print(f"  ✗ failed: {e}")
        finally:
            try:
                _cleanup_track_temp_files(
                    path, audio_temp_files, dsp_temp_files, stem_temp_files, demucs_out_dirs
                )
            except Exception:
                pass
            try:
                _aggressive_memory_cleanup()
            except Exception:
                pass
            pause = float(BATCH_PAUSE_BETWEEN_TRACKS_S or 0)
            if pause > 0 and i < len(files):
                status(f"Batch pause {pause:.0f}s (letting RAM settle)...")
                try:
                    import time as _time
                    _time.sleep(pause)
                except Exception:
                    pass
                status_done()

    print(
        f"\n  Batch done — saved: {ok}, skipped: {skipped}, failed: {failed}\n"
        f"  Chat context was not modified. Use /load <name>.json to discuss a saved track.\n"
    )


def main():
    print_logo()

    check_ollama_running()

    if ENABLE_ESSENTIA_REPORT and not ESSENTIA_AVAILABLE:
        print(
            "  (Essentia is enabled but could not be imported; Essentia report will be skipped. "
            f"{ESSENTIA_IMPORT_ERROR})"
        )

    # Music Flamingo is NOT loaded here. It's large, and most turns in a
    # session (general chat, cached-track questions) never touch it, so it's
    # loaded lazily the first time a fresh audio analysis actually needs it
    # (see get_music_flamingo()/unload_music_flamingo() below), and released
    # again as soon as that analysis finishes. mf_model/mf_processor start
    # unset and are only populated inside the /listen fresh-analysis branch.
    mf_model = mf_processor = None
    mf_device = _mf_planned_device()

    # Per-track state, keyed by the raw path/URL as the user referenced it
    comprehensive_analyses = {}   # raw_path -> cached full-track analysis text
    track_signatures = {}        # raw_path -> current (absolute path, size, mtime_ns) identity
    track_analysis_signatures = {} # raw_path -> signature of the recording actually analysed/saved
    last_scan_was_excerpt = False # prevents /save from persisting an excerpt as a full-song scan
    track_corrections = {}        # raw_path -> {field: user-confirmed value}
    audio_temp_files = {}         # raw_path -> converted temp .wav path (cached so we don't reconvert)
    dsp_temp_files = {}
    stem_temp_files = {}          # raw_path -> stereo WAV used for Demucs/MIDI
    demucs_out_dirs = []          # temporary Demucs output directories to clean up later
    track_metadata = {}       # raw_path -> file-tag metadata dict
    track_cover_b64 = {}      # raw_path -> base64 cover art for Ollama, or None
    track_cover_observations = {}  # raw_path -> structured visual observations from cover art
    track_singer_identity = {}     # raw_path -> singer identity resolution text
    track_stem_midi_report = {}    # raw_path -> stem/MIDI evidence for that exact track
    track_stem_notes = {}          # raw_path -> raw per-stem transcribed note events
    track_structure_sections = {}  # raw_path -> objectively resolved section map
    track_bpm_key = {}             # raw_path -> (bpm, key) used for melodic analysis
    track_clap_embeddings = {}     # raw_path -> normalized 512-d CLAP vector (saved/loaded comparisons)
    # raw_path -> the exact writer_history message dict that carries this track's full
    # evidence block. Used (via identity + trailing-size check, see
    # _evidence_message_still_safe below) to decide whether it's safe to send a short
    # pointer instead of re-sending the full evidence on a follow-up question.
    track_evidence_message = {}
    track_wiki_context = {}        # raw_path -> cached WIKIPEDIA BACKGROUND CONTEXT block (or "")
    last_writer_message = None     # most recent message sent to the writer model
    

    current_track = sys.argv[1] if len(sys.argv) > 1 else None
    # Every track in the most recent /loadcompare. current_track only holds the
    # LAST one loaded, which is why follow-up questions about a comparison could
    # only ever find the second song on Wikipedia. Empty for single-track work.
    active_compare_keys = []
    last_scanned_track = None

    if current_track and not current_track.startswith(("http://", "https://")):
        if not os.path.exists(current_track):
            print(f"File not found: {current_track}")
            sys.exit(1)

    # Active chat persona (voice only). Music evidence rules stay fixed underneath.
    active_persona_text = DEFAULT_PERSONA_PROMPT
    active_persona_label = "default"
    writer_history = [{"role": "system", "content": build_writer_system_prompt(active_persona_text)}]
    warn_if_system_prompt_truncated(writer_history[0]["content"])

    print(_colorize(
        f"\nReady. Musiclyse uses {OLLAMA_MODEL} (writer) and {MF_MODEL_ID} "
        f"(listener, on {mf_device}).\n"
        f"Both models load lazily and are swapped in/out of memory as needed, "
        f"rather than staying resident for the whole session.\n"
        f"{OLLAMA_MODEL} chats directly for general questions.\n"
        f"'{LISTEN_FLAG} <question>' gets a full 10-category analysis of the current track "
        f"(cached after the first listen) and answers your question from it.\n"
        f"'{LISTEN_FLAG} <path or URL> <question>' switches tracks first.\nAudio windows can be limited with [start-end], e.g. '{LISTEN_FLAG} song.mp3 [30-60] analyse the solo'.\n"
        f"'{RELISTEN_FLAG} [<path or URL>] <question>' forces a fresh re-analysis instead of using the cache.\n"
        f"'{CORRECT_FLAG} field=value[, field=value...]' records a confirmed fact for the current "
        f"track (e.g. '{CORRECT_FLAG} year=1966') that overrides the analysis from then on.\n"
        f"'{SAVE_FLAG}=filename.json' saves technical details for the most recently scanned track to {SAVE_DIR}/ "
        f"(spaces and most punctuation are allowed in the name).\n"
        f"'{LOAD_FLAG} filename.json [question]' loads a saved song; optional question after the name. "
        f"Quoted names and names with spaces work (e.g. /load \"Artist - Song.json\").\n"
        f"'{LOADCOMPARE_FLAG} \"track 1.json\" \"track 2.json\" question' loads two or more saved "
        f"songs together in one go and asks a question about all of them "
        f"Saved JSONs also include a 512-d CLAP sonic-similarity embedding for multi-track comparisons. "
        f"(e.g. /loadcompare \"Radiohead - Creep.json\" \"Nirvana - Lithium.json\" compare their choruses).\n"
        f"'{BATCH_FLAG} /path/to/folder' overnight-scans every audio file in that folder into {SAVE_DIR}/ "
        f"as 'Artist Name - Song Name.json' (from file tags; Unknown + original filename if tags missing). "
        f"Same analysis as /listen; does NOT import into chat. Skips files already saved. "
        f"Default: one subprocess per track to avoid macOS MPS OOM kills on long batches.\n"
        f"'{CLEAR_FLAG}' wipes chat context and resets session token counters "
        f"(track analysis cache is kept so you don't re-scan).\n"
        f"'{PERSONA_FLAG} <description>' sets a custom chat persona (taste/voice); music evidence rules stay.\n"
        f"'{PERSONA_FLAG} reset' (or default) restores the music-obsessed friend. "
        f"'{PERSONA_FLAG}' alone shows the current persona.\n"
        + (f"Starting track: {current_track}\n" if current_track else "No starting track yet — set one with /listen.\n")
        + "Type 'quit' to exit.\n",
        Ansi.YELLOW,
    ))

    def _parse_top_level_paren_groups(text):
        """Split text like '("a") ("b") (c)' into ['a', 'b', 'c'].

        Used by /loadcompare. Honors nesting (parens inside a group, e.g. a
        track named "Song (Live).json") and quotes (a paren inside quotes
        doesn't count toward depth). A group that is entirely wrapped in one
        layer of matching quotes has those quotes stripped. Returns None if
        the text isn't cleanly a sequence of top-level (...) groups (e.g.
        stray text outside any parens, or unbalanced parens) so the caller
        can fall back to a clear usage error.
        """
        groups = []
        i, n = 0, len(text)
        while i < n:
            while i < n and text[i] in " \t\r\n":
                i += 1
            if i >= n:
                break
            if text[i] != "(":
                return None
            depth = 0
            in_quote = None
            j = i
            while j < n:
                c = text[j]
                if in_quote:
                    if c == in_quote:
                        in_quote = None
                elif c in ("'", '"'):
                    in_quote = c
                elif c == "(":
                    depth += 1
                elif c == ")":
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            if depth != 0 or j >= n:
                return None
            inner = text[i + 1:j].strip()
            if len(inner) >= 2 and inner[0] == inner[-1] and inner[0] in ("'", '"'):
                inner = inner[1:-1].strip()
            groups.append(inner)
            i = j + 1
        return groups if groups else None

    def _diagnose_loadcompare_failure(text, resolved_names):
        """Build a specific, actionable message for a /loadcompare parse failure,
        instead of a bare usage reminder.

        /load's own best-effort fallback at least attempts a load and reports
        something concrete about what it tried; /loadcompare's failure path used
        to fall straight to a generic usage line with no indication of WHICH name
        it couldn't resolve or why -- unhelpful for exactly the case that trips
        people up: a title that's close but not quite right (e.g. the audio file
        is named "I Want You Bad" but the track was tagged and saved as "I Want U
        Bad" -- a real, correctly-saved title, not a typo in the app). This finds
        the first chunk of text that didn't resolve to a real saved file and
        suggests the closest actual filenames, the same way a shell's "command
        not found: did you mean..." works.

        Returns a message string (never raises; falls back to a bare notice if
        anything about the diagnosis itself goes wrong).
        """
        try:
            candidate = (text or "").strip()
            if candidate and candidate[:1] in ("'", '"'):
                q = candidate[0]
                end = candidate.find(q, 1)
                candidate = candidate[1:end] if end > 0 else candidate[1:]
            else:
                candidate = (candidate.split()[:6] and " ".join(candidate.split()[:6])) or candidate
            candidate = candidate.strip()
            if not candidate:
                return None

            try:
                saved = [
                    f[:-5] for f in os.listdir(SAVE_DIR) if f.lower().endswith(".json")
                ] if os.path.isdir(SAVE_DIR) else []
            except Exception:
                saved = []
            if not saved:
                return None

            close = difflib.get_close_matches(candidate, saved, n=3, cutoff=0.5)
            if not close:
                return None

            already = {n.strip().lower() for n in (resolved_names or [])}
            close = [c for c in close if c.strip().lower() not in already]
            if not close:
                return None

            suggestion_lines = "\n".join(f"    {c}.json" for c in close)
            return (
                f"  Could not find a saved track matching \"{candidate}\". Closest saved "
                f"file(s):\n{suggestion_lines}\n"
            )
        except Exception:
            return None

    def _parse_loadcompare_args_free(text):
        """Parse '/loadcompare' arguments without requiring parentheses.

        Uses the exact same name-resolution algorithm as /load (see
        _resolve_next_saved_track_argument), applied once per track: quoted
        or unquoted, with or without ".json", any punctuation including
        apostrophes. allow_best_effort_fallback=False, so it stops at the
        first argument that doesn't resolve to a real saved file instead of
        swallowing the comparison question as a bogus track name -- whatever
        text remains after the last real match is the question.
        """
        names = []
        rest = text

        while True:
            name, trailing = _resolve_next_saved_track_argument(
                rest, allow_best_effort_fallback=False
            )
            if name is None:
                break
            names.append(name)
            rest = trailing

        query = rest.strip()
        if len(names) < 2 or not query:
            return None
        return names, query

    def _load_saved_track_into_session(filename, question=None):
        """Load one saved-song JSON off disk into this session (analysis
        cache, metadata, cover art, singer identity, wiki context) and
        register a loaded_message in writer_history so the writer model can
        discuss it. Shared by /load (one track) and /loadcompare (two+
        tracks loaded back-to-back before a single combined question).

        `question` is the same optional hint /load's trailing prompt gives
        _get_or_build_wiki_context — for /loadcompare this is the comparison
        question, used for every track being loaded.

        Returns (key, label) on success, or None on failure (after printing
        the same failure messages /load has always printed).
        """
        try:
            data = load_song_data(filename)
        except Exception as e:
            print(f"  Load failed: {e}\n")
            return None

        if not data:
            print(f"  Saved song not found in {SAVE_DIR}/ for '{filename}'.\n")
            return None

        key = data.get("track_path") or os.path.splitext(os.path.basename(data.get("label", "saved-song")))[0]
        comprehensive_analyses[key] = data["analysis"]
        _loaded_sig = data.get("audio_file_signature")
        _current_sig = _audio_file_signature(key)
        if _current_sig is not None:
            track_signatures[key] = _current_sig
        # Old JSONs predate persisted signatures. Treat their analysis as stale
        # for the next /listen when the original local audio still exists rather
        # than silently trusting an analysis whose source cannot be verified.
        track_analysis_signatures[key] = (
            tuple(_loaded_sig) if isinstance(_loaded_sig, list) else _loaded_sig
        ) if _loaded_sig is not None else None

        # ------------------------------------------------------------------
        # Restore the raw transcribed MIDI saved with this track.
        # ------------------------------------------------------------------
        # Saves written before this field existed simply won't have it, and the
        # track still loads exactly as before — this is purely additive.
        #
        # When it IS present, the melodic analysis is rebuilt here from the
        # note events rather than relying on whatever prose happened to be
        # written at scan time. That is the difference between a reloaded track
        # being able to answer "how does the chorus melody move" from actual
        # measured pitches and only being able to repeat a sentence someone
        # wrote months ago.
        try:
            _saved_notes = _json_notes_to_stem_notes(data.get("stem_midi") or {})
        except Exception as e:
            print(f"  (saved MIDI could not be restored: {e})")
            _saved_notes = {}

        if _saved_notes:
            track_stem_notes[key] = _saved_notes
            _saved_sections = data.get("structure_sections") or []
            if _saved_sections:
                track_structure_sections[key] = _saved_sections
            _saved_bpm = data.get("bpm")
            _saved_key = data.get("key")
            track_bpm_key[key] = (_saved_bpm, _saved_key)

            # Only append if this save doesn't already carry the block, so
            # re-loading the same file repeatedly can't stack duplicates.
            if "MELODIC ANALYSIS (measured from this recording" not in comprehensive_analyses[key]:
                try:
                    _melody_block = build_melody_understanding_block(
                        _saved_sections, _saved_notes,
                        bpm=_saved_bpm, key=_saved_key,
                    )
                    if _melody_block:
                        comprehensive_analyses[key] = (
                            comprehensive_analyses[key].rstrip()
                            + "\n\n" + _melody_block
                        )
                except Exception as e:
                    print(f"  (melodic analysis rebuild skipped: {e})")

            _n_notes = sum(len(v) for v in _saved_notes.values())
            print(
                f"  (restored {_n_notes} transcribed notes across "
                f"{len(_saved_notes)} stems)"
            )
        track_corrections.setdefault(key, {}).update(data.get("corrections", {}) or {})
        clap_vector = _extract_clap_embedding(data.get("clap_embedding"))
        if clap_vector is not None:
            track_clap_embeddings[key] = clap_vector

        saved_metadata = data.get("metadata") or {}
        track_cover_b64.pop(key, None)
        # Prefer the cover written into the save (works even if the original file moved).
        saved_cover_name = str(data.get("cover_art") or "").strip()
        if saved_cover_name and os.path.exists(os.path.join(SAVE_DIR, saved_cover_name)):
            try:
                with open(os.path.join(SAVE_DIR, saved_cover_name), "rb") as f:
                    track_cover_b64[key] = base64.b64encode(f.read()).decode("utf-8")
            except Exception as e:
                print(f"  (could not read saved cover art: {e})")

        if (
            ENABLE_FILE_METADATA
            and not key.startswith(("http://", "https://"))
            and os.path.exists(key)
        ):
            # If the saved JSON has no metadata, try to recover it from the original file.
            if not any(
                str(saved_metadata.get(k) or "").strip()
                for k in ("title", "artist", "album", "year", "lyrics")
            ):
                try:
                    meta, _, _ = extract_audio_metadata(key)
                    saved_metadata = meta
                except Exception as e:
                    print(f"  (metadata recovery skipped on load: {e})")

            # Recover cover art if the original file is still available.
            if (SEND_COVER_ART_TO_OLLAMA or ENABLE_COVER_ART_DESCRIPTION) and track_cover_b64.get(key) is None:
                try:
                    cover_bytes, cover_mime = extract_cover_art_only(key)
                    prepared = (
                        prepare_cover_image_for_ollama(cover_bytes, cover_mime)
                        if cover_bytes else None
                    )

                    if prepared:
                        track_cover_b64[key] = base64.b64encode(prepared).decode("utf-8")
                    else:
                        track_cover_b64[key] = NO_COVER_SENTINEL

                except Exception as e:
                    print(f"  (cover art skipped on load: {e})")

        track_metadata[key] = saved_metadata

        saved_obs = data.get("cover_observations") or {}
        saved_identity = str(data.get("singer_identity") or "").strip()

        if saved_obs:
            track_cover_observations[key] = saved_obs
        else:
            cover_b64_for_desc = track_cover_b64.get(key)
            if (
                ENABLE_COVER_ART_DESCRIPTION
                and cover_b64_for_desc
                and cover_b64_for_desc != NO_COVER_SENTINEL
            ):
                obs = describe_cover_art(cover_b64_for_desc)
                track_cover_observations[key] = obs if obs else {}
            else:
                track_cover_observations.pop(key, None)

        if saved_identity:
            track_singer_identity[key] = saved_identity
        elif ENABLE_SINGER_IDENTITY_RESOLUTION and (track_metadata.get(key) or track_cover_observations.get(key)):
            identity_text = resolve_singer_identity(
                track_metadata.get(key, {}),
                _short_vocal_audit(data["analysis"]),
                track_cover_observations.get(key),
                track_corrections.get(key, {}),
                wiki_context=track_wiki_context.get(key),
            )
            if identity_text:
                track_singer_identity[key] = identity_text.strip()
            else:
                track_singer_identity.pop(key, None)
        else:
            track_singer_identity.pop(key, None)

        label = track_label(key)

        loaded_metadata_block = (
            _format_metadata_block(track_metadata.get(key, {}))
            if ENABLE_FILE_METADATA else ""
        )

        loaded_cover_images = []
        cover_b64 = track_cover_b64.get(key)
        if SEND_COVER_ART_TO_OLLAMA and cover_b64 and cover_b64 != NO_COVER_SENTINEL:
            loaded_cover_images.append(cover_b64)

        loaded_obs_block = (
            _format_cover_observation_block(track_cover_observations.get(key))
            if track_cover_observations else ""
        )

        loaded_identity_block = (
            f"\n\nSINGER IDENTITY RESOLUTION (combined audio + metadata + cover art; use for who-is-singing questions):\n{track_singer_identity[key]}"
            if track_singer_identity.get(key) else ""
        )

        extra_loaded_context = ""
        if "COVER ART OBSERVATIONS" not in data["analysis"]:
            extra_loaded_context += loaded_obs_block
        if "SINGER IDENTITY RESOLUTION" not in data["analysis"]:
            extra_loaded_context += loaded_identity_block

        has_cover_context = (
            bool(loaded_cover_images)
            or bool(loaded_obs_block)
            or ("COVER ART OBSERVATIONS" in data["analysis"])
        )
        loaded_cover_note = COVER_ART_CONTEXT_NOTE if has_cover_context else ""

        # Same wiki background-context lookup as /listen (cached per track, or
        # re-looked-up fresh per question if WIKI_CONTEXT_REFRESH_EVERY_QUESTION
        # is on) — folded in here too so /load (and /loadcompare) get it just
        # like /listen does.
        loaded_wiki_block = _get_or_build_wiki_context(
            key, track_metadata, track_wiki_context, question=question,
            persona_gate=(active_persona_text.strip() != DEFAULT_PERSONA_PROMPT.strip()),
        )

        # Blocks that must survive per-message truncation.
        #
        # /load puts data['analysis'] in the MIDDLE of this message, and
        # _truncate_text_for_ollama keeps only the head and the tail. Anything
        # sitting between the analysis and the end gets discarded once the wiki
        # block is large (a normal three-article lookup is ~20k chars). That was
        # silently dropping the file-tag metadata, the cover-art note, the
        # evidence-firewall note and the structure map on exactly the loads
        # where the most background text was present.
        #
        # These are moved to the very end so they land inside the tail. The
        # firewall note itself cannot simply be moved: its wording is positional
        # ("everything above this line was measured, everything below is
        # background"), so relocating it below the wiki block would invert its
        # meaning and, worse, would mark this restored evidence as background.
        # LOADED_TAIL_EVIDENCE_NOTE carries the same rule in position-independent
        # language and explicitly overrides the earlier marker for this section.
        loaded_structure_block = _structure_block_from_saved_sections(
            data.get("structure_sections")
        )
        tail_blocks = "".join(
            b for b in (
                loaded_metadata_block,
                loaded_cover_note,
                (f"\n\n{loaded_structure_block}\n" if loaded_structure_block else ""),
            ) if b
        )
        loaded_tail_section = (
            f"{LOADED_TAIL_EVIDENCE_NOTE}{tail_blocks}" if tail_blocks.strip() else ""
        )

        loaded_message = {
            "role": "user",
            "content": (
                f"[Loaded saved track '{label}']\n"
                "(background technical details restored from a previous scan; use them for discussion):\n"
                f"{data['analysis']}\n"
                f"{extra_loaded_context}"
                f"{AUDIO_EVIDENCE_FIREWALL_NOTE if loaded_wiki_block else ''}"
                f"{loaded_wiki_block}\n"
                f"{loaded_tail_section}"
                "This track is now available in the session."
            ),
        }

        if loaded_cover_images:
            loaded_message["images"] = loaded_cover_images[:MAX_COVER_IMAGES_PER_REQUEST]

        writer_history.append(loaded_message)
        # Register this message with the evidence-dedup tracker (see the /listen
        # branch below) so a later `/listen <question>` about this same track
        # knows full evidence is already in history and doesn't resend it.
        track_evidence_message[key] = loaded_message
        writer_history.append({
            "role": "assistant",
            "content": "Got it — I've loaded the saved analysis for that track and can discuss it from here on.",
        })

        print(f"  (loaded saved song '{label}' into this session)\n")

        return key, label

    try:
        while True:
            user_text = colored_input("You: ", Ansi.LIGHT_GREEN).strip()
            if user_text.lower() in ("quit", "exit"):
                break
            if not user_text:
                continue

            _compact_writer_history_in_place(writer_history)
            
            
            clear_all_rem = _command_remainder(user_text, CLEAR_ALL_FLAG)
            if clear_all_rem is not None:
                # Full in-memory reset: conversation + all analysis caches.
                # Saved song JSON/cover files on disk are left untouched so
                # /load still works after a session wipe.
                writer_history.clear()
                writer_history.append({
                    "role": "system",
                    "content": build_writer_system_prompt(active_persona_text),
                })
                track_evidence_message.clear()
                track_wiki_context.clear()
                comprehensive_analyses.clear()
                track_signatures.clear()
                track_analysis_signatures.clear()
                last_scan_was_excerpt = False
                track_metadata.clear()
                track_cover_b64.clear()
                track_cover_observations.clear()
                track_singer_identity.clear()
                track_clap_embeddings.clear()
                current_track = None
                last_scanned_track = None
                last_writer_message = None
                SESSION_TOKEN_USAGE["prompt"] = 0
                SESSION_TOKEN_USAGE["completion"] = 0
                SESSION_TOKEN_USAGE["total"] = 0
                SESSION_TOKEN_USAGE["last_prompt"] = 0
                SESSION_TOKEN_USAGE["last_completion"] = 0
                SESSION_TOKEN_USAGE["last_ctx"] = 0

                print(
                    "  Full cache cleared: conversation and in-memory track analyses wiped. "
                    f"Saved files in {SAVE_DIR}/ were left untouched. "
                    f"Persona: {active_persona_label}.\n"
                )
                continue

            clear_rem = _command_remainder(user_text, CLEAR_FLAG)
            if clear_rem is not None:
                # Wipe conversation context + token counters only.
                # Track analysis caches stay so /listen on a known path stays fast.
                # Active persona is preserved.
                writer_history.clear()
                writer_history.append({
                    "role": "system",
                    "content": build_writer_system_prompt(active_persona_text),
                })
                track_evidence_message.clear()
                # Wikipedia context is a question-sensitive retrieval cache, not
                # analysis evidence. Keeping it across /clear meant that the first
                # question asked about a track could permanently decide which
                # articles were available for all later questions in that session.
                # A fresh chat should allow fresh entity extraction and retrieval.
                track_wiki_context.clear()
                last_writer_message = None
                SESSION_TOKEN_USAGE["prompt"] = 0
                SESSION_TOKEN_USAGE["completion"] = 0
                SESSION_TOKEN_USAGE["total"] = 0
                SESSION_TOKEN_USAGE["last_prompt"] = 0
                SESSION_TOKEN_USAGE["last_completion"] = 0
                SESSION_TOKEN_USAGE["last_ctx"] = 0
                print(
                    "  Chat context cleared and token counters reset to zero. "
                    "Cached track analyses are still in memory "
                    f"({len(comprehensive_analyses)} track(s)). "
                    f"Persona: {active_persona_label}.\n"
                )
                continue

            persona_rem = _command_remainder(user_text, PERSONA_FLAG)
            if persona_rem is not None:
                rem = (persona_rem or "").strip()
                if not rem:
                    preview = active_persona_text.strip().replace("\n", " ")
                    if len(preview) > 160:
                        preview = preview[:157] + "..."
                    print(
                        f"  Current persona: {active_persona_label}\n"
                        f"  Preview: {preview}\n"
                        f"  Usage:\n"
                        f"    {PERSONA_FLAG} <description>   set a custom voice/taste\n"
                        f"    {PERSONA_FLAG} reset           restore default music buddy\n"
                        f"    {PERSONA_FLAG}                 show current persona\n"
                    )
                    continue

                rem_lower = rem.lower()
                is_persona_reset = rem_lower in ("reset", "default", "clear")
                if is_persona_reset:
                    active_persona_text = DEFAULT_PERSONA_PROMPT
                    active_persona_label = "default"
                    label_msg = "default music-obsessed friend"
                else:
                    # Strip a leading "Roleplay as" / "You are" so expansion stays clean.
                    cleaned = rem
                    for prefix in (
                        "roleplay as ",
                        "role-play as ",
                        "role play as ",
                        "act as ",
                        "be ",
                        "you are ",
                    ):
                        if cleaned.lower().startswith(prefix):
                            cleaned = cleaned[len(prefix):].strip()
                            break

                    # Short labels → full brief with authentic-taste instructions.
                    # Longer free-form text is used as written, with a taste reminder appended.
                    if len(cleaned) < 100 and "\n" not in cleaned:
                        active_persona_text = expand_persona_label(cleaned)
                        active_persona_label = cleaned[:60]
                    else:
                        active_persona_text = (
                            cleaned
                            + "\n\nMUSICAL TASTE: React as this persona truly would. "
                            "Do not automatically like every track. Use known or plausible "
                            "taste for real people/characters when available. Description of "
                            "a song is not the same as endorsement.\n"
                            "DEPTH: Stay conversational. Do not default to analytical "
                            "breakdowns (tempo, key, stems, production essays) unless this "
                            "persona would naturally talk that way or the user asks for it."
                        )
                        active_persona_label = cleaned.strip().split("\n", 1)[0][:60] or "custom"
                    label_msg = active_persona_label

                # Replace system message in place so the new voice applies immediately.
                new_system = build_writer_system_prompt(active_persona_text)
                # A custom persona builds a LARGER prompt than the default (its own
                # text plus CUSTOM_PERSONA_RULES), so it can cross the truncation
                # limit even when the startup check passed. Re-check here, since
                # that startup call only ever saw the default persona.
                warn_if_system_prompt_truncated(new_system)
                if writer_history and writer_history[0].get("role") == "system":
                    writer_history[0] = {"role": "system", "content": new_system}
                else:
                    writer_history.insert(0, {"role": "system", "content": new_system})

                # Drop markers left by earlier switches before adding the new
                # one. Swapping the system prompt alone does not undo them:
                # they sit in the conversation and keep issuing the previous
                # persona's instructions.
                _strip_persona_markers(writer_history)

                if is_persona_reset:
                    # Reset needs its OWN marker. Reusing the custom-persona one
                    # below is what broke /persona reset: it appended "gut
                    # reactions over analysis / do not default to tempo, key,
                    # production breakdowns" under the label "default", so the
                    # default persona stayed suppressed on /listen and /load.
                    writer_history.append({
                        "role": "user",
                        "content": (
                            f"{PERSONA_MARKER_USER_PREFIX}{label_msg}. The previous character "
                            "is gone — drop that voice, its taste and its limits completely. "
                            "You are back to the default: a music-obsessed friend who is happy "
                            "to go deep on tempo, key, structure, stems and production whenever "
                            "it is useful, using the measured evidence as normal. Music evidence "
                            "rules are unchanged.]"
                        ),
                    })
                    writer_history.append({
                        "role": "assistant",
                        "content": (
                            f"{PERSONA_MARKER_ASSISTANT_PREFIX}{label_msg} — back to my own "
                            "voice, and back to full analytical depth whenever it helps."
                        ),
                    })
                    print(f"  Persona set to: {label_msg}\n")
                    continue

                # Soft marker in history so the model notices the switch mid-thread.
                writer_history.append({
                    "role": "user",
                    "content": (
                        f"{PERSONA_MARKER_USER_PREFIX}{label_msg}. Reply fully in character from now on. "
                        "Match their speech AND their musical taste — do not fake enthusiasm for "
                        "tracks they would not care about. Keep it human and conversational: "
                        "gut reactions over analysis. Do not default to tempo/key/production "
                        "breakdowns unless this persona would naturally geek out that way or "
                        "the user asks. You may name a song accurately without pretending to "
                        "love it. Music evidence rules are unchanged.]"
                    ),
                })
                writer_history.append({
                    "role": "assistant",
                    "content": (
                        f"{PERSONA_MARKER_ASSISTANT_PREFIX}{label_msg}, "
                        "including taste and how much I care about the technical stuff."
                    ),
                })
                print(f"  Persona set to: {label_msg}\n")
                continue

            batch_rem = _command_remainder(user_text, BATCH_FLAG)
            if batch_rem is not None:
                folder = batch_rem.strip().strip('"').strip("'")
                if not folder:
                    print(
                        f"  Usage: {BATCH_FLAG} /path/to/folder\n"
                        f"  Scans all audio files in that folder (non-recursive), "
                        f"saves JSON+cover into {SAVE_DIR}/, does not load them into chat.\n"
                    )
                    continue
                folder = os.path.expanduser(folder)
                if not os.path.isdir(folder):
                    print(f"  Not a directory: {folder}\n")
                    continue
                try:
                    batch_scan_folder_to_saved_songs(
                        folder,
                        audio_temp_files=audio_temp_files,
                        dsp_temp_files=dsp_temp_files,
                        stem_temp_files=stem_temp_files,
                        demucs_out_dirs=demucs_out_dirs,
                        skip_existing=True,
                    )
                except Exception as e:
                    print(f"  Batch scan failed: {e}\n")
                continue

            debug_rem = _command_remainder(user_text, DEBUG_FLAG)
            if debug_rem is not None:
                    if last_writer_message is None:
                        print("  No writer message yet.\n")
                    else:
                        print(json.dumps(_redact_message_for_debug(last_writer_message), indent=2, default=str))
                        print(f"  cover observations present for current track: {bool(track_cover_observations.get(current_track))}")
                        print(f"  singer identity resolution present for current track: {bool(track_singer_identity.get(current_track))}\n")
                    continue
                

            save_rem = _command_remainder(user_text, SAVE_FLAG)
            if save_rem is not None:
                filename = save_rem.strip('"').strip("'")
                if last_scan_was_excerpt:
                    print("  Last scan was an audio excerpt; /save is blocked so an excerpt cannot be saved as a full-song analysis. Run /listen on the full track first.\n")
                    continue
                if last_scanned_track is None or last_scanned_track not in comprehensive_analyses:
                    print("  No scanned track to save yet — use /listen first.\n")
                    continue

                # Collect prepared cover art so it can be written into the save.
                save_cover_bytes, save_cover_mime = None, "image/jpeg"
                b64 = track_cover_b64.get(last_scanned_track)
                if b64 and b64 != NO_COVER_SENTINEL:
                    try:
                        save_cover_bytes = base64.b64decode(b64)
                        save_cover_mime = _guess_image_mime(save_cover_bytes)
                    except Exception:
                        save_cover_bytes = None
                if (save_cover_bytes is None and not last_scanned_track.startswith(("http://", "https://"))
                        and os.path.exists(last_scanned_track)):
                    try:
                        cb, cm = extract_cover_art_only(last_scanned_track)
                        prepared = prepare_cover_image_for_ollama(cb, cm) if cb else None
                        if prepared:
                            save_cover_bytes, save_cover_mime = prepared, _guess_image_mime(prepared)
                    except Exception:
                        pass

                try:
                    path, cover_path = save_song_data(
                        filename,
                        last_scanned_track,
                        comprehensive_analyses[last_scanned_track],
                        track_corrections.get(last_scanned_track, {}),
                        track_metadata.get(last_scanned_track, {}),
                        track_cover_observations.get(last_scanned_track),
                        track_singer_identity.get(last_scanned_track),
                        save_cover_bytes,
                        save_cover_mime,
                        stem_midi=track_stem_notes.get(last_scanned_track),
                        structure_sections=track_structure_sections.get(last_scanned_track),
                        bpm=(track_bpm_key.get(last_scanned_track) or (None, None))[0],
                        key=(track_bpm_key.get(last_scanned_track) or (None, None))[1],
                        clap_embedding=track_clap_embeddings.get(last_scanned_track),
                    )
                except Exception as e:
                    print(f"  Save failed: {e}\n")
                    continue

                extra = f" + cover art → {cover_path}" if cover_path else ""
                print(f"  (saved technical details for {track_label(last_scanned_track)} to {path}{extra})\n")
                continue

            load_rem = _command_remainder(user_text, LOAD_FLAG)
            if load_rem is not None:
                # Support: /load name.json
                #          /load 'Artist Name - Song.json'
                #          /load Artist Name - Song.json what about the chorus?
                # Optional prompt after the filename is sent to the writer like /listen.
                # Filenames may contain spaces, apostrophes, parentheses, dashes, etc.
                load_rest = load_rem.strip()
                filename, load_prompt = _resolve_next_saved_track_argument(
                    load_rest, allow_best_effort_fallback=True
                )

                result = _load_saved_track_into_session(filename, question=(load_prompt or None))
                if result is None:
                    continue
                key, label = result
                current_track = key
                # Single-track load ends any active comparison context.
                active_compare_keys = []
                last_scanned_track = key
                last_scan_was_excerpt = False

                if load_prompt:
                    # Optional trailing question, same idea as /listen path + question.
                    _load_depth_requested = bool(
                        re.search(
                            r"\b(in[\s-]?depth|in\s+detail|elaborate|tell me more|go deeper|"
                            r"more detail|full breakdown|deep dive|thorough|comprehensive|"
                            r"everything (you'?ve got|you know)|expand on|say more|break (it|that|this) down|"
                            r"walk me through|long answer|really get into)\b",
                            load_prompt,
                            re.IGNORECASE,
                        )
                    )
                    _load_reply_style_note = (
                        "Reply as their music buddy in the conversation. They asked for depth here — "
                        "give a genuinely long, detailed answer that actually goes into it, not a short "
                        "summary with a token gesture toward length."
                        if _load_depth_requested else
                        "Reply as their music buddy in the conversation — answer what they asked, "
                        "not a full analytical write-up unless they asked for one."
                    )
                    writer_message = {
                        "role": "user",
                        "content": (
                            f"Regarding the loaded track '{label}': {load_prompt}"
                            "\n\nIf what they're asking relates to something already discussed earlier in this "
                            "conversation — comparing this to another track, continuing a topic, reacting to an "
                            "earlier point — use those earlier turns to answer that directly. Don't just give a "
                            "standalone description of this track in isolation when they asked about a connection "
                            "to something already talked about.\n\n"
                            f"{_load_reply_style_note}"
                        ),
                    }
                    last_writer_message = writer_message
                    writer_history.append(writer_message)
                    status("Writing...")
                    final_reply, usage = _safe_ollama_chat(writer_history)
                    if final_reply is None:
                        status_done()
                        continue
                    writer_history.append({"role": "assistant", "content": final_reply})
                    status_done()
                    print(_colorize(f"\nMusiclyse: {final_reply}\n", Ansi.MAGENTA))
                    _print_token_usage(usage)
                continue

            loadcompare_rem = _command_remainder(user_text, LOADCOMPARE_FLAG)
            if loadcompare_rem is not None:
                # Support (parentheses optional, same spirit as /load):
                #   /loadcompare "track 1.json" "track 2.json" question
                #   /loadcompare track 1.json track 2.json question
                #   /loadcompare ("track 1.json") ("track 2.json") (question)   -- still works
                # At least two tracks, then one trailing question. Quotes around a
                # name are optional but recommended for names containing spaces;
                # without quotes, each name just needs to end in '.json' so its
                # boundary is unambiguous.
                usage_msg = (
                    f"  Usage: {LOADCOMPARE_FLAG} \"track 1.json\" \"track 2.json\" question"
                    f"  — at least two tracks (quoted, or ending in .json), then one question.\n"
                )
                loadcompare_rest = loadcompare_rem.strip()
                # Try the original parenthesized form first — it declines immediately
                # (returns None) unless the text actually starts with '(', so this is
                # a safe first attempt and won't misfire on paren-free input.
                groups = _parse_top_level_paren_groups(loadcompare_rest)
                if groups and len(groups) >= 3:
                    *compare_names, compare_query = groups
                    compare_names = [n for n in compare_names if n.strip()]
                    compare_query = compare_query.strip()
                    if len(compare_names) < 2 or not compare_query:
                        compare_names = None
                else:
                    compare_names = None

                if not compare_names:
                    parsed = _parse_loadcompare_args_free(loadcompare_rest)
                    if parsed is None:
                        diag = _diagnose_loadcompare_failure(loadcompare_rest, [])
                        print((diag or "") + usage_msg)
                        continue
                    compare_names, compare_query = parsed

                compare_keys, compare_labels = [], []
                load_ok = True
                for name in compare_names:
                    result = _load_saved_track_into_session(name.strip(), question=compare_query)
                    if result is None:
                        load_ok = False
                        break
                    key, label = result
                    compare_keys.append(key)
                    compare_labels.append(label)

                if not load_ok or len(compare_keys) < 2:
                    print("  /loadcompare aborted — could not load all of the requested tracks.\n")
                    continue

                current_track = compare_keys[-1]
                active_compare_keys = list(compare_keys)
                last_scanned_track = compare_keys[-1]

                # Backfill missing embeddings transiently for older JSON files when
                # their original local audio is still available. New saves already
                # persist the embedding in the JSON. This only runs for comparisons,
                # never for a single-track /load question.
                # compute_clap_embedding() unloads the model on every call by
                # default, which meant a comparison of N un-embedded tracks paid
                # N full CLAP loads; keep it resident across the loop and unload
                # once at the end instead.
                _missing = [k for k in compare_keys if k not in track_clap_embeddings]
                for _i, _key in enumerate(_missing):
                    _last = (_i == len(_missing) - 1)
                    _emb = compute_clap_embedding(_key, keep_loaded=not _last)
                    if _emb is not None:
                        track_clap_embeddings[_key] = _emb
                if _missing:
                    try:
                        unload_clap()
                    except Exception:
                        pass

                labels_joined = ", ".join(f"'{l}'" for l in compare_labels[:-1]) + f" and '{compare_labels[-1]}'"
                clap_comparison_block = _format_clap_comparison(
                    compare_keys, compare_labels, track_clap_embeddings
                )
                writer_message = {
                    "role": "user",
                    "content": (
                        f"Now compare the tracks just loaded — {labels_joined} — and answer this: "
                        f"{compare_query}\n\n"
                        "Use the technical details already given for each of these tracks above; don't ask "
                        "for anything further before answering. When comparing, compare like with like "
                        "(tempo vs tempo, key vs key, LUFS vs LUFS, etc.) rather than vague impressions. "
                        "Do NOT put timestamps in the comparison unless the user's question actually asks "
                        "about timing, section boundaries, or when something happens. Do NOT walk through "
                        "either track's section map unprompted either — no 'Verse 1 -> Chorus 1 -> ...' "
                        "run-throughs unless the user asked about structure. If form is worth a mention, "
                        "keep it to a passing phrase ('one front-loads its hook, the other holds it back'). "
                        "If you do give the map or times because they were asked for, quote them exactly "
                        "and note once that the section map and its times are detected automatically and "
                        "can be a few seconds out. "
                        "For overall sonic resemblance, use any CLAP similarity evidence supplied below as "
                        "supporting evidence alongside the musical notes, not as a standalone verdict. "
                        "GENRE: describe each track from its OWN measured evidence — the RECOMMENDED GENRE "
                        "block, GENRE_RANKED and the PANNs tags for that file. This applies to every genre "
                        "word you use anywhere in the comparison, including passing texture descriptions, "
                        "not only when the user asks a genre question directly. Do NOT reach for the band's "
                        "catalogue label ('pop rock', 'indie', etc.) from background or general knowledge to "
                        "characterise how a recording sounds. If you want to mention how a track is usually "
                        "filed, attribute it and keep it separate from the measurement, and say plainly when "
                        "the two disagree. "
                        "Keep the comparison focused on the recording and the user's question; biography is "
                        "secondary unless they ask for it. Never expose internal program terminology such as "
                        "dedicated pass, transcription, tags, metadata, analysis, scan, or private notes. "
                        "For lyric questions, use reliable supplied lyrics directly and never contrast them with "
                        "an internal transcription unless the user explicitly asks to compare versions. "
                        "Reply as their music buddy in the conversation — answer what they asked, not a "
                        "full analytical write-up of each track individually unless they asked for one. "
                        + (f"\n\n{clap_comparison_block}" if clap_comparison_block else "")
                    ),
                }
                last_writer_message = writer_message
                writer_history.append(writer_message)
                status("Writing...")
                final_reply, usage = _safe_ollama_chat(writer_history)
                if final_reply is None:
                    status_done()
                    continue
                writer_history.append({"role": "assistant", "content": final_reply})
                status_done()
                print(_colorize(f"\nMusiclyse: {final_reply}\n", Ansi.MAGENTA))
                _print_token_usage(usage)
                continue

            correct_rem = _command_remainder(user_text, CORRECT_FLAG)
            if correct_rem is not None:
                if current_track is None:
                    print("  No current track to correct — use /listen with a path first.\n")
                    continue

                remainder = correct_rem
                if "=" not in remainder:
                    print(f"  Usage: {CORRECT_FLAG} field=value[, field=value...]  e.g. '{CORRECT_FLAG} year=1966' or '{CORRECT_FLAG} singer=child_gender_uncertain'\n")
                    continue

                corrections = track_corrections.setdefault(current_track, {})
                applied = []
                for part in remainder.split(","):
                    field, sep, value = part.strip().partition("=")
                    field, value = field.strip(), value.strip()
                    if sep and field and value:
                        if field.lower() in VOCAL_CORRECTION_FIELDS:
                            normalized_value = _normalize_vocal_tag(value)
                            if normalized_value in VOCAL_LEAD_TAGS or normalized_value in VOCAL_LEAD_ALIASES:
                                value = VOCAL_LEAD_ALIASES.get(normalized_value, normalized_value)
                        corrections[field] = value
                        applied.append(f"{field} = {value}")

                if not applied:
                    print("  Couldn't parse that — use field=value format.\n")
                    continue

                label = track_label(current_track)
                print(f"  (recorded correction for {label}: {', '.join(applied)})\n")

                # Tell the LLM immediately, so it updates rather than waiting for the next /listen turn
                correction_note = (
                    f"[User correction for track '{label}']: " + "; ".join(applied) + ". "
                    "This came directly from the user and is ground truth. It overrides anything "
                    "the audio-perception model said or implied about these point(s), including any "
                    "reasoning it built on top of the now-corrected fact. Treat it as fact from now on."
                )
                writer_history.append({"role": "user", "content": correction_note})
                writer_history.append(
                    {"role": "assistant", "content": f"Got it — noted: {', '.join(applied)}. I'll treat that as confirmed going forward."}
                )
                continue  # nothing further to generate for this turn

            listen_rem = None
            force_fresh = False
            relisten_rem = _command_remainder(user_text, RELISTEN_FLAG)
            if relisten_rem is not None:
                force_fresh = True
                listen_rem = relisten_rem
            else:
                listen_rem = _command_remainder(user_text, LISTEN_FLAG)

            if listen_rem is not None:
                # If /listen is accidentally given the name of a saved JSON,
                # treat it as /load rather than silently reusing the current
                # track's cached analysis.
                saved_match = _match_saved_filename_prefix(listen_rem)
                if saved_match is not None:
                    saved_filename, saved_prompt = saved_match
                    result = _load_saved_track_into_session(
                        saved_filename, question=(saved_prompt or None)
                    )
                    if result is None:
                        continue
                    key, label = result
                    current_track = key
                    # Single-track scan ends any active comparison context.
                    active_compare_keys = []
                    last_scanned_track = key
                    last_scan_was_excerpt = False

                    if saved_prompt:
                        _load_depth_requested = bool(
                            re.search(
                                r"\b(in[\s-]?depth|in\s+detail|elaborate|tell me more|go deeper|"
                                r"more detail|full breakdown|deep dive|thorough|comprehensive|"
                                r"everything (you'?ve got|you know)|expand on|say more|break (it|that|this) down|"
                                r"walk me through|long answer|really get into)\b",
                                saved_prompt,
                                re.IGNORECASE,
                            )
                        )
                        _load_reply_style_note = (
                            "Reply as their music buddy in the conversation. They asked for depth here — "
                            "give a genuinely long, detailed answer that actually goes into it, not a short "
                            "summary with a token gesture toward length."
                            if _load_depth_requested else
                            "Reply as their music buddy in the conversation — answer what they asked, "
                            "not a full analytical write-up unless they asked for one."
                        )
                        _load_question_notes = _build_writer_question_notes(
                            saved_prompt,
                            depth_requested=_load_depth_requested,
                            metadata=track_metadata.get(key, {}),
                        )
                        writer_message = {
                            "role": "user",
                            "content": (
                                f"Regarding the loaded track '{label}': {saved_prompt}"
                                "\n\nIf what they're asking relates to something already discussed earlier in this "
                                "conversation — comparing this to another track, continuing a topic, reacting to an "
                                "earlier point — use those earlier turns to answer that directly. Don't just give a "
                                "standalone description of this track in isolation when they asked about a connection "
                                "to something already talked about.\n\n"
                                f"{_load_question_notes}\n\n"
                                f"{_load_reply_style_note}"
                            ),
                        }
                        last_writer_message = writer_message
                        writer_history.append(writer_message)
                        status("Writing...")
                        final_reply, usage = _safe_ollama_chat(writer_history)
                        if final_reply is None:
                            status_done()
                            continue
                        writer_history.append({"role": "assistant", "content": final_reply})
                        status_done()
                        print(_colorize(f"\nMusiclyse: {final_reply}\n", Ansi.MAGENTA))
                        _print_token_usage(usage)
                    continue

                remainder = listen_rem
                remainder, listen_segment = parse_listen_segment(remainder)
                is_snippet = listen_segment is not None
                snippet_caution = ""
                if is_snippet:
                    snippet_caution = (
                        f"\n\nAUDIO EXCERPT CAUTION: The analysis below was performed on a short excerpt from "
                        f"{listen_segment[0]}s to {listen_segment[1]}s. The structural timestamps in the notes "
                        "are relative to that excerpt, not the full song. Do not describe sections that occur "
                        "outside this excerpt; base your answer only on what is audible in that range.\n"
                    )
                cleaned_question, audio_ref = extract_audio_reference(remainder)

                if audio_ref:
                    current_track = audio_ref
                    print(f"  (switching current track to: {track_label(current_track)})")

                if current_track is not None:
                    _sig = _audio_file_signature(current_track)
                    if _sig is not None:
                        _prev_sig = track_signatures.get(current_track)
                        if _prev_sig is not None and _prev_sig != _sig:
                            # The pathname now refers to a different recording.
                            # Drop every evidence cache tied to that pathname so old
                            # audio, stems, identity, metadata and structure cannot bleed
                            # into the replacement file.
                            for _cache in (
                                comprehensive_analyses, track_corrections,
                                audio_temp_files, dsp_temp_files, stem_temp_files,
                                track_metadata, track_cover_b64,
                                track_cover_observations, track_singer_identity,
                                track_stem_midi_report, track_stem_notes,
                                track_structure_sections, track_bpm_key,
                                track_clap_embeddings, track_wiki_context,
                                track_analysis_signatures,
                            ):
                                _cache.pop(current_track, None)
                            track_evidence_message.pop(current_track, None)
                            print("  (track file changed in place; invalidated cached audio evidence)")
                        track_signatures[current_track] = _sig

                if current_track is None:
                    print(
                        f"  No track set yet — include a path or URL the first time, e.g.\n"
                        f"  '{LISTEN_FLAG} /path/to/song.mp3 what genre is this?'\n"
                    )
                    continue

                extra_image_refs = []
                if cleaned_question:
                    cleaned_question, extra_image_refs = extract_image_references(cleaned_question)
                    if extra_image_refs and not OLLAMA_SUPPORTS_IMAGES:
                        print("  (Ollama model is marked as text-only; ignoring explicit image references)")
                        extra_image_refs = []
                    elif extra_image_refs:
                        print(f"  (found {len(extra_image_refs)} explicit image reference(s) in /listen question)")

                question = cleaned_question or "Give me an overview of this track."
                if listen_segment:
                    print(f"  (analysing only audio segment {listen_segment[0]:g}s–{listen_segment[1]:g}s)")
                    # Segments are different analyses from the full-track cache.
                    # Do not accidentally reuse the cached whole-song result.
                    force_fresh = True
                # If the user forced a fresh listen, also retry cover-art extraction in case it failed before.
                if force_fresh:
                    track_cover_b64.pop(current_track, None)
                # Extract file metadata/cover art from the ORIGINAL file,
                # before any WAV conversion.
                if (
                    ENABLE_FILE_METADATA
                    and current_track
                    and not current_track.startswith(("http://", "https://"))
                    and os.path.exists(current_track)
                ):
                    need_meta = current_track not in track_metadata
                    need_cover = (SEND_COVER_ART_TO_OLLAMA or ENABLE_COVER_ART_DESCRIPTION) and (
                        current_track not in track_cover_b64
                        or track_cover_b64.get(current_track) is None
                    )

                    if need_meta or need_cover:
                        status("Reading file metadata/tags before WAV conversion...")

                        meta = {}
                        cover_bytes = None
                        cover_mime = "image/jpeg"

                        try:
                            if need_meta:
                                meta, cover_bytes, cover_mime = extract_audio_metadata(current_track)
                            else:
                                cover_bytes, cover_mime = extract_cover_art_only(current_track)
                        except Exception as e:
                            print(f"  (metadata/cover extraction skipped: {e})")

                        if need_meta:
                            existing_meta = track_metadata.setdefault(current_track, {})
                            for k, v in meta.items():
                                if v and not existing_meta.get(k):
                                    existing_meta[k] = v

                        if need_cover:
                            try:
                                prepared = (
                                    prepare_cover_image_for_ollama(cover_bytes, cover_mime)
                                    if cover_bytes else None
                                )

                                if prepared:
                                    track_cover_b64[current_track] = base64.b64encode(prepared).decode("utf-8")
                                    print(f"  (embedded cover art found for {track_label(current_track)})")
                                else:
                                    # Cache a permanent "no cover" only when no raw embedded art was found.
                                    # If raw art exists but preparation failed, leave it unset so a later /listen can retry.
                                    if cover_bytes is None:
                                        track_cover_b64[current_track] = NO_COVER_SENTINEL
                                    else:
                                        track_cover_b64.pop(current_track, None)

                                    print(
                                        f"  (no usable embedded cover art found for {track_label(current_track)}; "
                                        f"raw_bytes={len(cover_bytes) if cover_bytes else 0}, mime={cover_mime})"
                                    )

                            except Exception as e:
                                # Leave it unset/None so a later /listen can retry if this was transient.
                                print(f"  (cover art skipped: {e})")

                    # Cover-art description for identity/context (must run on success, not only on failure).
                    if SEND_COVER_ART_TO_OLLAMA or ENABLE_COVER_ART_DESCRIPTION:
                        cover_b64 = track_cover_b64.get(current_track)
                        if (
                            cover_b64
                            and cover_b64 != NO_COVER_SENTINEL
                            and (force_fresh or current_track not in track_cover_observations)
                        ):
                            status("Describing embedded cover art for writer context...")
                            obs = describe_cover_art(cover_b64)
                            if obs:
                                track_cover_observations[current_track] = obs
                            else:
                                track_cover_observations.pop(current_track, None)
                        elif not cover_b64 or cover_b64 == NO_COVER_SENTINEL:
                            track_cover_observations.pop(current_track, None)

                _analysis_sig = track_analysis_signatures.get(current_track)
                _current_audio_sig = _audio_file_signature(current_track)
                _analysis_source_changed = (
                    not is_snippet
                    and current_track in comprehensive_analyses
                    and _current_audio_sig is not None
                    and _analysis_sig != _current_audio_sig
                )
                # Saved JSONs from before the signature field existed are treated
                # as stale when the original local audio is available, because we
                # cannot prove which bytes produced that historical analysis.
                _legacy_saved_without_sig = (
                    not is_snippet
                    and current_track in comprehensive_analyses
                    and _current_audio_sig is not None
                    and _analysis_sig is None
                )
                need_analysis = (
                    force_fresh
                    or (not is_snippet and current_track not in comprehensive_analyses)
                    or _analysis_source_changed
                    or _legacy_saved_without_sig
                )
                multi_voice_fields = {}
                turn_analysis = None
                if need_analysis:
                    # A fresh (or forced) analysis invalidates any evidence block already
                    # sitting in writer_history for this track, so the new evidence must
                    # be sent again in full on this turn.
                    track_evidence_message.pop(current_track, None)
                    if not current_track.startswith(("http://", "https://")) and not os.path.exists(current_track):
                        print(f"  File not found for fresh analysis: {current_track}\n")
                        continue

                    # Resolve to a playable path (convert non-wav/flac local files; URLs pass through)
                    if current_track.startswith(("http://", "https://")):
                        resolved_path = current_track
                    else:
                        ext = os.path.splitext(current_track)[1].lower()
                        if ext in (".wav", ".flac"):
                            resolved_path = current_track
                        elif current_track in audio_temp_files:
                            resolved_path = audio_temp_files[current_track]
                        else:
                            status(f"Converting {ext} to WAV for compatibility...")
                            resolved_path = convert_to_wav(current_track)
                            audio_temp_files[current_track] = resolved_path

                    # About to start a batch of Music Flamingo passes (era, full analysis,
                    # vocal, confirmation, lyrics). Free the output LLM from Ollama's memory first —
                    # it isn't needed again until we're back to writing the final answer —
                    # then lazily load Music Flamingo (a no-op if it's already loaded from
                    # a call earlier in this same batch).
                    ollama_unload_model()
                    mf_model, mf_processor, mf_device = get_music_flamingo()

                    if listen_segment and not current_track.startswith(("http://", "https://")):
                        resolved_path = crop_audio_segment(
                            resolved_path, listen_segment[0], listen_segment[1]
                        )

                    # ERA is run FIRST, in its own isolated conversation with no prior generated
                    # text (mood/vibe language especially) sitting in context to bias the judgment
                    # toward "sounds like modern indie."
                    status("Listening — estimating era...")
                    era_conversation = [
                        {
                            "role": "user",
                            "content": [
                                {"type": "text", "text": ERA_ANALYSIS_PROMPT},
                                {"type": "audio", "path": resolved_path},
                            ],
                        }
                    ]
                    era_result = mf_generate(mf_model, mf_processor, era_conversation, max_new_tokens=1024)

                    status("Listening — running full analysis (this can take a while)...")
                    first_pass, mf_conversation, main_max_tokens = _mf_run_main_analysis(
                        mf_model, mf_processor, resolved_path, deep=DEEP_MODE
                    )

                    objective_report = ""
                    vocal_objective_report = ""
                    essentia_report = ""
                    genre_mood_report = ""
                    panns_genre_tags = []
                    dsp_path = None
                    precomputed_stems, precomputed_demucs_out_dir = {}, None
                    vocal_pitch_source = "full mix (no isolated vocal stem available)"
                    if not current_track.startswith(("http://", "https://")):
                        if current_track in dsp_temp_files:
                            dsp_path = dsp_temp_files[current_track]
                        else:
                            status("Preparing higher-rate WAV for signal processing...")
                            try:
                                dsp_path = convert_to_wav(current_track, sample_rate=22050)
                                dsp_temp_files[current_track] = dsp_path
                            except Exception:
                                ext = os.path.splitext(current_track)[1].lower()
                                if ext in (".wav", ".flac"):
                                    dsp_path = current_track
                                else:
                                    dsp_path = resolved_path

                        # Isolate vocals via Demucs *before* pitch tracking, when stem
                        # separation is enabled, so pyin locks onto the singer instead
                        # of a sustained bass/pad/guitar drone in the full mix. Reused
                        # below for the stem MIDI report so Demucs only runs once.
                        if ENABLE_VOCAL_OBJECTIVE_REPORT and ENABLE_STEM_MIDI:
                            precomputed_stems, precomputed_demucs_out_dir = _prepare_demucs_stems_for_track(
                                current_track, stem_temp_files, demucs_out_dirs,
                                status_fn=status, deep_mode=DEEP_MODE,
                            )
                            if precomputed_stems.get("vocals"):
                                vocal_pitch_source = "isolated vocal stem (Demucs)"

                        if dsp_path is not None:
                            if ENABLE_OBJECTIVE_AUDIO_REPORT:
                                status("Measuring beat/timbre with signal processing...")
                                objective_report = build_objective_audio_report(
                                    dsp_path, original_path=current_track
                                )
                            if ENABLE_VOCAL_OBJECTIVE_REPORT:
                                status("Measuring vocal pitch/formant proxies...")
                                _pitch_source_path = precomputed_stems.get("vocals") or dsp_path
                                vocal_objective_report = build_vocal_objective_report(_pitch_source_path)
                                if vocal_objective_report:
                                    vocal_objective_report += f"\nmeasurement source: {vocal_pitch_source}"
                            if ENABLE_ESSENTIA_REPORT and ESSENTIA_AVAILABLE:
                                status("Measuring tempo/key/spectral features with Essentia...")
                                essentia_report = build_essentia_report(dsp_path)
                            if ENABLE_GENRE_MOOD_TAGGING:
                                status("Cross-checking genre/mood with an independent classifier...")
                                try:
                                    genre_mood_report, panns_genre_tags = build_genre_mood_signal_report(dsp_path)
                                except Exception as e:
                                    print(f"  (genre/mood signal skipped: {e})")
                                    genre_mood_report = ""
                                    panns_genre_tags = []

                    vocal_result = ""
                    if ENABLE_VOCAL_PASS:
                        status("Listening — estimating singer profile...")
                        vocal_prompt_text = VOCAL_ANALYSIS_PROMPT
                        if vocal_objective_report:
                            vocal_prompt_text += (
                                "\n\nObjective vocal measurements (evidence only, not proof):\n"
                                f"{vocal_objective_report}"
                            )

                        vocal_conversation = [
                            {
                                "role": "user",
                                "content": [
                                    {"type": "text", "text": vocal_prompt_text},
                                    {"type": "audio", "path": resolved_path},
                                ],
                            }
                        ]
                        vocal_result = mf_generate(mf_model, mf_processor, vocal_conversation, max_new_tokens=768)

                    confirmation_result = ""
                    initial_lead = ""
                    initial_backing = ""
                    confirm_lead = ""
                    confirm_confidence = ""
                    final_lead = ""

                    vocal_pitch = extract_vocal_pitch_summary(vocal_objective_report) if vocal_objective_report else {
                        "median": None, "low": None, "high": None, "note": None
                    }
                    median_f0 = vocal_pitch["median"]

                    if vocal_result:
                        initial_lead, initial_backing = parse_vocal_tags(vocal_result)

                    _vp_flag = _parse_vocals_present_flag(vocal_result or "")
                    no_clear_vocals = _vp_flag in ("no",)
                    no_clear_vocals, _early_vocal_salvage, _ = _salvage_false_no_vocals(
                        vocal_result,
                        no_clear_vocals,
                        median_f0=median_f0,
                        vocal_objective_report=vocal_objective_report or "",
                        stem_midi_report="",
                        initial_lead=initial_lead,
                    )

                    if ENABLE_VOCAL_CONFIRMATION_PASS and vocal_result and not no_clear_vocals:
                        should_confirm = False

                        # Always confirm when the initial result is young/uncertain.
                        if initial_lead in UNCERTAIN_YOUNG_CATEGORIES:
                            should_confirm = True

                        # Confirm female-leaning results more aggressively, especially when pitch is high
                        # or objective f0 is unavailable. This targets the common miscategorisation case.
                        elif initial_lead in FEMALE_LEAD_CATEGORIES and (
                            (median_f0 is not None and median_f0 >= VOCAL_CONFIRMATION_F0_THRESHOLD)
                            or (median_f0 is None and VOCAL_CONFIRMATION_WITHOUT_F0)
                        ):
                            should_confirm = True
                        elif initial_lead in (MALE_LEAD_CATEGORIES | ADOLESCENT_MALE_CATEGORIES) and (
                            median_f0 is not None
                            and F0_MALE_HIGH_CONFIRM_HZ is not None
                            and median_f0 >= float(F0_MALE_HIGH_CONFIRM_HZ)
                        ):
                            # High track-wide median on a male-tagged lead is a common
                            # female→male mislabel path; run confirmation before locking in.
                            should_confirm = True
                        elif initial_lead == "mixed_leads":
                            should_confirm = True
                        else:
                            _mv_early = parse_multi_voice_fields(vocal_result or "")
                            if _mv_early.get("voice_arrangement") in ("duet_co_leads", "call_response"):
                                should_confirm = True
                            elif _mv_early.get("num_distinct_voices") in ("2", "3", "3+", "two", "three"):
                                should_confirm = True

                        if should_confirm:
                            status("Listening — confirming lead voice category...")
                            confirmation_conversation = [
                                {
                                    "role": "user",
                                    "content": [
                                        {"type": "text", "text": VOCAL_CONFIRMATION_PROMPT},
                                        {"type": "audio", "path": resolved_path},
                                    ],
                                }
                            ]
                            confirmation_result = mf_generate(
                                mf_model, mf_processor, confirmation_conversation, max_new_tokens=256
                            )

                        if confirmation_result:
                            confirm_lead, confirm_confidence = parse_vocal_confirmation(confirmation_result)

                    final_lead = choose_final_vocal_lead(
                        initial_lead, confirm_lead, confirm_confidence, confirmation_result,
                        median_f0=median_f0,
                        multi_voice_fields=multi_voice_fields,
                    )
                    final_lead = _apply_vocal_age_guard(
                        final_lead,
                        (vocal_result or "") + "\n" + (confirmation_result or ""),
                    )
                    final_lead = _apply_f0_pitch_guard(
                        final_lead,
                        median_f0,
                        low_f0=vocal_pitch.get("low") if isinstance(vocal_pitch, dict) else None,
                        high_f0=vocal_pitch.get("high") if isinstance(vocal_pitch, dict) else None,
                    )



                    first_pass = _mf_salvage_empty_analysis(
                        first_pass, objective_report, essentia_report, vocal_result
                    )

                    if FAST_MODE:
                        revised = first_pass
                    else:
                        status("Double-checking its own analysis for overconfident claims...")
                        self_check_text = SELF_CHECK_PROMPT
                        if vocal_result or confirmation_result:
                            self_check_text += "\n\nVocal profile evidence:\n"
                            if vocal_result:
                                self_check_text += f"{vocal_result}\n"
                            if confirmation_result:
                                self_check_text += f"{confirmation_result}\n"
                            self_check_text += (
                                "Use this ONLY to correct lead/backing voice age/gender category claims. "
                                "Do NOT use it to change GENRE, KEY, CHORD PROGRESSION, SONG STRUCTURE, ERA, or non-vocal instrumentation. "
                                "If the lead is identified as young_male, child_male_likely, child_female_likely, or child_gender_uncertain, do not leave a confident female-lead claim in place."
                            )

                        if final_lead in UNCERTAIN_YOUNG_CATEGORIES:
                            self_check_text += (
                                " The lead vocal is gender-uncertain/young-uncertain according to the isolated vocal decision logic. "
                                "Remove any confident boy/girl/woman/girl/man claim from the analysis."
                            )

                        objective_crosscheck_parts = []
                        if essentia_report:
                            objective_crosscheck_parts.append(essentia_report)
                        if objective_report:
                            objective_crosscheck_parts.append(objective_report)

                        if objective_crosscheck_parts:
                            self_check_text += (
                                "\n\nIndependent signal-processing cross-checks "
                                "(use only for tempo/beat, key/key strength when explicitly reported, timbre, element activity, dynamic range, "
                                "and -- when a STRUCTURAL BOUNDARY CANDIDATES line is present -- section-timing in STRUCTURE; "
                                "do NOT use librosa/Essentia spectral stats to invent GENRE or change vocal identity):\n"
                                + "\n\n".join(objective_crosscheck_parts)
                            )
                        if genre_mood_report:
                            self_check_text += (
                                "\n\nIndependent genre/mood classifier (PANNs/AudioSet) — this MAY be used "
                                "to revise GENRE_RANKED when it clearly conflicts with a rock/pop-punk top rank "
                                "driven mainly by guitar texture while this signal is electronic/dance/synth-pop. "
                                "See GENRE self-check rules.\n"
                                + genre_mood_report
                            )

                        mf_conversation.append(
                            {"role": "assistant", "content": [{"type": "text", "text": first_pass}]}
                        )
                        mf_conversation.append(
                            {"role": "user", "content": [{"type": "text", "text": self_check_text}]}
                        )
                        revised = mf_generate(mf_model, mf_processor, mf_conversation, max_new_tokens=main_max_tokens)

                    # ----------------------------------------------------------
                    # SONG STRUCTURE (objective-first) — resolved once, here.
                    # ----------------------------------------------------------
                    # Same placement rationale as the non-interactive path: this
                    # is the last point the audio model is resident, and it is
                    # only used to NAME parts whose boundaries signal analysis
                    # has already fixed. Resolving it here also means the stem
                    # melody/intensity blocks below are keyed to the SAME
                    # sections as the final RECOMMENDED STRUCTURE block.
                    _structure_sections = []
                    _bnd_pre = []
                    _struct_grid = {}
                    try:
                        _total_duration_pre = _resolve_total_duration(
                            track_path=current_track, dsp_path=dsp_path,
                            objective_report=objective_report,
                        )
                        _struct_audio_path = dsp_path or resolved_path or current_track
                        if (
                            _struct_audio_path
                            and _total_duration_pre
                            and not str(_struct_audio_path).startswith(("http://", "https://"))
                            and os.path.exists(_struct_audio_path)
                        ):
                            # See the note in run_fresh_track_analysis_heavy:
                            # final_bpm is not assigned until later, so a
                            # measured tempo is read from the objective report
                            # instead when one is available.
                            _struct_bpm_hint = None
                            try:
                                _struct_bpm_hint = (
                                    extract_objective_bpm(objective_report)
                                    or extract_essentia_bpm(essentia_report)
                                )
                            except Exception:
                                _struct_bpm_hint = None

                            status("Resolving song structure from the audio (cut -> cluster -> name)...")
                            _y_struct, _sr_struct = librosa.load(
                                _struct_audio_path, sr=None, mono=True
                            )
                            _structure_sections = _build_objective_first_structure(
                                _struct_audio_path, _y_struct, _sr_struct,
                                _total_duration_pre, mf_model, mf_processor,
                                bpm_hint=_struct_bpm_hint,
                            )
                            try:
                                _sb, _sd, _sbl, _ = _beat_and_downbeat_grid(
                                    _y_struct, _sr_struct, bpm_hint=_struct_bpm_hint
                                )
                                _struct_grid = {"beats": _sb, "downbeats": _sd,
                                                "beat_len": _sbl}
                            except Exception:
                                _struct_grid = {}
                            del _y_struct
                            if _structure_sections:
                                _bnd_pre = [
                                    float(s["start"]) for s in _structure_sections[1:]
                                ]
                                status_done(
                                    f"Structure resolved from audio "
                                    f"({len(_structure_sections)} sections)"
                                )
                    except Exception as e:
                        import traceback
                        print(f"  !! STRUCTURE DETECTION FAILED: {type(e).__name__}: {e}")
                        traceback.print_exc()
                        _structure_sections = []

                    # That self-check revision was the last Music Flamingo pass in this
                    # batch (stem/MIDI below uses Demucs/Omnizart, not Music Flamingo;
                    # singer-identity resolution and the final written answer use the
                    # output LLM via Ollama). Free its memory now, before the lyrics pass
                    # below, so Music Flamingo and Whisper are never resident at once.
                    unload_music_flamingo()
                    mf_model = mf_processor = None

                    # Dedicated lyrics pass in an ISOLATED conversation (like ERA), now
                    # using Whisper instead of Music Flamingo — Music Flamingo hallucinates
                    # readily on song lyrics (inventing lines, drifting into unrelated
                    # prose, "correcting" words toward remembered/expected lyrics), whereas
                    # Whisper is a dedicated, comparatively literal ASR model. Whisper is
                    # lazy-loaded here (only for the duration of this pass) and released
                    # again immediately after.
                    # Skip when authoritative file-tag lyrics are already present — the
                    # transcription is often noisy, duplicates tags, and is a major token cost.
                    tag_lyrics = ""
                    if ENABLE_FILE_METADATA:
                        tag_lyrics = str(
                            (track_metadata.get(current_track) or {}).get("lyrics") or ""
                        ).strip()
                    _lyric_chunks = []  # default when the Whisper lyrics pass below is skipped
                    # Any non-empty file-tag lyrics are authoritative. Do not let a short tag
                    # block fall through to snippet-level Whisper transcription.
                    skip_mf_lyrics = (
                        SKIP_MF_LYRICS_WHEN_TAGS_PRESENT
                        and bool(tag_lyrics)
                    )
                    if skip_mf_lyrics:
                        status("Skipping lyrics transcription pass (file-tag lyrics already present)...")
                        revised += (
                            "\n\nLYRICS: reliable lyrics are present and are the preferred source for lyric questions."
                        )
                    else:
                        status("Transcribing full lyrics with Whisper (dedicated pass)...")
                        full_lyrics, _lyric_chunks = whisper_transcribe_lyrics_full(resolved_path, cross_check=True)
                        unload_whisper()
                        if full_lyrics and full_lyrics.strip():
                            revised += (
                                f"\n\nLYRICS HEARD IN AUDIO (secondary evidence; do not use when reliable lyrics are present):\n{full_lyrics}"
                            )
                        lyric_repetition_report = build_lyric_repetition_report(_lyric_chunks)
                        if lyric_repetition_report:
                            revised += "\n\n" + lyric_repetition_report

                    revised += f"\n\n11. ERA / RELEASE PERIOD (isolated dedicated pass):\n{era_result}"
                    try:
                        revised += _build_era_remaster_caveat(objective_report)
                    except Exception:
                        pass
                    if vocal_result:
                        revised += (
                            "\n\nVOCAL / SINGER PROFILE (isolated dedicated pass):\n"
                            + _mark_superseded_vocal_tags(vocal_result, locals().get("final_lead"))
                        )
                        if confirmation_result:
                            revised += (
                                "\n\nVOCAL CONFIRMATION PASS:\n"
                                + _mark_superseded_vocal_tags(confirmation_result, locals().get("final_lead"))
                            )

                        f0_text = f"{median_f0} Hz" if median_f0 is not None else "unavailable"
                        # Merge any additional detail not already captured above.
                        if confirmation_result:
                            conf_mv = parse_multi_voice_fields(confirmation_result)
                            for k, v in conf_mv.items():
                                if v and (not multi_voice_fields.get(k) or multi_voice_fields.get(k) in ("", "unparsed", "uncertain")):
                                    multi_voice_fields[k] = v
                        # INDEPENDENT TRIGGER: see the matching comment at the
                        # first occurrence of this block above for the full
                        # rationale. Runs even when MF's own pass (and the
                        # confirmation pass) reported only a single voice.
                        if (
                            ENABLE_INDEPENDENT_F0_MULTI_SINGER_TRIGGER
                            and (final_lead or initial_lead) not in ("mixed_leads", "")
                            and vocal_objective_report
                        ):
                            try:
                                f0_independent = _refine_multi_singer_from_f0(
                                    vocal_objective_report,
                                    min_sep=INDEPENDENT_MULTI_SINGER_MIN_SEP_SEMITONES,
                                    min_ratio=INDEPENDENT_MULTI_SINGER_MIN_RATIO,
                                )
                            except Exception:
                                f0_independent = {}
                            if f0_independent.get("num_distinct_voices") in ("2", "3+"):
                                # Two F0 centres can come from one singer's chest/head
                                # registers, octave doubling, harmonies, or pitch-tracking
                                # errors. Keep this as supporting evidence rather than
                                # upgrading a single-voice classification to a duet on
                                # pitch histogram alone.
                                for k, v in f0_independent.items():
                                    if v:
                                        multi_voice_fields[k] = v
                                multi_voice_fields["multi_voice_evidence"] = (
                                    (multi_voice_fields.get("multi_voice_evidence") or "")
                                    + " [Upgraded from a single-voice MF classification on "
                                    "independent objective f0 evidence — MF's own pass did not "
                                    "report a second voice, but the measured pitch histogram "
                                    "shows two well-separated, substantial centres consistent "
                                    "with two different singers/registers.]"
                                ).strip()

                        if (final_lead or initial_lead) == "mixed_leads" and not multi_voice_fields.get("voice_arrangement"):
                            multi_voice_fields["voice_arrangement"] = "duet_co_leads"
                            if not multi_voice_fields.get("num_distinct_voices"):
                                multi_voice_fields["num_distinct_voices"] = "2"
                            # Refine multi-singer detection using objective f0 multi-peak hint
                            if vocal_objective_report:
                                f0_suggest = _refine_multi_singer_from_f0(vocal_objective_report)
                                if f0_suggest:
                                    for k, v in f0_suggest.items():
                                        if v and (not multi_voice_fields.get(k) or multi_voice_fields.get(k) in ("", "unparsed", "uncertain")):
                                            multi_voice_fields[k] = v
                                    # If f0 suggests two distinct centres, strongly consider mixed_leads
                                    if f0_suggest.get("num_distinct_voices") in ("2", "3+"):
                                        if final_lead not in ("mixed_leads",):
                                            final_lead = "mixed_leads"
                                            multi_voice_fields["voice_arrangement"] = f0_suggest.get("voice_arrangement", "duet_co_leads")
                                            if not multi_voice_fields.get("co_lead_detail"):
                                                multi_voice_fields["co_lead_detail"] = f0_suggest.get("co_lead_detail", "two distinct pitch centres from f0 analysis")
                        revised += (
                            "\n\nVOCAL DECISION AUDIT (audio-only evidence for vocal age/gender):\n"
                            f"- Initial isolated lead profile: {initial_lead or 'unparsed'}\n"
                            f"- Confirmation pass: {confirm_lead or 'not run/unparsed'} (confidence={confirm_confidence or 'n/a'})\n"
                            f"- Objective median f0: {f0_text}\n"
                            f"- FINAL LEAD PROFILE: {final_lead or 'unknown'}\n"
                            f"- BACKING PROFILES: {initial_backing or 'uncertain'}\n"
                            "This is audio-only evidence. If a SINGER IDENTITY RESOLUTION block appears later in this analysis, use that for user-facing singer-identity claims; otherwise use FINAL LEAD PROFILE. Do not override a well-supported combined judgment with pitch impressions alone. If FINAL LEAD PROFILE is unknown/unparsed, do not treat free-text LEAD_PROFILE / LEAD_CATEGORY lines earlier in the vocal pass as a settled gender/age claim — those lines were not accepted as structured final tags. A very high objective median f0 can demote male/adolescent tags to uncertain; when FINAL is uncertain, prefer SINGER IDENTITY RESOLUTION (metadata + cover + pitch constraint) over any earlier free-text male claim."
                        )
                        mv_block = format_multi_voice_audit(
                            multi_voice_fields, final_lead or initial_lead, initial_backing or "uncertain"
                        )
                        if mv_block:
                            revised += "\n\n" + mv_block
                        # Presence salvage: failed lyric pass / false MF 'no vocals' must not
                        # poison the saved analysis or the writer reply.
                        _salv_note = locals().get('_early_vocal_salvage') or ''
                        if not _salv_note:
                            _, _salv_note, _ = _salvage_false_no_vocals(
                                vocal_result,
                                no_clear_vocals,
                                median_f0=median_f0,
                                vocal_objective_report=(vocal_objective_report or ''),
                                stem_midi_report='',
                                initial_lead=(initial_lead or final_lead or ''),
                            )
                        if _salv_note and 'VOCAL PRESENCE SALVAGE' not in (revised or ''):
                            revised += '\n\n' + _salv_note
                            if 'VOCALS_PRESENT=yes' not in revised:
                                revised += '\nVOCALS_PRESENT=yes  # from objective/structured salvage'
                    elif median_f0 is not None and _objective_evidence_of_vocals(median_f0=median_f0):
                        _ps = (
                            "VOCAL PRESENCE SALVAGE: no usable Music Flamingo vocal pass, but objective "
                            f"voiced pitch median ~{median_f0} Hz indicates a human voice is present. "
                            "Treat VOCALS_PRESENT=yes; age/gender may be uncertain. Do not claim the track "
                            "is instrumental solely because lyrics failed or the clip is short."
                        )
                        if 'VOCAL PRESENCE SALVAGE' not in (revised or ''):
                            revised += '\n\n' + _ps + '\nVOCALS_PRESENT=yes  # from objective pitch salvage'
                            no_clear_vocals = False

                    # Always expose vocal pitch information to the writer, independent of gender/age category.
                    if ENABLE_VOCAL_OBJECTIVE_REPORT and not current_track.startswith(("http://", "https://")):
                        pitch_lines = ["VOCAL PITCH REPORT (independent of lead age/gender category):"]
                        if median_f0 is None:
                            pitch_lines.append("- No reliable voiced pitch detected in the scanned portion.")
                        else:
                            pitch_lines.append(f"- objective voiced pitch median: {median_f0} Hz")
                            if vocal_pitch.get("note"):
                                pitch_lines.append(f"- approximate median note: {vocal_pitch['note']}")
                            if vocal_pitch.get("low") is not None and vocal_pitch.get("high") is not None:
                                pitch_lines.append(
                                    f"- 5-95 percentile range: {vocal_pitch['low']}-{vocal_pitch['high']} Hz"
                                )
                        pitch_lines.append(
                            "- Prefer median + 5–95 percentile range for the main vocal range. Median f0 is also used as a soft constraint on lead age/gender tags (high median can demote an overconfident post-puberty-male claim; it does not invent gender alone). "
                            "Do not treat absolute extremes from stem MIDI (often harmonics/octave errors) "
                            "as the sung range. Do not say the specific pitch range is missing when this block exists."
                        )
                        revised += "\n\n" + "\n".join(pitch_lines)
                        
                    # --- Reconcile BPM from MF, Essentia, and objective detector ---
                    mf_bpm_val = extract_bpm_from_text(first_pass)
                    revised_bpm_val = extract_bpm_from_text(revised)
                    if revised_bpm_val is not None:
                        mf_bpm_val = revised_bpm_val
                    essentia_bpm_val = extract_essentia_bpm(essentia_report) if essentia_report else None
                    objective_bpm_val = extract_objective_bpm(objective_report) if objective_report else None
                    essentia_median_bpm_val = extract_essentia_median_bpm(essentia_report) if essentia_report else None
                    objective_median_bpm_val = extract_objective_median_bpm(objective_report) if objective_report else None

                    _bpm_genre_hint = _genre_hint_from_analysis_text(
                        revised or first_pass,
                        panns_genre_tags,
                    )
                    final_bpm, bpm_note = reconcile_bpm(
                        mf_bpm_val, essentia_bpm_val, objective_bpm_val,
                        essentia_median_bpm=essentia_median_bpm_val,
                        objective_median_bpm=objective_median_bpm_val,
                        genre_hint=_bpm_genre_hint,
                    )

                    if final_bpm:
                        revised += (
                            f"\n\nRECOMMENDED TEMPO FOR DISCUSSION: {final_bpm} BPM. "
                            f"Reasoning: {bpm_note}. "
                            "This is the primary tempo to report to the user. "
                            "State it as a concrete figure (e.g. 'about 158 BPM'). "
                            "Do not expand it into a range unless this block itself marks the value as uncertain."
                        )
                    # -----------------------------------------------

                    # --- Reconcile KEY from MF and Essentia ---
                    mf_key_val = extract_key_from_text(first_pass)
                    revised_key_val = extract_key_from_text(revised)
                    if revised_key_val is not None:
                        mf_key_val = revised_key_val
                    essentia_key_val, essentia_key_strength = (None, None)
                    if essentia_report:
                        parsed = extract_essentia_key_from_text(essentia_report)
                        if parsed:
                            essentia_key_val, essentia_key_strength = parsed

                    final_key, key_note = reconcile_key(mf_key_val, essentia_key_val, essentia_key_strength)

                    if final_key:
                        revised += (
                            f"\n\nRECOMMENDED KEY FOR DISCUSSION: {final_key}. "
                            f"Reasoning: {key_note} "
                            "This is the primary key to report to the user unless the reasoning above marks it uncertain."
                        )
                    # -----------------------------------------------

                    # Numeric dynamics / loudness — prefer ORIGINAL local file (full
                    # duration, native rate/channels). Ignore ReplayGain tags.
                    crest_db_val = None
                    crest_src = "objective (librosa) crest-factor proxy"
                    lufs_val = lra_val = loudness_src = None
                    try:
                        _dyn_path = None
                        if (
                            current_track
                            and not str(current_track).startswith(("http://", "https://"))
                            and os.path.exists(current_track)
                        ):
                            _dyn_path = current_track
                        elif current_track in dsp_temp_files:
                            _dyn_path = dsp_temp_files[current_track]
                        elif "dsp_path" in locals() and dsp_path is not None:
                            _dyn_path = dsp_path
                        if _dyn_path:
                            crest_db_val = measure_crest_factor_db(_dyn_path)
                            lufs_val, lra_val, loudness_src = measure_ebur128_loudness(_dyn_path)
                    except Exception:
                        crest_db_val = None
                    if crest_db_val is None:
                        crest_db_val = extract_crest_db_from_text(objective_report) if objective_report else None
                    if crest_db_val is None and essentia_report:
                        crest_db_val = extract_crest_db_from_text(essentia_report)
                        if crest_db_val is not None:
                            crest_src = "Essentia crest-factor proxy"
                    dyn_block = format_recommended_dynamics_block(
                        crest_db=crest_db_val,
                        source_note=crest_src,
                        lufs=lufs_val,
                        lra=lra_val,
                        loudness_source=loudness_src,
                    )
                    if dyn_block:
                        revised += dyn_block
                    else:
                        revised += (
                            "\n\nRECOMMENDED DYNAMICS FOR DISCUSSION: unavailable "
                            "(could not compute EBU R128 loudness or crest-factor proxy from this file). "
                            "Do not invent a dB/LUFS figure; fall back only to qualitative production notes."
                        )

                    # Independent cross-checks via signal processing (local files only) — these
                    # come from actual DSP analysis of the waveform, not the model's own perception
                    measurement_parts = []
                    if objective_report:
                        measurement_parts.append(objective_report)
                    if vocal_objective_report:
                        measurement_parts.append(vocal_objective_report)
                    if essentia_report:
                        measurement_parts.append(essentia_report)
                    if ENABLE_ESSENTIA_REPORT:
                        if not ESSENTIA_AVAILABLE:
                            measurement_parts.append("ESSENTIA REPORT unavailable (essentia could not be imported).")
                        elif not essentia_report:
                            measurement_parts.append("ESSENTIA REPORT unavailable (imported, but no measurements were produced for this file).")

                    if measurement_parts:
                        revised += (
                            "\n\n[Independent signal-processing report:\n"
                            + "\n\n".join(measurement_parts)
                            + "\nThis is computed directly from the audio (librosa/Essentia), not from the model above — "
                            "use it only for tempo/beat, key/key strength when explicitly reported, timbre, "
                            "low/mid/high element activity, dynamic range / loudness (crest-factor proxy), "
                            "and vocal pitch/formant proxies. Do NOT use it to infer or revise GENRE."
                        )

                    if genre_mood_report:
                        revised += "\n\n" + genre_mood_report
                    try:
                        _rec_g, _rec_g_note = reconcile_genre(revised, panns_genre_tags)
                        revised += format_recommended_genre_block(_rec_g, _rec_g_note)
                        if _rec_g and "dsp_path" in locals() and dsp_path is not None:
                            _prev_k = extract_essentia_key_from_text(essentia_report) if essentia_report else None
                            _pk, _ps = (None, None)
                            if _prev_k:
                                _pk, _ps = _prev_k if isinstance(_prev_k, tuple) else (_prev_k, None)
                            _nk, _ns, _nnote = refine_essentia_key_with_genre(
                                dsp_path, _rec_g, previous_key=_pk, previous_strength=_ps
                            )
                            if _nnote:
                                revised += f"\n\nKEY PROFILE REFINEMENT: {_nnote}"
                            if _nk and _nnote and "shifted" in _nnote:
                                _mfk = extract_key_from_text(revised) or extract_key_from_text(first_pass)
                                _fk, _fnote = reconcile_key(_mfk, _nk, _ns)
                                if _fk:
                                    revised += (
                                        f"\n\nRECOMMENDED KEY FOR DISCUSSION: {_fk}. "
                                        f"Reasoning: {_fnote} (after genre-conditioned Essentia refinement). "
                                        "This is the primary key to report to the user unless the reasoning marks it uncertain."
                                    )
                    except Exception:
                        pass

                    # Optional Demucs 6s + Omnizart stem MIDI report.
                    # Essentia and Music Flamingo above still used only the original track.
                    stem_midi_report = ""
                    if ENABLE_STEM_MIDI and not current_track.startswith(("http://", "https://")):
                        try:
                            _get_omnizart()  # fail fast before slow Demucs run

                            if precomputed_stems:
                                # Reuse the separation already run above for
                                # vocal pitch isolation -- avoids a second,
                                # redundant Demucs pass.
                                stems = precomputed_stems
                            else:
                                if current_track in stem_temp_files:
                                    stem_wav = stem_temp_files[current_track]
                                else:
                                    status("Preparing stereo WAV for Demucs/MIDI...")
                                    stem_wav = convert_to_wav_for_stems(
                                        current_track,
                                        sample_rate=44100,
                                        channels=2,
                                        max_seconds=STEM_MIDI_MAX_SECONDS,
                                    )
                                    stem_temp_files[current_track] = stem_wav

                                status("Running Demucs 6s stem separation (this can be slow)...")
                                out_dir = tempfile.mkdtemp(prefix="demucs_")
                                demucs_out_dirs.append(out_dir)
                                stems = run_demucs_stems(
                                    stem_wav, out_dir,
                                    shifts=DEMUCS_SHIFTS_DEEP if DEEP_MODE else DEMUCS_SHIFTS_FAST,
                                )

                            if not stems:
                                stem_midi_report = "STEM MIDI REPORT unavailable: Demucs did not produce expected stems."
                            else:
                                whole_mix_tags = None
                                if ENABLE_WHOLE_MIX_INSTRUMENT_TAGGING and dsp_path is not None:
                                    try:
                                        status("Tagging instruments on the full (un-separated) mix...")
                                        whole_mix_tags = tag_full_mix_instruments(dsp_path)
                                    except Exception as e:
                                        print(f"  (whole-mix instrument tagging skipped: {e})")
                                        whole_mix_tags = None
                                status("Running Omnizart on each separated stem...")
                                _total_duration = _resolve_total_duration(
                                    track_path=current_track, dsp_path=dsp_path,
                                    objective_report=objective_report,
                                )
                                if not _structure_sections:
                                    _structure_sections, _bnd_pre, _ = _finalize_structure_sections(
                                        revised or first_pass,
                                        objective_report=objective_report,
                                        lyric_chunks=locals().get("_lyric_chunks"),
                                        total_duration=_total_duration,
                                    )
                                _stem_notes_raw = {}
                                # Per-stem energy/density, used below to
                                # cross-check a missing guitar tag against the
                                # actual Demucs guitar stem.
                                _stem_activity_raw = []
                                # Cross-stem instrument agreement map.
                                _stem_convergence = {}
                                # sections=None: section-keyed blocks are built
                                # after refinement, from the final map.
                                stem_midi_report = build_omnizart_summaries(
                                    stems, whole_mix_tags=whole_mix_tags,
                                    bpm=final_bpm, sections=None, key=final_key,
                                    notes_out=_stem_notes_raw,
                                    mix_audio_path=dsp_path,
                                    activity_out=_stem_activity_raw,
                                    convergence_out=_stem_convergence,
                                )
                                # Appended after refinement (see below).
                                if whole_mix_tags is not None:
                                    whole_mix_report = build_whole_mix_instrument_report(
                                        dsp_path, tags=whole_mix_tags
                                    )
                                    if whole_mix_report:
                                        stem_midi_report = (
                                            stem_midi_report + "\n\n" + whole_mix_report
                                        )
                                        try:
                                            _gan = guitar_absence_note_from_tags(
                                                locals().get("whole_mix_tags"), whole_mix_report,
                                                mix_audio_path=dsp_path,
                                                stem_notes=locals().get("_stem_notes_raw"),
                                                activity_metas=locals().get("_stem_activity_raw"),
                                                cross_stem_agreement=locals().get("_stem_convergence"),
                                            )
                                            if _gan:
                                                stem_midi_report = stem_midi_report + "\n\n" + _gan
                                        except Exception:
                                            pass
                                _release_omnizart_memory()

                        except Exception as e:
                            print(f"  (stem MIDI skipped/unavailable: {e})")
                            stem_midi_report = f"STEM MIDI REPORT unavailable: {e}"

                    # Always append the stem MIDI report to revised, even if unavailable,
                    # so the output LLM knows the status and it's logged in the save file.
                    stem_midi_report = (
                        stem_midi_report
                        or "STEM MIDI REPORT not run (disabled or non-local track)."
                    )

                    if not is_snippet:
                        track_stem_midi_report[current_track] = stem_midi_report

                    # Include the report in the saved/comprehensive analysis once.
                    revised += "\n\n" + stem_midi_report

                    # Presence salvage, second pass -- same rationale as the
                    # batch/heavy path (see run_fresh_track_analysis_heavy):
                    # the two earlier _salvage_false_no_vocals() calls ran
                    # before Demucs/Omnizart had produced this evidence, so
                    # they could not see it. This is the first point the
                    # vocal-stem's own measured onset is available to check.
                    if (
                        "VOCALS_PRESENT=yes" not in revised
                        and "EARLIEST VOCAL ONSET:" in stem_midi_report
                    ):
                        revised += (
                            "\n\nVOCAL PRESENCE SALVAGE (from vocal-stem transcription): the "
                            "isolated vocal stem has a measured note onset (see EARLIEST VOCAL "
                            "ONSET above), confirming a human voice is present in this "
                            "recording. Treat VOCALS_PRESENT=yes; do not describe the track, or "
                            "its opening, as instrumental on the strength of Music Flamingo's "
                            "own vocal-pass prose alone when this measured onset contradicts it."
                            "\nVOCALS_PRESENT=yes  # from vocal-stem onset salvage"
                        )

                    # Add authoritative structure block
                    total_duration = _resolve_total_duration(
                        track_path=current_track, dsp_path=dsp_path,
                        objective_report=objective_report,
                    )

                    _lyric_groups_for_structure = None
                    try:
                        _lc = locals().get("_lyric_chunks")
                        _lyric_groups_for_structure = (
                            _detect_lyric_repetitions(_lc) if _lc else None
                        )
                    except Exception:
                        _lyric_groups_for_structure = None

                    # Final section map: the audio model leads (it understands
                    # song form), measurement sharpens its boundaries, lyrics
                    # correct its names. Same rationale as the batch path.
                    _mf_sections = []
                    try:
                        _mf_sections = extract_structure_sections(revised or "")
                    except Exception:
                        _mf_sections = []

                    structure_sections, _structure_source = _resolve_final_structure(
                        _mf_sections,
                        dsp_sections=_structure_sections,
                        lyric_groups=_lyric_groups_for_structure,
                        lyric_chunks=locals().get("_lyric_chunks"),
                        total_duration=total_duration,
                        grid=_struct_grid,
                        stem_notes=locals().get("_stem_notes_raw"),
                        bpm=locals().get("final_bpm"),
                    )
                    if structure_sections:
                        boundary_seconds = [
                            float(s["start"]) for s in structure_sections[1:]
                        ]
                        revised = _overwrite_structure_field(revised, structure_sections)
                        status_done(
                            f"Section map resolved ({_structure_source}, "
                            f"{len(structure_sections)} sections)"
                        )
                    else:
                        structure_sections, boundary_seconds, _lg = _finalize_structure_sections(
                            revised,
                            objective_report=objective_report,
                            stem_midi_report=locals().get("stem_midi_report") or "",
                            lyric_chunks=locals().get("_lyric_chunks"),
                            total_duration=total_duration,
                        )
                        _lyric_groups_for_structure = (
                            _lg or _lyric_groups_for_structure
                        )

                    if structure_sections:
                        try:
                            _sk = build_section_keyed_stem_blocks(
                                locals().get("stems") or {}, structure_sections,
                                locals().get("_stem_notes_raw") or {},
                                bpm=final_bpm, key=final_key,
                            )
                            if _sk:
                                stem_midi_report = (
                                    (locals().get("stem_midi_report") or "").rstrip()
                                    + "\n\n" + _sk
                                )
                                # Same immutable-string bug as the main path:
                                # `revised` already holds a copy, and the
                                # per-track cache was filled before this point
                                # too, so both need the blocks appended
                                # explicitly or they never reach the writer.
                                revised += "\n\n" + _sk
                                if not is_snippet:
                                    track_stem_midi_report[current_track] = stem_midi_report
                        except Exception as e:
                            print(f"  (section-keyed stem blocks skipped: {e})")

                    if not is_snippet:
                        track_stem_notes[current_track] = locals().get("_stem_notes_raw") or {}
                        track_structure_sections[current_track] = structure_sections
                        track_bpm_key[current_track] = (final_bpm, final_key)

                    structure_block = format_recommended_structure_block(
                        structure_sections,
                        objective_boundaries=boundary_seconds,
                        total_duration=total_duration,
                        lyric_groups=_lyric_groups_for_structure,
                        objective_report=objective_report,
                    )
                    if structure_block:
                        revised += "\n\n" + structure_block

                    if (
                        ENABLE_WHOLE_MIX_INSTRUMENT_TAGGING
                        and dsp_path is not None
                        and "WHOLE-MIX INSTRUMENT TAGS" not in (stem_midi_report or "")
                    ):
                        status("Tagging instruments on the full (un-separated) mix...")
                        try:
                            whole_mix_report = build_whole_mix_instrument_report(dsp_path)
                            if whole_mix_report:
                                revised += "\n\n" + whole_mix_report
                                _gan = ""
                                try:
                                    _gan = guitar_absence_note_from_tags(
                                        locals().get("whole_mix_tags"), whole_mix_report,
                                        mix_audio_path=dsp_path,
                                        stem_notes=locals().get("_stem_notes_raw"),
                                        activity_metas=locals().get("_stem_activity_raw"),
                                        cross_stem_agreement=locals().get("_stem_convergence"),
                                    )
                                except Exception:
                                    _gan = ""
                                if _gan:
                                    revised += "\n\n" + _gan
                        except Exception as e:
                            print(f"  (whole-mix instrument tagging skipped: {e})")

                    # Move singer identity resolution OUTSIDE the MIDI check, 
                    # because it should run regardless of whether MIDI succeeded.
                    singer_identity_text = ""
                    if ENABLE_SINGER_IDENTITY_RESOLUTION and (
                        track_metadata.get(current_track) or track_cover_observations.get(current_track)
                    ):
                        f0_text_res = f"{median_f0} Hz" if median_f0 is not None else "unavailable"
                        vocal_audit_for_resolution = (
                            f"Initial isolated lead profile: {initial_lead or 'unparsed'}\n"
                            f"Confirmation pass: {confirm_lead or 'not run/unparsed'} (confidence={confirm_confidence or 'n/a'})\n"
                            f"FINAL LEAD PROFILE: {final_lead or 'unknown'}\n"
                            f"BACKING PROFILES: {initial_backing or 'uncertain'}\n"
                            f"objective median f0: {f0_text_res}"
                        )

                        if no_clear_vocals:
                            vocal_audit_for_resolution = "No clear vocals detected.\n" + vocal_audit_for_resolution

                        _release_heavy_analysis_memory_before_identity()

                        status("Resolving singer identity from audio + metadata + cover art...")
                        singer_identity_text = resolve_singer_identity(
                            track_metadata.get(current_track, {}),
                            vocal_audit_for_resolution,
                            track_cover_observations.get(current_track),
                            track_corrections.get(current_track, {}),
                        )

                        if not is_snippet:
                            if singer_identity_text:
                                track_singer_identity[current_track] = singer_identity_text.strip()
                            else:
                                track_singer_identity.pop(current_track, None)

                        cover_obs_block = (
                            _format_cover_observation_block(track_cover_observations.get(current_track))
                            if track_cover_observations else ""
                        )
                        if cover_obs_block and "COVER ART OBSERVATIONS" not in revised:
                            revised += "\n\n" + cover_obs_block

                        resolved_tag = _parse_singer_identity(singer_identity_text) if singer_identity_text else ""

                        if singer_identity_text and "SINGER IDENTITY RESOLUTION" not in revised:
                            revised += (
                                f"\n\nSINGER IDENTITY RESOLUTION (combined audio + metadata + cover art; use for who-is-singing questions):\n{singer_identity_text}"
                            )

                        priority_tag = _reconcile_identity_with_acoustic_age(resolved_tag, final_lead)
                        if vocal_result or singer_identity_text:
                            revised += build_vocal_priority_note(priority_tag, initial_backing or "uncertain")

                    revised = _collapse_runaway_repetition_fields(revised)
                    if is_snippet:
                        # Excerpt results are turn-local evidence. Never overwrite the
                        # full-track analysis/evidence caches with a cropped result.
                        turn_analysis = revised
                        last_scan_was_excerpt = True
                    else:
                        comprehensive_analyses[current_track] = revised
                        track_analysis_signatures[current_track] = _audio_file_signature(current_track)
                        last_scanned_track = current_track
                        last_scan_was_excerpt = False

                    # Sonic embedding at the end of the analysis, not only on
                    # /save. Without this a freshly listened-to track has no
                    # embedding in the session at all, so it cannot take part
                    # in a sonic-similarity comparison until it has been saved
                    # and re-loaded from JSON. The result is cached, so the
                    # later /save reuses it rather than running CLAP twice.
                    if (
                        ENABLE_CLAP_EMBEDDING
                        and not is_snippet
                        and current_track
                        and current_track not in track_clap_embeddings
                        and not str(current_track).startswith(("http://", "https://"))
                    ):
                        try:
                            status("Computing sonic-similarity embedding...")
                            _emb = compute_clap_embedding(current_track)
                            if _emb is not None:
                                track_clap_embeddings[current_track] = _emb
                                status_done("Sonic embedding ready")
                            else:
                                status_done("Sonic embedding unavailable")
                        except Exception as e:
                            print(f"  (CLAP embedding skipped: {e})")

                    if SHOW_RAW_ANALYSIS:
                        print(f"\n  ── Music Flamingo's raw analysis for {track_label(current_track)} ──")
                        print(f"  {revised}")
                        print("  ──────────────────────────────────────────────────────────\n")
                else:
                    status_done("Using cached full analysis for this track")
                    last_scanned_track = current_track
                    last_scan_was_excerpt = False

                    if SHOW_RAW_ANALYSIS:
                        print(f"\n  ── Music Flamingo's raw analysis for {track_label(current_track)} ──")
                        print(f"  {comprehensive_analyses[current_track]}")
                        print("  ──────────────────────────────────────────────────────────\n")

                label = track_label(current_track)
                
                # Get the analysis text for this turn. Excerpt scans are intentionally
                # turn-local; a later full-track question must still use the full cache.
                if is_snippet:
                    revised = turn_analysis or ""
                else:
                    revised = comprehensive_analyses[current_track]

                # --- Drum highlight extraction (only if the question asks about drums/beat) ---
                drum_highlights = ""
                if re.search(r"\b(drums?|beat|groove|rhythm|percussion)\b", question, re.IGNORECASE):
                    drum_lines = []
                    for line in revised.splitlines():
                        l = line.lower()
                        if ("groove_hint" in l or 
                            "kick beat-grid" in l or 
                            "snare beat-grid" in l or 
                            "swing/shuffle" in l or
                            "per-section groove" in l):
                            drum_lines.append(line.strip())
                    if drum_lines:
                        drum_highlights = (
                            "DRUM PATTERN SUMMARY (extracted from analysis, prioritise these for beat/rhythm answers):\n"
                            + "\n".join(drum_lines[:5])
                            + "\n"
                        )

                corrections = track_corrections.get(current_track)
                correction_block = ""
                if corrections:
                    correction_lines = "\n".join(f"- {k}: {v}" for k, v in corrections.items())
                    correction_block = (
                        f"\n\nCONFIRMED CORRECTIONS FOR THIS TRACK (from the user — ground truth, "
                        f"overrides the analysis above wherever they conflict):\n{correction_lines}"
                    )

                vocal_question = bool(
                    re.search(
                        r"\b(singer|singing|vocals?|voice|male|female|boy|girl|man|woman|gender)\b",
                        question,
                        re.IGNORECASE,
                    )
                )
                depth_requested = bool(
                    re.search(
                        r"\b(in[\s-]?depth|in\s+detail|elaborate|tell me more|go deeper|"
                        r"more detail|full breakdown|deep dive|thorough|comprehensive|"
                        r"everything (you'?ve got|you know)|expand on|say more|break (it|that|this) down|"
                        r"walk me through|long answer|really get into)\b",
                        question,
                        re.IGNORECASE,
                    )
                )
                reply_style_note = (
                    "Reply as their music buddy in the conversation. They asked for depth here — "
                    "give a genuinely long, detailed answer that actually goes into it, not a short "
                    "summary with a token gesture toward length."
                    if depth_requested else
                    "Reply as their music buddy in the conversation — answer what they asked, "
                    "not a full analytical write-up unless they asked for one."
                )
                vocal_gate_note = ""
                if vocal_question:
                    vocal_gate_note = (
                        "\n\nFor this specific question about the singer/voice, start from any CONFIRMED CORRECTIONS. "
                        "If a SINGER IDENTITY RESOLUTION block is present in the track context, use it as the primary combined judgment; it already weighs audio, metadata, and cover art. "
                        "Only override it if user correction, distinct co-lead evidence, or unambiguous adult vocal evidence clearly contradicts it. "
                        "If no resolution block is present, combine the VOCAL DECISION AUDIT / FINAL LEAD PROFILE with file metadata, reliable artist knowledge, and cover-art cues. "
                        "Do not default a high-pitched young voice to female when the combined context supports a male solo artist."
                    )

                metadata_block = (
                    _format_metadata_block(track_metadata.get(current_track, {}))
                    if ENABLE_FILE_METADATA else ""
                )

                context_prior_note = ""
                if ENABLE_FILE_METADATA:
                    meta = track_metadata.get(current_track, {}) or {}
                    if any(str(meta.get(k) or "").strip() for k in ("title", "artist", "album", "year")):
                        year_bit = f", {meta.get('year')}" if meta.get("year") else ""
                        year_lock = ""
                        if meta.get("year"):
                            year_lock = (
                                f" The reliable release year for this track is {meta.get('year')}; "
                                "use that year when stating when the track or album was released. "
                                "Do not replace it with a different year from knowledge of other releases by the same artist. "
                                "State it plainly (\"came out in {y}\") — don't cite where the year came from."
                            ).format(y=meta.get("year"))
                        context_prior_note = (
                            "\n\nTRACK ID (private reference only — reliable, but never cite this framing "
                            "out loud; just state the facts the way you'd naturally know them): this recording "
                            "is "
                            f"{meta.get('title') or 'unknown title'} by {meta.get('artist') or 'unknown artist'}"
                            + (f" from {meta.get('album')}" if meta.get("album") else "")
                            + year_bit
                            + ". "
                            "Talk about the artist, vocalist, and producer freely when it's useful or asked about — "
                            "credits, discography, career/album context, reception, influences, comparisons, general "
                            "reputation and history are all fair game from your normal knowledge, same as you'd "
                            "discuss any artist. Don't hedge on well-known background facts you're actually confident about.\n"
                            "The one place to be careful: when you're specifically characterising what THIS "
                            "RECORDING sounds like (its genre, instrumentation, arrangement, production, vocal "
                            "delivery), ground that in the audio evidence above rather than in what this artist "
                            "'usually' sounds like or how their other releases are remembered — an artist can make "
                            "a record that doesn't match their reputation. If your background knowledge and the "
                            "audio evidence would point to different sounds, trust the audio evidence and it's fine "
                            "to note the two agree or don't.\n"
                            "Don't state uncertain trivia as fact, and don't guess at nationality/origin unless "
                            "confident — outside of that, engage normally."
                            + year_lock
                        )

                # Cached once per track by default, or re-looked-up fresh using this
                # question's own keywords when WIKI_CONTEXT_REFRESH_EVERY_QUESTION is
                # True — see build_wiki_context_block() for the strict background-only
                # / no-audio-technical-facts scope.
                wiki_context_block = _get_or_build_wiki_context(
                    current_track, track_metadata, track_wiki_context, question=question,
                    persona_gate=(active_persona_text.strip() != DEFAULT_PERSONA_PROMPT.strip()),
                )

                cover_images = []
                if SEND_COVER_ART_TO_OLLAMA and OLLAMA_SUPPORTS_IMAGES:
                    cover_b64 = track_cover_b64.get(current_track)
                    if cover_b64 and cover_b64 != NO_COVER_SENTINEL:
                        cover_images.append(cover_b64)
                        status_done("Attaching embedded cover art to writer")
                    else:
                        status_done("No usable embedded cover art found/attached")

                writer_images = cover_images[:]
                explicit_image_obs_block = ""

                if extra_image_refs:
                    obs_parts = []
                    for i, ref in enumerate(extra_image_refs):
                        if len(writer_images) >= MAX_IMAGES_PER_REQUEST:
                            break

                        try:
                            b64 = image_to_base64(ref)
                        except Exception as e:
                            print(f"  (skipping unreadable explicit image {ref}: {e})")
                            continue

                        writer_images.append(b64)

                        if ENABLE_IMAGE_OBSERVATIONS_FOR_GENERAL and i < MAX_IMAGES_TO_DESCRIBE:
                            obs = describe_cover_art(b64)
                            if obs:
                                obs_parts.append(
                                    f"EXPLICIT IMAGE {i + 1} OBSERVATIONS ({ref}):\n"
                                    + _format_cover_observation_block(obs)
                                )

                    explicit_image_obs_block = "\n\n".join(obs_parts)

                has_cover_context = (
                    bool(cover_images)
                    or bool(track_cover_observations.get(current_track))
                    or ("COVER ART OBSERVATIONS" in comprehensive_analyses[current_track])
                    or bool(explicit_image_obs_block)
                )
                cover_note = COVER_ART_CONTEXT_NOTE if has_cover_context else ""

                # The full evidence block (Music Flamingo analysis + Essentia report +
                # stem/MIDI note logs + singer identity resolution) is large — often the
                # single biggest contributor to prompt size. It only needs to go out in
                # full once per track per session — after that it's already sitting in
                # writer_history. But that's only safe to skip if the earlier message
                # holding it (a) hasn't been evicted by history compaction and (b) isn't
                # at risk of being dropped by this request's context-budget trimming
                # (which only guarantees the newest message survives). If either check
                # fails, fall back to sending it in full again — a pointer to evidence
                # the model doesn't actually have is worse than the extra tokens.
                prior_evidence_msg = track_evidence_message.get(current_track)
                evidence_still_safe = prior_evidence_msg is not None and _evidence_message_still_safe(
                    writer_history, prior_evidence_msg, OLLAMA_NUM_CTX
                )

                if evidence_still_safe:
                    evidence_section = (
                        "(Private notes for this track are already in the conversation — "
                        "reuse them; they have not changed unless a CONFIRMED CORRECTIONS "
                        "section appears below. Do not restate the notes unless the user asks.)"
                    )
                else:
                    evidence_section = (
                        "=== PRIVATE TRACK NOTES (for you only; do not recite as a report) ===\n"
                        "TRACK SCOPE: The notes below describe ONLY this track "
                        f"({label}). Do not attribute instruments, vocals, tempo, key, "
                        "or production details from any earlier track in this conversation "
                        "to this one unless the user is explicitly comparing and you name "
                        "each track. Previous tracks may be used only as comparison points, "
                        "never as evidence for this track. "
                        "Never transfer instruments, vocal qualities, genre/style traits, "
                        "arrangement details, mix characteristics, or production descriptions "
                        "from another analysed track into the current track. "
                        "Phantom carry-over of guitar/piano/strings is a known "
                        "failure mode — if these notes omit an instrument or include a "
                        "GUITAR ABSENCE NOTE, that instrument is not present here. "
                        "A 'GUITAR EVIDENCE INCONCLUSIVE' or 'GUITAR EVIDENCE UNAVAILABLE' "
                        "note is the opposite case and must not be reported as absence: "
                        "when comparing two tracks, do not contrast one as 'has guitar' "
                        "against the other as 'no guitar' on the strength of such a note, "
                        "and do not use it to argue either track is more or less rock. "
                        "If several RECOMMENDED KEY blocks appear, use the last one "
                        "(after any KEY PROFILE REFINEMENT). "
                        "For tempo, use RECOMMENDED TEMPO's integer only — do not voice "
                        "genre-prior or detector jargon.\n\n"
                        + comprehensive_analyses[current_track]
                    )

                # metadata_block / context_prior_note / wiki_context_block / cover_note are
                # all static per-track content that was already bundled into the same
                # writer message as evidence_section the first time this track was
                # discussed (see track_evidence_message below). If that earlier message
                # is still safely present in writer_history — same check used for the
                # evidence block above — these don't need to go out again either; a
                # short pointer is enough. If it's not safe (evicted by compaction, or at
                # risk of being trimmed from this request), fall back to sending them in
                # full, same as evidence_section does.
                if evidence_still_safe:
                    static_context_note = (
                        "(Wiki background and file metadata notes for this track are "
                        "also already above — reuse them unless something in "
                        "CONFIRMED CORRECTIONS contradicts them.)"
                    )
                    metadata_block = ""
                    context_prior_note = ""
                    wiki_context_block = ""
                    # cover_note is deliberately NOT suppressed here: has_cover_context
                    # (above) is recomputed fresh every turn and can turn True for
                    # reasons unrelated to old track evidence — e.g. the user attaches
                    # a brand-new image this turn via extra_image_refs. Gating it on
                    # evidence_still_safe risked dropping cover-art guidance on exactly
                    # the turn it's newly relevant. It's a small fixed block, so the
                    # token cost of always sending it when has_cover_context is True is
                    # low relative to that risk.
                else:
                    static_context_note = ""

                # The actual question ends up FAR more likely to get a direct,
                # context-aware answer (rather than a generic "here's an overview
                # of this track" reply) when it isn't buried at the bottom of a
                # single giant message stacked underneath the full evidence dump.
                # Small local models in particular tend to latch onto whatever
                # dominates the prompt, and the private-notes block is often the
                # single largest thing in the request the first time a track is
                # discussed. So: when the full evidence needs to go out (brand
                # new track, or evicted from history), send it as its OWN turn
                # with a short synthesized ack — mirroring how /load already
                # separates "here's the loaded track" from the follow-up
                # question — then send the question as a short, separate, FINAL
                # turn so it's the most recent (and most attended-to) thing the
                # model sees. When the evidence is already safely in history,
                # keep the previous lean single-message behaviour.
                context_linking_note = (
                    "\n\nIf what they're asking relates to something already discussed earlier in this "
                    "conversation — comparing this to another track, continuing a topic, reacting to an "
                    "earlier point — use those earlier turns to answer that directly. Don't just give a "
                    "standalone description of this track in isolation when they asked about a connection "
                    "to something already talked about. "
                    "When comparing, name each track explicitly. Never import instruments from an earlier "
                    "track onto the current one (e.g. do not say this track has guitar only because the "
                    "previous song did)."
                )

                if not OLLAMA_SUPPORTS_IMAGES:
                    writer_images = []
                else:
                    writer_images = [img for img in writer_images if _is_sendable_base64_image(img)]

                if not evidence_still_safe:
                    context_turn_msg = (
                        f"[We're listening to: {label}]\n\n"
                        f"{evidence_section}"
                        f"{correction_block}"
                        f"{metadata_block}"
                        f"{context_prior_note}"
                        # The boundary marker only goes out when there is
                        # actually background material below it to fence off.
                        f"{AUDIO_EVIDENCE_FIREWALL_NOTE if wiki_context_block else ''}"
                        f"{wiki_context_block}"
                        f"{cover_note}"
                    )
                    context_message = {"role": "user", "content": context_turn_msg}
                    if writer_images:
                        context_message["images"] = writer_images[:MAX_WRITER_IMAGES_PER_TURN]

                    writer_history.append(context_message)
                    # This message now holds the full evidence block — remember it (by
                    # object identity) as the one to check against on future turns.
                    track_evidence_message[current_track] = context_message
                    writer_history.append({
                        "role": "assistant",
                        "content": f"Got it — I have the details on '{label}'. What would you like to know?",
                    })

                    writer_question_notes = _build_writer_question_notes(
                        question,
                        depth_requested=depth_requested,
                        metadata=track_metadata.get(current_track, {}),
                    )
                    writer_user_msg = (
                        f"{snippet_caution}"          # <-- ADD THIS LINE
                        f"{drum_highlights}"          # <-- ADD THIS LINE
                        f"{vocal_gate_note}\n\n"
                        f"User said: {question}"
                        f"{context_linking_note}\n\n"
                        f"{writer_question_notes}\n\n"
                        f"{reply_style_note}"
                    )
                    writer_message = {"role": "user", "content": writer_user_msg}

                else:
                    writer_question_notes = _build_writer_question_notes(
                        question,
                        depth_requested=depth_requested,
                        metadata=track_metadata.get(current_track, {}),
                    )
                    snippet_caution = ""
                    if is_snippet:
                        snippet_caution = (
                            f"\n\nAUDIO EXCERPT CAUTION: The analysis below was performed on a short excerpt from "
                            f"{listen_segment[0]}s to {listen_segment[1]}s. The structural timestamps in the notes "
                            "are relative to that excerpt, not the full song. Do not describe sections that occur "
                            "outside this excerpt; base your answer only on what is audible in that range.\n"
                        )

                    writer_user_msg = (
                        f"[We're listening to: {label}]\n\n"
                        f"{snippet_caution}"
                        f"{drum_highlights}"
                        f"{evidence_section}"
                        f"{static_context_note}"
                        f"{correction_block}"
                        f"{cover_note}"
                        f"{vocal_gate_note}\n\n"
                        f"User said: {question}"
                        f"{context_linking_note}\n\n"
                        f"{writer_question_notes}\n\n"
                        f"{reply_style_note}"
                    )
                    writer_message = {"role": "user", "content": writer_user_msg}
                    if writer_images:
                        writer_message["images"] = writer_images[:MAX_WRITER_IMAGES_PER_TURN]

                last_writer_message = writer_message
                writer_history.append(writer_message)

                status("Writing...")
                final_reply, _usage = _safe_ollama_chat(writer_history)
                if final_reply is None:
                    status_done()
                    continue
                writer_history.append({"role": "assistant", "content": final_reply})

            else:
                # General question / cross-track comparison — straight to the output LLM.
                # Multiple image references are now supported in one message.
                cleaned_text, image_refs = extract_image_references(user_text)

                if image_refs and not OLLAMA_SUPPORTS_IMAGES:
                    print("  (Ollama model is marked as text-only; ignoring image references)")
                    image_refs = []

                if image_refs:
                    refs = image_refs[:max(MAX_WRITER_IMAGES_PER_TURN, MAX_IMAGES_TO_DESCRIBE)]
                    print(f"  (found {len(image_refs)} image reference(s), sending to {OLLAMA_MODEL}...)")
                    if len(image_refs) > len(refs):
                        print(f"  (limiting this request to the first {len(refs)} images)\n")

                    b64_images = []
                    obs_blocks = []

                    for i, ref in enumerate(refs):
                        try:
                            b64 = image_to_base64(ref)
                        except Exception as e:
                            print(f"  (skipping unreadable image {ref}: {e})")
                            continue

                        b64_images.append(b64)

                        if ENABLE_IMAGE_OBSERVATIONS_FOR_GENERAL and i < MAX_IMAGES_TO_DESCRIBE:
                            obs = describe_cover_art(b64)
                            if obs:
                                obs_blocks.append(
                                    f"IMAGE {i + 1} OBSERVATIONS ({ref}):\n"
                                    + _format_cover_observation_block(obs)
                                )

                    image_obs_block = "\n\n".join(obs_blocks)
                    base_content = cleaned_text or "Describe these images."
                    content = f"{base_content}\n\n{image_obs_block}" if image_obs_block else base_content
                    if b64_images:
                        content = f"{content}\n\n{GENERAL_IMAGE_CHAT_NOTE}"

                    if len(b64_images) > MAX_WRITER_IMAGES_PER_TURN:
                        print(f"  (limiting Ollama request to first {MAX_WRITER_IMAGES_PER_TURN} images)")

                    writer_message = {
                        "role": "user",
                        "content": content,
                        "images": b64_images[:MAX_WRITER_IMAGES_PER_TURN],
                    }
                    last_writer_message = writer_message
                    writer_history.append(writer_message)

                    status("Writing...")
                    final_reply, _usage = _safe_ollama_chat(writer_history)
                    if final_reply is None:
                        status_done()
                        continue
                    writer_history.append({"role": "assistant", "content": final_reply})

                else:
                    wiki_general_block = build_wiki_context_for_general_question(
                        user_text, track_metadata, current_track,
                        writer_history=writer_history,
                        extra_tracks=active_compare_keys,
                        persona_gate=(active_persona_text.strip() != DEFAULT_PERSONA_PROMPT.strip()),
                    )
                    if WIKI_DEBUG_LOG:
                        if wiki_general_block:
                            _matched_titles = re.findall(r'--- "(.+?)" ---', wiki_general_block)
                            print(f"  (wiki: matched {len(_matched_titles)} article(s): {', '.join(_matched_titles)})")
                        else:
                            print("  (wiki: no local DB match for this question — answering from the model's own knowledge)")

                    # /loadcompare builds a CLAP sonic-similarity block for the
                    # tracks it just loaded together. Loading the same two (or
                    # more) tracks via separate /load calls left this evidence
                    # out entirely, even though comprehensive_analyses already
                    # keeps every loaded-this-session track around (it is only
                    # cleared by /clearall) and track_clap_embeddings persists
                    # the same way. _format_clap_comparison already returns ""
                    # when fewer than two embeddings are available, so this is
                    # safe to call unconditionally and adds nothing when only
                    # one track is loaded.
                    clap_general_block = ""
                    if ENABLE_CLAP_EMBEDDING and len(comprehensive_analyses) >= 2:
                        _clap_keys = [
                            k for k in comprehensive_analyses.keys()
                            if k in track_clap_embeddings
                        ]
                        if len(_clap_keys) >= 2:
                            clap_general_block = _format_clap_comparison(
                                _clap_keys,
                                [track_label(k) for k in _clap_keys],
                                track_clap_embeddings,
                            )

                    writer_message = {
                        "role": "user",
                        "content": (
                            user_text + wiki_general_block
                            + (f"\n\n{clap_general_block}" if clap_general_block else "")
                        ),
                    }
                    last_writer_message = writer_message
                    writer_history.append(writer_message)
                    status("Thinking...")
                    final_reply, _usage = _safe_ollama_chat(writer_history)
                    if final_reply is None:
                        status_done()
                        continue
                    writer_history.append({"role": "assistant", "content": final_reply})

            status_done()
            print(_colorize(f"\nMusiclyse: {final_reply}\n", Ansi.MAGENTA))
            _print_token_usage(locals().get("_usage") or SESSION_TOKEN_USAGE)
    finally:
        for temp_path in audio_temp_files.values():
            if os.path.exists(temp_path):
                os.remove(temp_path)
        for temp_path in dsp_temp_files.values():
            if os.path.exists(temp_path):
                os.remove(temp_path)
        for temp_path in stem_temp_files.values():
            if os.path.exists(temp_path):
                os.remove(temp_path)
                
        try:
            unload_music_flamingo()
        except Exception:
            pass
        try:
            unload_whisper()
        except Exception:
            pass

        _release_omnizart_memory()
        

        for d in demucs_out_dirs:
            try:
                shutil.rmtree(d, ignore_errors=True)
            except Exception:
                pass

        for d in _OMNIZART_OUTPUT_DIRS:
            try:
                shutil.rmtree(d, ignore_errors=True)
            except Exception:
                pass


if __name__ == "__main__":
    # Subprocess entry for isolated batch tracks:
    #   python musiclyse.py --batch-one /path/to/song.mp3
    # Parent batch orchestrator launches this so each track gets a clean process.
    if len(sys.argv) >= 3 and sys.argv[1] == "--batch-one":
        track = sys.argv[2]
        # Minimal banner so overnight logs stay readable.
        print(f"  [batch-one] {os.path.basename(track)}")
        try:
            run_batch_one_track(track)
            sys.exit(0)
        except Exception as e:
            print(f"  ✗ batch-one failed: {e}", file=sys.stderr)
            try:
                _aggressive_memory_cleanup()
            except Exception:
                pass
            sys.exit(1)

    # Split-process batch entries (BATCH_SPLIT_IDENTITY_PROCESS, default on):
    #   python musiclyse.py --batch-one-analyze /path/to/song.mp3 /tmp/staging.json
    #   python musiclyse.py --batch-one-finish /tmp/staging.json
    # The parent orchestrator (_batch_run_isolated) runs these as two
    # separate processes per track so the identity/save stage always starts
    # from a clean memory baseline, regardless of what the heavy stage's
    # process was unable to fully release before it exits.
    if len(sys.argv) >= 4 and sys.argv[1] == "--batch-one-analyze":
        track, staging_path = sys.argv[2], sys.argv[3]
        print(f"  [batch-one-analyze] {os.path.basename(track)}")
        try:
            run_batch_one_analyze(track, staging_path)
            sys.exit(0)
        except Exception as e:
            print(f"  ✗ batch-one-analyze failed: {e}", file=sys.stderr)
            try:
                _aggressive_memory_cleanup()
            except Exception:
                pass
            sys.exit(1)

    if len(sys.argv) >= 3 and sys.argv[1] == "--batch-one-finish":
        staging_path = sys.argv[2]
        print(f"  [batch-one-finish] {os.path.basename(staging_path)}")
        try:
            run_batch_one_finish(staging_path)
            sys.exit(0)
        except Exception as e:
            print(f"  ✗ batch-one-finish failed: {e}", file=sys.stderr)
            try:
                _aggressive_memory_cleanup()
            except Exception:
                pass
            sys.exit(1)

    main()
